window.NOTES=window.NOTES||{};window.NOTES["history"]=[{"unit":1,"part":"臺灣史","title":"史前文化與臺灣原住民","summary":"學習歷史事實與解釋、歷史分期與四種紀年，臺灣舊石器、新石器、金屬器三期史前文化，以及原住民的南島語族起源、傳說與名稱演變；會考常以出土器物判斷時代（同一文化層看最晚出現者）、文化層上下順序、遺址地點與紀年換算出題。","sections":[{"heading":"歷史事實、紀錄與解釋","points":["歷史事實：過去確實發生過的事件，較客觀，不因時間或價值觀改變","歷史紀錄：以遺物、遺址或文字保存、記錄歷史事實，如《馬關條約》條文","歷史解釋：後人對歷史事實的詮釋、評論，較主觀，會因立場不同而產生差異","判斷訣竅：句中出現「精美、重要、滿懷理想、高超」等評價字眼多屬歷史解釋"],"example":"「甲午戰爭後清帝國將臺灣割讓日本」是事實；「臺灣在日本統治下走向文明」是解釋。"},{"heading":"歷史分期與紀年","points":["依文字有無分期：文字發明前為史前時代（口述、圖畫），之後為歷史時代（文字記錄較可信）","中國歷史常以朝代更迭分期，如宋、元、明、清","干支紀年：天干地支配對，60年一循環稱一甲子，如甲午戰爭、戊戌變法","帝王紀年：以帝王在位年次或年號紀年，如秦始皇26年、日本明治、昭和、令和","西元紀年：與耶穌誕生有關、今日國際通用，100年為一世紀","民國紀年：以1912年為民國元年；民國年＋1911＝西元年"],"example":"民國113年＋1911＝西元2024年；「光緒丁亥年」同時用了帝王紀年與干支紀年。","fig":{"src":"../assets/fig/history/u1-s2.svg","cap":"紀年方式的比較（以西元 1 年與 1912 年為例）"}},{"heading":"舊石器時代：長濱文化","points":["史前文化依器物材質與製作技術分為舊石器、新石器、金屬器時代","舊石器時代約距今5萬～5千年前：使用打製石器、已知用火、以採集漁獵維生","代表長濱文化（臺東縣長濱鄉），是目前臺灣發現最早的史前文化，住在天然洞穴","文化層：愈下方的文化層年代愈早，可依上下堆疊判斷時代先後"],"example":"看到「打製石器＋住洞穴＋採集漁獵＋臺灣東部」→長濱文化。"},{"heading":"新石器時代：大坌坑、圓山、卑南文化","points":["新石器時代約距今7千～2千年前：從採食到產食，文化快速發展","新石器時代特色：磨製石器、燒製陶器，開始農耕與飼養家畜，食物來源較穩定","早期代表大坌坑文化（新北市八里）：出土繩紋陶，也被視為最早的南島語族","晚期代表圓山文化（臺北市中山區）：出土大量貝塚","晚期代表卑南文化（臺東市）：出土石板棺與陪葬玉器","臺南南關里遺址出土碳化稻米，是臺灣目前最早的稻米遺跡","南投曲冰遺址是臺灣首次在高山地區發現的史前聚落：出土陶器、石板棺、石屋礎石，近卑南文化","嘉義太保農場遺址：出土繩紋陶、貝塚","各地出土相似玉器，東南亞亦有發現，顯示島內外已有交流","臺北捷運植物園站遺址由上而下：表土、十三行、植物園、圓山、訊塘埔五個文化層","植物園文化層出土陶器、磨製石器，屬新石器時代","同一文化層出土多種器物時，以最晚出現的特色判斷所屬時代"],"example":"記法：北部「大坌坑繩紋陶、圓山貝塚」，東部「卑南石板棺配玉器」。","fig":{"src":"../assets/fig/history/u1-s4.svg","cap":"臺灣重要的史前文化遺址"}},{"heading":"金屬器時代：十三行文化","points":["金屬器時代約距今2千～4百年前：已知煉鐵、使用金屬工具","代表十三行文化（新北市八里）：農業為主、漁獵為輔；出土煉鐵爐、鐵渣等鐵製工具遺跡","十三行出土玻璃珠、玻璃手環、瑪瑙手環與珠飾、中國銅錢等外來物→與東南亞或中國大陸已有貿易往來","南部蔦松文化、中部番仔園文化也屬金屬器時代，出土鐵器與外來物品","高雄內惟小溪貝塚遺址：出土鐵鎗頭、鐵鋤、銅錢幣、玻璃環，屬金屬器時代","宜蘭淇武蘭遺址下文化層距今約1,300～800年前：出土鐵刀、珠飾及金屬線編成的魚形裝飾品，屬金屬器時代"],"example":"看到「鐵器、煉鐵爐、玻璃環、瑪瑙、對外貿易」→金屬器時代，北部就是十三行。"},{"heading":"原住民的起源與傳說","points":["臺灣原住民屬南島語族，語言與東南亞、大洋洲原住民相近","南島語族分布於太平洋和印度洋：北起臺灣（分布範圍最北端）、南抵紐西蘭、東達復活節島、西到馬達加斯加","臺灣可能是南島語族向外遷徙的起點（構樹DNA研究可佐證）","嚼食檳榔是南島語族文化的重要因素；新石器遺址曾發現帶檳榔漬痕的牙齒遺骸","原住民沒有文字，靠口耳相傳形成傳說，可推測族群起源、遷徙與生活調適","族群起源傳說：泰雅族岩石始祖、排灣族蛇生始祖","族群遷徙傳說：邵族逐白鹿到日月潭；阿美族、布農族、西拉雅族洪水避難傳說"],"example":"泰雅族大霸尖山巨石裂開走出始祖、排灣族蛇生始祖→起源傳說；布農族巨蛇堵溪、螃蟹剪蛇→洪水傳說。","fig":{"src":"../assets/fig/history/u1-s6.svg","cap":"南島語族的分布範圍（示意）"}},{"heading":"原住民的名稱演變與分布","points":["清帝國依是否歸順（納稅、服勞役）分為熟番、生番","日治時期依居住地區分為平埔族、高砂族（1935年改稱）","戰後中華民國稱高山族為山地同胞，平埔族因漢化深未被視為原住民","民國83年（1994年8月1日）修憲將山地同胞正名、統稱「原住民」；每年8月1日定為原住民族日","民國86年修憲改稱「原住民族」；今政府認定16族","平埔族群：分布西部與東北部平原、丘陵，與漢人接觸早、漢化較深，逐漸融入漢人社會","平埔族群代表：西拉雅、凱達格蘭、噶瑪蘭","高山各族：分布山區、東部、蘭嶼，與漢人接觸晚，保有不少原有文化、傳統文化保存較完整；代表邵、排灣、賽夏","今東部以阿美族為大宗，北部多為泰雅族"],"example":"口訣「清看納稅（熟／生番）、日看住地（平埔／高砂）、戰後山地同胞、民國80年代正名原住民族」。","fig":{"src":"../assets/fig/history/u1-s7.svg","cap":"臺灣原住民族的分布（政府認定 16 族，示意）"}}],"confusions":[{"a":"歷史事實","b":"歷史解釋","diff":"事實是客觀發生過的事；解釋是後人帶有評價、立場的詮釋","tip":"有形容詞評價（精美、偉大、理想、高超）就是解釋"},{"a":"干支紀年","b":"帝王紀年","diff":"干支以天干地支配對、60年循環；帝王以帝王在位年次或年號紀年","tip":"甲子、丁亥→干支；光緒、明治、昭和→帝王"},{"a":"大坌坑文化","b":"十三行文化","diff":"都在新北市八里，但大坌坑屬新石器時代早期（繩紋陶），十三行屬金屬器時代（煉鐵、對外貿易）","tip":"看陶器還是鐵器"},{"a":"長濱文化","b":"卑南文化","diff":"都在臺東，長濱為舊石器時代打製石器、住洞穴；卑南為新石器時代石板棺、玉器","tip":"打製＝長濱，玉器石板棺＝卑南"},{"a":"熟番／生番","b":"平埔族／高砂族","diff":"前者是清帝國依是否歸順納稅分類；後者是日治時期依居住地區分類","tip":"清看納稅，日看住地"},{"a":"起源傳說","b":"遷徙（洪水）傳說","diff":"起源傳說講族人如何誕生、部落形成；遷徙傳說講遭洪水等天災而遷居","tip":"岩石生人、蛇生始祖→起源；洪水漂流、避居高山、逐白鹿→遷徙"}],"terms":[{"term":"史前時代","def":"文字發明以前的時代，人類以口述、圖畫等方式記錄事件，需靠遺址與器物了解生活。"},{"term":"歷史時代","def":"人類開始以文字記錄發生的事件之後的時代，留下較可信、明確的資料。"},{"term":"干支紀年","def":"以十天干與十二地支配對紀年，始於甲子終於癸亥，60年循環一次稱一甲子。"},{"term":"帝王紀年","def":"以帝王在位年次或其使用的年號紀年，用於部分君主制國家，如日本明治、昭和。"},{"term":"西元紀年","def":"又稱公元紀年，以傳統認為耶穌誕生之年為元年，今日國際通用，100年為一世紀。"},{"term":"民國紀年","def":"以中華民國成立的西元1912年為民國元年，民國年加1911即為西元年。"},{"term":"文化層","def":"不同時期遺址在地層中堆積形成的層次，通常愈下方的文化層年代愈早。"},{"term":"灰坑","def":"考古學名詞，指古代人類堆積廢棄物品的凹坑，可據以了解當時生活。"},{"term":"長濱文化","def":"臺灣發現最早的史前文化，屬舊石器時代，位於臺東長濱，使用打製石器、已知用火。"},{"term":"大坌坑文化","def":"新石器時代早期代表，位於新北八里，出土繩紋陶，被視為最早的南島語族文化。"},{"term":"圓山文化","def":"新石器時代晚期文化，位於臺北市中山區，以出土大量貝塚聞名。"},{"term":"卑南文化","def":"新石器時代晚期文化，位於臺東市，出土大量石板棺與作為陪葬品的玉器。"},{"term":"十三行文化","def":"金屬器時代代表，位於新北八里，已知煉鐵，出土玻璃珠、瑪瑙等外來物，顯示對外貿易。"},{"term":"南島語族","def":"語言同屬南島語系的族群，分布北起臺灣、南抵紐西蘭、東達復活節島、西到馬達加斯加。"},{"term":"洪水傳說","def":"原住民關於洪水氾濫、漂流避難的傳說，反映曾遭天災而被迫遷徙，如阿美族、布農族。"},{"term":"熟番、生番","def":"清帝國依原住民是否歸順、納稅服勞役所作的分類，歸順者為熟番，未歸順者為生番。"},{"term":"平埔族","def":"分布西部與東北部平原、丘陵的原住民，與漢人接觸早、漢化較深，日治時期起有此稱呼。"},{"term":"阿立祖","def":"南臺灣平埔族西拉雅族祭祀的祖靈，祭祀時以檳榔等為祭品。"},{"term":"高砂族","def":"日治時期對居住山區等地原住民的稱呼（1935年由生番改稱），戰後改稱山地同胞。"},{"term":"原住民族","def":"民國83年（1994）修憲將山地同胞正名為原住民，民國86年修憲改稱原住民族，今政府認定16族。"}],"timeline":[{"time":"距今約5萬～5千年前","event":"舊石器時代：長濱文化，使用打製石器、已知用火、採集漁獵"},{"time":"距今約7千年前","event":"進入新石器時代：大坌坑文化出現，燒製繩紋陶、開始農耕"},{"time":"距今約4千年前","event":"南島語族自臺灣出航，向菲律賓等地擴散"},{"time":"新石器時代晚期","event":"圓山文化（貝塚）、卑南文化（石板棺、玉器）發展"},{"time":"距今約2千年前","event":"進入金屬器時代：十三行文化已知煉鐵並對外貿易"},{"time":"距今約1,300～800年前","event":"宜蘭淇武蘭遺址下文化層，屬金屬器時代（鐵刀、珠飾）"},{"time":"16世紀起","event":"歐洲人陸續來到東亞，臺灣結束史前時代進入大航海時代"},{"time":"清帝國時期","event":"依是否歸順納稅，將原住民分為熟番、生番"},{"time":"1912","event":"中華民國成立，為民國紀年元年"},{"time":"1935","event":"日治時期將生番改稱高砂族、熟番改稱平埔族"},{"time":"戰後","event":"中華民國政府稱高山族為山地同胞，平埔族未被視為原住民"},{"time":"1994（民國83年）","event":"8月1日修憲將山地同胞正名，統稱為「原住民」（8月1日定為原住民族日）"},{"time":"1997（民國86年）","event":"修憲改稱「原住民族」"},{"time":"2023","event":"中央政府認定原住民族共16族"}],"sources":[{"name":"卑南遺址人獸形玉玦","gist":"以花蓮豐田臺灣玉製成，形式相似玉器亦見於東南亞遺址。","clue":"玉器、石板棺、臺東→卑南文化；東南亞也有→與島外交流"},{"name":"構樹DNA研究","gist":"太平洋諸島構樹多為雌株且與臺灣南部構樹相同，推論由臺灣帶出。","clue":"構樹、語族擴張起點→南島語族源自臺灣"},{"name":"泰雅族大霸尖山岩石始祖傳說","gist":"神鳥在巨石前啼叫，巨石裂開走出一男一女，成為泰雅族祖先。","clue":"岩石生人、始祖→起源傳說；大霸尖山→北部山區泰雅族"},{"name":"排灣族蛇生始祖傳說","gist":"排灣族傳說祖先由百步蛇所生，說明族群的由來。","clue":"蛇生祖先→起源傳說，屬排灣族"},{"name":"布農族洪水傳說","gist":"巨蛇堵塞溪水造成洪水，族人遷至玉山避難，螃蟹剪斷巨蛇後洪水退去。","clue":"洪水、避居高山→遷徙傳說，反映天災迫使部落遷徙"},{"name":"族譜紀年（光緒丁亥年、昭和丁丑年）","gist":"族譜以年號加干支記錄出生與死亡時間。","clue":"年號＝帝王紀年；天干地支＝干支紀年"}]},{"unit":2,"part":"臺灣史","title":"大航海時代的臺灣","summary":"認識16～17世紀東亞海域的漢人海商、日本人與歐洲勢力，以及荷蘭、西班牙、鄭氏政權先後在臺灣的統治與經濟活動，和原住民受到的衝擊。會考多以史料、書信、地圖判讀「是哪個政權、哪個時期、在哪裡」。","sections":[{"heading":"東亞海域的各方勢力","points":["12、13世紀漢人已在澎湖活動；14世紀後期（末）明帝國為防範倭寇實施海禁","海禁下部分商人違禁走私，形成配有武力、亦盜亦商的海商集團，澎湖成為走私據點","16世紀後期海禁鬆弛，明朝駐軍澎湖，海商轉往臺灣；顏思齊、鄭芝龍招募漢人開墾雲林、嘉義一帶","鄭芝龍接受明帝國招降後，壟斷中國對外貿易，成為東亞海域霸主","日本人稱臺灣為「高砂」「高山國」，曾遣使要求納貢未成；1633年起鎖國，僅准中國、荷蘭船隻至長崎貿易","15世紀末葡萄牙人開闢通往亞洲新航路，歐洲人為貿易與傳教陸續東來；航經臺灣的歐洲人稱臺灣為「福爾摩沙」","歐洲人貿易對象為中國、日本：中國絲織品（絲綢）、瓷器、茶葉，南洋香料，日本工藝品","葡萄牙據澳門；西班牙據菲律賓馬尼拉，1565年開闢馬尼拉—阿卡普爾科跨太平洋航線","西班牙以美洲白銀換取中國絲綢，當時明朝正發生銀荒","荷蘭聯合東印度公司（VOC）獲荷蘭政府授予獨占海外貿易特權，亞洲總部設於巴達維亞（今雅加達）"],"example":"記據點：葡—澳門、西—馬尼拉、荷—巴達維亞；北港有「顏思齊先生開拓臺灣登陸紀念碑」。","fig":{"src":"../assets/fig/history/u2-s1.svg","cap":"17 世紀東亞海域的各方勢力"}},{"heading":"荷、西在臺灣的競爭","points":["荷蘭人曾占澎湖，遭明將沈有容驅逐，1624年轉往大員","澎湖天后宮「沈有容諭退紅毛番韋麻郎等」碑，是臺灣現存年代最早的石碑","荷蘭（1624～1662）以大員為中心占南部：熱蘭遮城在大員（今安平古堡）為行政中心，鄭氏改稱安平城","熱蘭遮城（海陸之城）最初以木板、砂土修築，名「奧倫治城」，1634年以磚石擴建完成","普羅民遮城在赤崁（今赤崁樓）為商業中心（商業市街）","西班牙（1626～1642）為與荷蘭競爭航路、就近對日貿易，自馬尼拉北上占雞籠、淡水、蛤仔難，傳天主教","西班牙在雞籠（今和平島）建聖薩爾瓦多城、在淡水建聖多明哥城","荷蘭入臺前日商已在臺活動；1633年日本鎖國後日商退出，荷蘭對日貿易不受影響","日本鎖國使西班牙對日貿易受挫而減少駐軍，淡水、雞籠漸失轉口貿易功能","1642年荷蘭人北上驅逐西班牙人，勢力擴及北臺灣；淡水聖多明哥城被荷人重建，俗稱「紅毛城」","荷蘭占臺順序：澎湖→臺灣南部→臺灣北部","政權結束：西班牙因日本鎖國後荷蘭人出兵、荷蘭因鄭成功攻臺、鄭氏因施琅攻臺","重要年代：1624荷占南臺、1626西占北臺、1633日本鎖國、1642西退出、1662荷退出、1683施琅攻臺"],"example":"書信「致雞籠島要塞長官／致大員長官」＋天主教 vs 基督教 → 西班牙與荷蘭對抗。","fig":{"src":"../assets/fig/history/u2-s2.svg","cap":"荷蘭與西班牙在臺灣的據點與競爭"}},{"heading":"荷蘭人治臺","points":["由荷蘭聯合東印度公司治理，以臺灣長官為在臺最高領導人、熱蘭遮城為中心，管理原住民並發展國際貿易","對漢人管制嚴苛、徵收重稅；1652年郭懷一不滿重稅在赤崁一帶起事，荷蘭人在新港社等原住民協助下平定","為增加稻米、蔗糖產量，引進耕牛（黃牛）並鼓勵漢人移墾，招募中國東南沿海漢人來臺開墾","引進番茄、釋迦、荷蘭豆等新作物，以甘蔗（製糖）為主","向原住民購買赤崁土地建普羅民遮市街，招募漢人開墾，開啟臺南糖業；新式製糖業興起前臺南蔗糖產量約占全臺半數","以臺灣為國際貿易轉運站，連結中國、日本、巴達維亞，再透過VOC船隊將貿易延伸到全球","輸出蔗糖、鹿皮（稻米有餘才外銷）；轉運中國絲綢瓷器（絲織品）與東南亞香料至日本、巴達維亞，自日本換回白銀","1635～1640年荷蘭輸日生絲及絲織品87.5%由臺灣轉運；1661年鄭成功攻臺後降至8%，對日貿易受挫","與日商因課稅問題衝突：理加頭目赴日求援、日人挾持臺灣長官，幕府一度關閉荷蘭商館","與鄭芝龍等漢人海商既合作又競爭"],"example":"「臺灣真是公司的一頭好乳牛」——荷蘭長官形容轉口貿易帶來巨額利潤。"},{"heading":"鄭氏政權治臺","points":["明朝滅亡後鄭芝龍降清，其子鄭成功擁護南明，受封延平王","鄭成功獲南明賜姓朱，人稱「國姓爺」；荷蘭人誤以為是名字而稱他Koxinga","鄭成功不願降清，以東南沿海為根據地反清復明；1661年自鹿耳門登陸攻荷","鄭成功圍熱蘭遮城時，荷蘭總部派卡烏率11艘船艦救援未果，卡烏轉赴福州商討與清結盟","荷蘭長官揆一被圍兩百多日後投降，1662年荷蘭人議和退出臺灣","設承天府（今臺南市）為行政中心，建立臺灣首個漢人政權","鄭成功病逝後鄭經繼位，陳永華輔佐鄭經積極推展國際貿易與文教，建臺灣首座孔廟、推行儒家文化","陳永華將漢人典章制度移植臺灣，奠定漢文化在臺基礎","為解決糧食不足實施「寓兵於農」的軍屯，以承天府為中心向南北拓墾，留下左營、前鎮、新營等地名","荷蘭人曾闢建鹽田失敗；清帝國海禁下鄭氏須確保食鹽供應，臺灣開始發展天日曬鹽","清帝國實施海禁封鎖鄭氏；鄭氏貿易對象：中國（走私取得商品）、日本、東南亞（菲律賓）、英國","鄭氏貿易：輸出蔗糖、鹿皮；轉口瓷器、絲織品、香料；輸入軍需品（軍用物資）、日常用品","鄭氏與英國通商，自英國商人輸入軍用物資、布料","1683年清廷派施琅攻臺，鄭克塽兵敗投降，清帝國1684年將臺灣納入版圖","日治時期臺南的開山神社即今延平郡王祠，主祭鄭成功；1930年臺南舉辦文化三百年紀念會"],"example":"「國姓爺」＝鄭成功；「出口沒有稻米、進口有軍需品」是鄭氏貿易的判讀關鍵。","fig":{"src":"../assets/fig/history/u2-s4.svg","cap":"鄭氏時期臺灣的貿易（示意）"}},{"heading":"原住民與外來者的互動","points":["早期原住民以漁獵、游耕為生，鹿皮是與外來者交易的重要商品；中部有部落聯盟大肚王國","荷蘭對原住民：先以武力征服（如聯合新港社攻打麻豆社），再與各社結盟避免聯合反抗，也結盟壓制敵對者","新港社為荷蘭盟友，麻豆社之役與郭懷一事件皆協助荷蘭","荷蘭定期舉行地方會議，授予長老權杖，透過長老間接統治","部落長老權力移轉與繼承須經荷蘭人許可，提升對原住民部落的控制","地方會議分淡水、北路、南路、東部會議區；先鳴槍、鳴禮炮，確認長老留任或撤換並授權杖，再招待用餐","荷蘭人曾出兵攻擊中部的大肚王國，1645年大肚王歸順荷蘭","荷蘭在統治範圍內設教堂與學校傳基督教，部分原住民接受基督教信仰","荷蘭傳教士以羅馬字母拼寫西拉雅族新港社語言（新港文）傳教","清代原住民仍以新港文與漢人訂土地契約；相關文獻以新港社最多，故稱新港文書（番仔契）","西拉雅族運用荷蘭傳教士以羅馬拼音記錄的族語聖經推動語言復興；西拉雅國家風景區是第一個以人文命名的國家風景區","荷蘭透過漢人與原住民交易取得鹿皮；大量捕鹿使鹿隻銳減，梅花鹿數量逐漸減少，原住民減少狩獵、改以耕種為主","荷蘭與清代文獻記載南臺灣平埔族以檳榔象徵土地轉讓、婚姻往來與祭祀「阿立祖」","西班牙以武力降服雞籠、淡水原住民並加以安撫、傳天主教；不少原住民能說西班牙語（如凱達格蘭族的馬賽人）","西班牙留下三貂角等地名；日本鎖國後臺灣北部失去據點功能，西班牙對北臺重視降低，傳教成果不如荷蘭人","西班牙影響有限，離臺後天主教信仰迅速消失","鄭氏在部落設學校教儒家文化，原住民在鄭氏設立的部落學校接觸儒家文化，基督教文化逐漸衰退","漢人屯墾壓縮原住民生活空間，與中部大肚王國衝突最激烈，後被鄭氏鎮壓式微","鄭氏時期大肚王族群遭鄭軍討伐，部分族人遷往埔里、水里一帶；鄭氏徵召原住民搬運糧食也引發反抗","原住民學習漢人農耕技術，部分向漢人學會水田耕作而定居農耕；外來政權統治範圍外的原住民各族仍維持原有生活"],"example":"「新港社＋羅馬字＋地方會議」→荷蘭；「天主教＋雞籠淡水」→西班牙；「屯墾侵害大肚王國」→鄭氏。"}],"confusions":[{"a":"明帝國海禁","b":"清帝國海禁","diff":"明代海禁（14世紀起）為防範倭寇；清代海禁（17世紀後期，翰林作17世紀中期）為封鎖鄭氏政權的經濟來源。","tip":"明防倭寇、清鎖鄭氏"},{"a":"明清海禁","b":"日本鎖國","diff":"明朝海禁（14世紀後期起）防倭寇、清朝海禁（17世紀中期）封鎖鄭氏；日本鎖國（17世紀前期）為減少西方文化傳入後的衝突","tip":"海禁是中國管自己人出海；鎖國是日本擋外人，只准荷蘭、中國船到長崎"},{"a":"荷蘭人","b":"西班牙人","diff":"荷蘭據臺灣南部（1624～1662）、總部巴達維亞、傳基督教；西班牙據臺灣北部（1626～1642）、總部馬尼拉、傳天主教。","tip":"南荷北西；基督荷、天主西；巴達維亞荷、馬尼拉西"},{"a":"日本鎖國的影響","b":"鄭成功攻臺的影響","diff":"日本鎖國（1630年代）使西班牙對日貿易受挫而減少在臺駐軍；鄭成功攻臺（1661～1662）使荷蘭人退出臺灣。","tip":"鎖國→西班牙撤兵；國姓爺→荷蘭離臺"},{"a":"荷蘭、西班牙占臺目的","b":"鄭氏占臺目的","diff":"荷蘭為取得貿易據點、西班牙作為對日貿易基地；鄭氏作為反清復明基地","tip":"歐洲人為貿易，鄭氏為反清"},{"a":"荷治時期貿易","b":"鄭氏時期貿易","diff":"荷蘭出口蔗糖、鹿皮（及有餘的稻米），以轉口貿易獲利；鄭氏稻米只供內需，出口蔗糖鹿皮、進口軍需品，並與英國通商、對中國走私。","tip":"看到軍需品、英國、走私→鄭氏"},{"a":"三角貿易","b":"轉口貿易","diff":"三角貿易是貿易商接單後向第三方購買，由賣方直接運給買方；轉口（中轉）貿易是貨物經中轉國轉運，買賣雙方不直接交易","tip":"荷蘭以臺灣轉運中國絲瓷、南洋香料→轉口貿易"},{"a":"地方會議（荷蘭）","b":"設學校教儒家（鄭氏）","diff":"荷蘭召集長老宣誓效忠並授權杖以間接統治；鄭氏在部落設學校傳播儒家文化，使基督教文化衰退。","tip":"權杖→荷蘭；孔廟儒學→鄭氏"},{"a":"新港文","b":"新港文書","diff":"新港文是荷蘭傳教士用羅馬字母拼寫新港社語言所創的文字；新港文書是清代西拉雅族以新港文與漢人簽訂的土地契約（番仔契）。","tip":"荷蘭時期創文字，清代留契約"}],"terms":[{"term":"海禁","def":"明清時期禁止人民私自出海貿易的政策；明代為防倭寇，清代為封鎖鄭氏政權的經濟來源。"},{"term":"倭寇","def":"活躍於中國東南沿海、臺灣等地的海盜集團，明帝國為防範其侵擾而實施海禁。"},{"term":"大航海時代","def":"15世紀末起歐洲人開闢新航路，為貿易與傳教來到亞洲、美洲，形成全球經貿網絡的時代。"},{"term":"福爾摩沙","def":"大航海時代航經臺灣的歐洲人對臺灣的稱呼，意為美麗之島。"},{"term":"荷蘭聯合東印度公司","def":"荷蘭特許經營亞洲貿易的公司（VOC），總部設於巴達維亞，1624～1662年統治臺灣。"},{"term":"巴達維亞","def":"今印尼雅加達，荷蘭聯合東印度公司在亞洲的總部，就近掌握東印度群島的香料貿易。"},{"term":"熱蘭遮城","def":"荷蘭人在大員（今臺南安平）興建的城堡，為荷治時期政治中心；初名奧倫治城，1634年磚石擴建完成，鄭氏改稱安平城，今安平古堡。"},{"term":"普羅民遮城","def":"荷蘭人在赤崁興建的城堡，為商業中心，今赤崁樓一帶。"},{"term":"聖薩爾瓦多城","def":"西班牙人1626年占領雞籠後，在今基隆和平島興建的城堡，1642年被荷蘭人攻下。"},{"term":"聖多明哥城","def":"西班牙人在淡水興建的城堡，撤離時拆毀，荷蘭人在附近重建，俗稱「紅毛城」。"},{"term":"鎖國","def":"日本江戶幕府1630年代起禁止人民出海、限制外國人，僅准中國與荷蘭船隻至長崎貿易。"},{"term":"郭懷一事件","def":"1652年漢人郭懷一因不滿荷蘭人徵收重稅，在赤崁一帶起事，被荷蘭人聯合原住民平定。"},{"term":"轉口貿易","def":"又稱中轉貿易，貨物經中轉地轉運，買賣雙方不直接交易；荷蘭、鄭氏皆以臺灣從事轉口貿易。"},{"term":"承天府","def":"鄭成功驅逐荷蘭人後所設的行政中心，位於今臺南市，建立臺灣首個漢人政權。"},{"term":"軍屯（寓兵於農）","def":"鄭氏政權為解決糧食不足，令軍隊在駐紮地自耕自食，平日務農、戰時出戰。"},{"term":"陳永華","def":"輔佐鄭經的重要人物，提倡文教，在承天府建立臺灣第一座孔廟，奠定漢文化在臺基礎。"},{"term":"施琅","def":"清帝國將領，1683年率軍攻臺，鄭克塽兵敗投降，結束鄭氏政權的統治。"},{"term":"地方會議","def":"荷蘭人定期召集各社長老宣誓效忠、報告部落狀況，並授予權杖，以間接統治原住民部落。"},{"term":"新港文","def":"荷蘭傳教士以羅馬字母拼寫西拉雅族新港社語言所創的文字，用以教導原住民閱讀《聖經》。"},{"term":"新港文書","def":"清代西拉雅族仍以新港文與漢人簽訂的土地買賣契約，多為漢文與新港文雙語，俗稱「番仔契」。"},{"term":"大肚王國","def":"17世紀臺灣中部的部落聯盟，曾與荷蘭人衝突而臣服，後因鄭氏屯墾侵害領域而遭征伐衰微。"}],"timeline":[{"time":"12～13世紀","event":"漢人已在澎湖活動"},{"time":"14世紀末","event":"明帝國為防範倭寇實施海禁，海商開始到澎湖、臺灣走私"},{"time":"15世紀末","event":"葡萄牙人開闢通往亞洲的新航路，開啟大航海時代"},{"time":"16世紀","event":"葡萄牙據澳門、西班牙據馬尼拉（1571）；明帝國駐軍澎湖，海商轉往臺灣"},{"time":"1565","event":"西班牙開闢馬尼拉—阿卡普爾科跨太平洋航線，以美洲白銀換中國絲綢"},{"time":"17世紀初","event":"荷蘭人占領澎湖，遭明將沈有容驅逐；顏思齊、鄭芝龍招募漢人開墾雲林、嘉義"},{"time":"1619","event":"荷蘭聯合東印度公司在巴達維亞設立亞洲總部"},{"time":"1624","event":"荷蘭人自大員登陸，占領臺灣南部，建熱蘭遮城"},{"time":"1626","event":"西班牙人自馬尼拉北上，占領雞籠、淡水等臺灣北部地區"},{"time":"1630年代","event":"日本鎖國（1633），西班牙對日貿易受挫而減少在臺駐軍"},{"time":"1634","event":"熱蘭遮城以磚石擴建完成"},{"time":"1635～1636","event":"荷蘭人聯合新港社攻打麻豆社，確立在臺灣南部的統治地位"},{"time":"1642","event":"荷蘭人北上驅逐西班牙人，統治範圍擴及北臺灣"},{"time":"1645","event":"大肚王歸順荷蘭"},{"time":"1652","event":"郭懷一不滿荷蘭重稅起事，遭荷蘭人聯合原住民平定"},{"time":"1661","event":"鄭成功自鹿耳門登陸，圍攻熱蘭遮城"},{"time":"1662","event":"荷蘭人與鄭成功議和退出臺灣，鄭氏設承天府"},{"time":"1665","event":"陳永華輔佐鄭經，建臺灣第一座孔廟（臺南孔廟）"},{"time":"1670","event":"鄭經與英國東印度公司通商，允許英國在臺設商館；鄭氏軍隊攻打大肚王國"},{"time":"1675","event":"《被遺誤的臺灣》出版，批評荷蘭評議會決策失當致失去臺灣"},{"time":"1683","event":"清廷派施琅攻臺，鄭克塽兵敗投降，鄭氏政權結束"},{"time":"1684","event":"清帝國將臺灣納入版圖，並解除沿海海禁"}],"sources":[{"name":"《巴達維亞城日記》","gist":"荷蘭聯合東印度公司巴達維亞總部的紀錄；1624年2月載大員、蕭壠一帶多產檳榔子、香蕉。","clue":"巴達維亞、大員、我方建城→荷蘭聯合東印度公司"},{"name":"熱蘭遮城日誌","gist":"荷蘭聯合東印度公司在臺的官方紀錄，記載地方會議、貿易、郭懷一事件等。","clue":"赤崁、長官、公司、各社酋長、授予權杖（藤杖）→荷治時期"},{"name":"西班牙傳教士北臺灣報告","gist":"1630年代傳教士記錄三貂（聖地牙哥）、噶瑪蘭四十多個聚落與蘇澳（聖．羅倫索）的原住民情形。","clue":"北臺灣、噶瑪蘭、西班牙式聖名地名→西班牙"},{"name":"荷西交戰書信","gist":"荷蘭大員長官致書雞籠要塞長官勸降，西班牙長官以天主教徒身分拒絕交出聖薩爾瓦多城。","clue":"雞籠、大員、天主教徒、聖薩爾瓦多城→1642年荷西之戰"},{"name":"17世紀荷蘭文、新港文對照《聖經》","gist":"荷蘭傳教士以羅馬字母拼寫西拉雅語，將《馬太福音》譯成新港文，與荷蘭文雙語對照。","clue":"羅馬字母＋荷蘭文對照＋聖經→荷蘭傳教、新港文"},{"name":"鄭成功致荷蘭長官勸降書","gist":"鄭成功稱臺灣為中國之土地，要求困守城中的荷蘭人獻城投降。","clue":"困守城中、遠渡重洋經營臺島、「地當歸我」、國姓爺→1661年圍攻熱蘭遮城"},{"name":"《臺灣外記》大肚王阿德狗讓事件","gist":"鄭氏部將屯墾北路時欺凌大肚社人，大肚王領導反抗遭鄭成功鎮壓。","clue":"順治年號、屯墾、大肚社→鄭氏屯墾侵害原住民領域"},{"name":"《被遺誤的臺灣》","gist":"1675年出版，為荷蘭末代臺灣長官揆一一方的辯護，批評評議會決策失當，終致失去臺灣。","clue":"末代長官、評議會、失去臺灣→荷蘭被鄭成功逐出臺灣"},{"name":"清帝國致鄭氏書信","gist":"清方要求鄭氏「薙髮留辮」登岸投降，鄭方以據有臺灣可進可退拒絕。","clue":"薙髮留辮→清帝國；金門、廈門、今領有臺灣→鄭氏政權"},{"name":"《諸羅縣志》半線營盤記載","gist":"記載鄭氏將領劉國軒帶兵駐紮半線（今彰化），設立營盤開發當地。","clue":"偽將、帶兵駐紮、營盤→鄭氏寓兵於農的軍屯"},{"name":"新港文書（番仔契）","gist":"清代西拉雅族以羅馬字母拼寫的新港文與漢人簽訂的土地契約，常為雙語並標清朝年號。","clue":"羅馬字母、西拉雅族、新港社＋清朝年號（雍正、乾隆、嘉慶）"}]},{"unit":3,"part":"臺灣史","title":"清帝國時期的臺灣","summary":"學習清帝國治臺由「為防臺而治臺」轉向積極建設的過程，以及對渡貿易到開港通商的經濟變化、漢人移墾社會的衝突與文化發展、原住民的處境。會考常以史料、地圖與統計圖判讀時代、比較開港前後差異，並考牡丹社事件、清法戰爭帶來的政策轉變。","sections":[{"heading":"清帝國前期的消極治臺與行政區劃","points":["1683年施琅攻臺，鄭氏降清；清廷出現棄臺論：臺灣小而無用、管理不易、非固有領土、增加財政負擔","施琅以土地肥沃、物產豐富、戰略地位重要力主保留，1684年納入版圖，設臺灣府隸屬福建省","清帝國在西部陸疆積極進取，海疆政策則圍繞「禁」與「防」，故對臺消極，採「為防臺而治臺」，防止臺灣再成反清基地","清初三禁令：海禁政策（清初～1684，打擊鄭氏）、渡臺禁令（1684～1875）、劃界封山（1722～1875）","渡臺禁令：須申請證照、不准攜眷；劃界封山：在近山立番界（土牛、土牛溝），禁止漢人越界，隔離漢人與原住民","禁令影響：海禁使走私貿易興起；渡臺禁令使偷渡興盛、男女（性別）比例失衡，出現單身無業的「羅漢腳」，成為治安隱憂","劃界封山下侵墾興盛，漢人仍常越界開墾，番界逐漸往山區移動","清初耶穌會傳教士測繪的地圖只畫出臺灣西半部，反映番界以東未受官方實質控制","行政區劃隨開發由南向北、由西向東擴展（中南部平原→北部→東北部）；調整原因：受民變與外力入侵刺激，基於治安與國防需求","康熙一府三縣→雍正5年（1727）一府四縣二廳：朱一貴事件後增設彰化縣、淡水廳（1723），並設澎湖廳","林爽文事件後諸羅縣改名嘉義縣；嘉慶17年（1812）因吳沙率眾拓墾蛤仔難、原漢衝突及海盜侵擾，增設噶瑪蘭廳（今宜蘭）","嘉慶一府四縣三廳→沈葆楨時期（1875）二府八縣四廳，增設臺北府、恆春縣→劉銘傳時期（1887）三府十一縣三廳一直隸州","臺灣人口：1811年約24.7萬戶、194萬人；1893年約50萬戶、255萬人"],"example":"康熙時只有臺灣府轄臺灣、鳳山、諸羅三縣，所以大臺北的墾號要向諸羅縣申請墾照。","fig":{"src":"../assets/fig/history/u3-s1.svg","cap":"清帝國時期臺灣行政區劃的演變（示意）"}},{"heading":"外力衝擊與積極治臺","points":["1858年英法聯軍之役清帝國戰敗簽訂條約，臺灣於1860年代開港通商，重新接觸外國勢力","牡丹社事件起因：1871年琉球（宮古島）漁民漂流至恆春遭原住民殺害","1874年5月日本出兵，日軍由社寮港登陸，攻打牡丹社、高士佛社等部落，即牡丹社事件","清日議和條約承認日本出兵為「保民義舉」、給撫卹銀兩並約束生番；日本於1879年併吞琉球","牡丹社事件後沈葆楨來臺：廢渡臺禁令、開山撫番，增設臺北府與恆春縣、卑南廳","沈葆楨在安平建二鯤鯓砲臺（億載金城）、旗後架設砲臺等西式炮臺","荷蘭熱蘭遮城於清代改稱安平堡，作水師衙門與倉庫；沈葆楨建億載金城時拆其外牆磚石作建材","清廷對城池初期只築簡易土牆、木柵或刺竹圍城，以免成為反抗據點及財政負擔","沈葆楨開闢北、中、南三條通往山區與東部的道路；北路為蘇花公路前身","中路由林圮埔（竹山）經八通關到璞石閣（玉里）；南路由射寮到卑南","1884年清法戰爭因越南問題爆發，法軍進攻基隆、淡水、澎湖；劉銘傳來臺督辦防務","清法戰爭臺灣人稱「西仔反」（西仔指法蘭西人，反指戰爭動亂）","清法戰爭期間（1884～1885）法軍封鎖臺灣，淡水海關無稻米輸入紀錄，兩岸貨物往來受阻","臺灣建省可提升行政層級、增加自主權；建省前臺灣隸屬福建，省會在福州","1885年臺灣建省，劉銘傳任首任巡撫；建省後選定臺北為省會","劉銘傳建設：建基隆—臺北鐵路、設郵政總局、架電報線、購輪船，並設西學堂、電報學堂","清法戰爭後建省，全臺設三府（臺北府、臺灣府、臺南府），並增設臺東直隸州","建省後原臺灣府城（今臺南）一帶改屬臺南府，臺灣府改設於中部","臺北府城以北門為主城門，規畫至落成費時5年；日治初期城牆因市區改正遭拆除","劉銘傳修築基隆—臺北—新竹鐵路，任內完成基隆至臺北段（1891年通車）","臺北—新竹鐵路於1893年通車；電報線遠達福州，輪船航行於臺灣、中國大陸與東南亞之間；北部設電燈","治臺態度由消極轉為積極，臺灣成為清帝國最現代化的省分之一"],"example":"億載金城是沈葆楨（牡丹社事件後）所建，海門天險（二沙灣炮臺）則是劉銘傳（清法戰爭）所修。"},{"heading":"農業拓墾與水利設施","points":["推力：福建、廣東人口增加、山多平原少；拉力：臺灣人口稀少、有大量未開墾土地","土地取得：向官府申請墾照開墾無主地，或向原住民承租土地","拓墾所需人力與資金龐大，多採合資經營（墾號），如金廣福墾號開墾新竹內山；留下股、份等地名","清代墾號實例：陳和議墾號、藍廷珍申辦墾照，19世紀創建金廣福公館開墾新竹內山","合資拓墾時墾戶按股份分配土地，留下臺南市七股區、苗栗縣頭份市等地名","隘墾：新竹「合興庄」由竹塹富商陳長順出資，設隘寮連成隘防線並向東推移","水圳多由民間集資興建：八堡圳（康熙、施世榜、彰化平原、灌溉最大）、瑠公圳（乾隆、郭錫瑠、臺北盆地）","貓霧捒圳（雍正、張達京、臺中盆地，原漢共築）、曹公圳（道光、曹謹、高雄，官方主導）","水源：貓霧捒圳引大甲溪、瑠公圳引新店溪、曹公圳引高屏溪、八堡圳引濁水溪；瑠公圳為郭錫瑠父子興建","曹公圳由鳳山知縣曹謹於19世紀前期（道光年間）主導興建，是官方主導的水圳","水利設施使拓墾範圍擴大，稻米、甘蔗產量增加，可輸出至中國大陸"],"example":"記憶法：「八堡最早又最大在彰化」，濁水溪引水；瑠公圳則灌溉臺北盆地。"},{"heading":"對渡貿易與開港通商","points":["開港前以中國大陸為對象進行兩岸對渡貿易，出口稻米、蔗糖，進口紡織品、藥材、日用品","鹿耳門為最初唯一正港（對渡廈門），之後陸續開放鹿港（對渡蚶江）、八里坌（對渡五虎門），形成「一府二鹿三艋舺」三大港市","開港前港口多為海港、河港，形成「正港」一說；開港後政經中心北移","鹿港為與福建泉州（蚶江）對渡的合法港口，泉廈郊商雲集，有「臺自郡城而外，各處貨市，當以鹿港為最」之說","商人組成「郊」（行郊），功能：配運貨物、維護商業利益、避免惡性競爭","郊依地區分泉郊、廈郊，依商品分米郊、糖郊、布郊","《天津條約》先開淡水、安平為通商口岸，後又增開雞籠（基隆）、打狗（高雄），貿易對象擴及世界各地","開港後外商設洋行掌控進出口，僱用漢人買辦處理商務，部分買辦成為新興商人，例如李春生","出口茶葉（北部丘陵，淡水出口，出口值最高）、樟腦（中北部山區）、蔗糖（南部平原，安平、打狗出口）；進口鴉片、紡織品","茶葉是開港後外銷最大宗商品；蔗糖外銷歷史最悠久；樟腦產量曾居世界第一","開港後外銷市場：茶葉主銷美國、東南亞；蔗糖主銷日本；樟腦主銷歐美","樟腦可作藥用、生活用品及軍火、工業原料，帶動採集、煉製到外銷的產業鏈，被喻為「19世紀的護國神山」","樟腦原料產於番地，劃界封山時期附屬於軍事工業物料生產，開港後成為重要出口貨品","英商陶德引進福建安溪茶種，以貸款保障收購的契作模式鼓勵種茶，在艋舺設精製廠，後遷大稻埕","陶德的「福爾摩沙烏龍茶」外銷紐約、揚名歐美，吸引洋商與華商競入臺茶市場，推動大稻埕發展","出口貿易演變：荷蘭時代稻米、蔗糖、鹿皮→鄭氏蔗糖、鹿皮→清開港前稻米、蔗糖→開港後茶、糖、樟腦","19世紀後期起貿易出超，茶、樟腦帶動大稻埕等北部市鎮興起，政經重心（中心）由南部移往北部","19世紀後期北部因茶、樟腦發展而米糧不足，須從中國大陸進口稻米"],"example":"周成在大稻埕做「新興商品」出口而致富，答案是茶葉；糖則早在荷治時期就已外銷。","fig":{"src":"../assets/fig/history/u3-s4.svg","cap":"開港通商後臺灣的主要出口商品"}},{"heading":"移民社會的衝突：械鬥與民變","points":["漢人移民以閩南人（福建泉州、漳州，多居平原）為多數，客家人（廣東為主）北部多居丘陵，常同鄉或同姓聚居","移民渡臺艱辛諺語：「六死三留一回頭」「唐山過臺灣，心肝結歸丸」","性別比例懸殊諺語：「一個某較好三個天公祖」「番兒至老無妻」；羅漢腳多使社會好勇鬥狠","移民社會族群複雜，因語言、習性差異及爭奪土地、水源、商業利益而爆發械鬥","械鬥可依祖籍、姓氏或職業結群，以祖籍分類最頻繁（閩粵械鬥、漳泉械鬥）","分類械鬥諺語：「輸人不輸陣，輸陣歹看面」「仙拚仙，拚死猴齊天」","姓氏械鬥：諺語「鍾廖李，拚生死」源自鍾、李（頂店）與廖姓（下店）之間的姓氏械鬥","1861年板橋林家林國芳藉租約糾紛驅逐泉州籍佃農，引發士林至新莊一帶漳泉大型械鬥","民變是人民以武力反抗政府，背景：吏治不良（官吏貪汙腐化）、治安不佳、男女比例失衡、祕密結社（結盟）盛行，導致社會浮動","三大民變：朱一貴事件（康熙60年）、林爽文事件（乾隆51年，清代規模最大，與天地會有關）、戴潮春事件（同治元年）","王得祿於林爽文事件募勇解諸羅城之圍，嘉慶年間追剿海盜，官至太子太保，家鄉改名「太保」","村莊設「隘門」防禦、各地設有應公廟祭祀動亂死者，反映「三年一小反，五年一大亂」"],"example":"1853年艋舺三邑人因控制碼頭抽稅與同安人爆發「頂下郊拚」，同安人敗走大稻埕，屬爭奪商業利益的械鬥。"},{"heading":"漢人社會文化變遷與西方文化傳入","points":["清初漢人移民被視為暫時寄居的「流寓」，不得入臺灣籍；康熙後期才推行入籍臺灣並強化保甲","渡臺禁令使移民性別比例失衡，俗諺「有唐山公、無唐山媽」，漢人男子多與平埔族女子通婚","宗教信仰由原鄉信仰轉為共同信仰（媽祖、土地公、王爺）","原鄉信仰：泉州人清水祖師、漳州人開漳聖王、潮州（客家）人三山國王；有應公廟祭祀無主孤魂","臺南祀典大天后宮為清代全臺首間官建媽祖廟，由府城北郊、南郊、糖郊三郊共同主持","宗族組織由唐山祖（祭原鄉同姓名人，成員未必有血緣）轉為開臺祖（祭來臺第一代祖先，有血緣關係）","開臺祖宗族建祠堂、修族譜，並以部分祖產作為祭祀公業","開臺祖宗祠實例：屏東崇蘭蕭家宗祠，祭祀1715年生、祖籍廣東惠州的來臺祖蕭唯天，1880年落成","初期移民忙於拓墾少投入文教；中期以後經濟穩定、書院增加，通過科舉者增多，轉型為文治社會","清代臺灣舉人由康雍時期15人增至咸豐至光緒106人，進士由0增至21人，顯示走向文治社會","科舉依原籍應試，廣東移民起初無法應考；朱一貴事件中助官平亂獲「義民」身分，乾隆年間取得粵籍學額","臺灣鄉試有保障名額，漳泉學子常冒籍應考；清廷逐步規定入籍年限，19世紀初出現第一位臺灣籍進士","開港通商後西方傳教士再度來臺，以醫療與教育傳教；開港後西方文化再傳入以基督教長老教會最重要","天主教神父多以教堂為中心向周遭村落傳教；長老教會牧師（如甘為霖、馬偕）更深入山區向原住民傳教、行醫","馬偕在北部淡水替人拔牙、建西醫醫館、設理學堂大書院（牛津學堂），另創淡水女學堂","馬雅各在府城設看西街醫館（在臺南創辦的西醫醫館），為新樓醫院前身"],"example":"西方文化兩度傳入：17世紀荷治時期（新港文）、19世紀開港通商後（長老教會傳教士）。"},{"heading":"原住民的社會文化變遷","points":["清初未將番地視為領土；清廷以是否納稅歸化將原住民分為熟番與生番","熟番居西部平原，受官府管理，易受漢化；生番居山區、東部，保留較多傳統文化","歸化的平埔族（熟番）須納稅、服勞役；清廷設社學（設學校、改漢姓）推廣漢文化","平埔族群因漢人越界開墾，或被以買賣、欺騙取得土地而土地流失，又受官方推動漢化與原漢雜處影響，語言文化式微","清廷設「北路理番同知」駐彰化縣城，處理淡水廳、諸羅、彰化境內漢原土地買賣、質押與侵占糾紛","平埔族群遭官府剝削而多次起事抗官，如1731年大甲西社人不滿勞役沉重，聯合中部各社平埔族反抗，是清代規模最大的原住民抗官事件","19世紀平埔族群展開四次大遷徙，移往埔里盆地、宜蘭、花東","遷徙路線：中部平埔族遷埔里盆地與宜蘭；噶瑪蘭族遷花蓮、臺東；西拉雅族先南遷高雄再移居花東","1823年起中部平埔族群大規模遷入埔里，與當地原住民結為盟友族親（2023年為入埔200年）","高山族群前期受劃界封山隔離；隨漢人拓墾範圍擴大，番界逐漸向山區移動，縮減高山原住民生存空間","開港後茶葉、樟腦需求使漢人入山，原漢衝突增加","牡丹社事件後清廷解除劃界封山、推行開山撫番，開闢通往後山道路、在東部設卑南廳與臺東直隸州","開山撫番使漢人大量進入原住民區域，引發反抗，部分族群被迫遷往更偏僻的山區","1877年大港口事件：清廷強開道路、過度使役原住民，引起花蓮阿美族部落反抗，遭清軍鎮壓","1878年加禮宛事件：噶瑪蘭族與撒奇萊雅族聯合抗清遭武力鎮壓，撒奇萊雅族四散、人口銳減、社會組織瓦解"],"example":"史料從「漢人私入番界處重刑」轉為「生番居島中心，不疏通則百病叢生」，代表劃界封山轉為開山撫番。","fig":{"src":"../assets/fig/history/u3-s7.svg","cap":"清代平埔族群的遷徙（示意）"}}],"confusions":[{"a":"海禁政策","b":"渡臺禁令","diff":"海禁政策在清初至1684年禁止沿海人民出海，目的在打擊鄭氏政權；渡臺禁令在1684至1875年限制漢人來臺，須申請證照且不得攜眷","tip":"打擊鄭氏、禁出海→海禁；領臺後、證照、不准攜眷→渡臺禁令"},{"a":"劃界封山","b":"開山撫番","diff":"劃界封山是清初隔離漢原、禁止漢人越界；開山撫番是牡丹社事件後開路、設官，強化對原住民與山林的控制","tip":"番界、土牛溝、禁越界→清初；開路通後山、卑南廳、臺東直隸州→1874年後"},{"a":"沈葆楨","b":"劉銘傳","diff":"沈葆楨因牡丹社事件以欽差大臣來臺，廢渡臺禁令、建億載金城、開山撫番；劉銘傳因清法戰爭來臺，建省後任巡撫，建鐵路、郵政、電報","tip":"沈＝牡丹社、億載金城；劉＝清法戰爭、巡撫、鐵路（基隆—臺北）"},{"a":"郊（行郊）","b":"洋行","diff":"郊是開港前臺灣商人組成、經營兩岸對渡貿易的組織；洋行是開港後外國商人在通商口岸設立、掌控國際貿易的機構","tip":"泉州、廈門、米糖→郊；外商、茶樟腦、淡水打狗→洋行"},{"a":"開港前對渡貿易","b":"開港後國際貿易","diff":"開港前對象為中國大陸，港口鹿耳門、鹿港、八里坌，出口稻米蔗糖；開港後對象為世界各地，港口雞籠、淡水、安平、打狗，出口茶、糖、樟腦","tip":"米＋糖＝開港前；茶、樟腦＝1860年代以後"},{"a":"械鬥","b":"民變","diff":"械鬥是民間團體（多依祖籍）互相武鬥，爭奪土地水源商業利益；民變是人民以武力反抗官府","tip":"民vs民（漳泉、閩粵）→械鬥；民vs官（朱一貴、林爽文、戴潮春）→民變"},{"a":"唐山祖","b":"開臺祖","diff":"唐山祖祭原鄉同姓顯赫祖先，成員同姓未必有血緣，出現於移民初期；開臺祖祭來臺第一代祖先，成員有血緣，出現於定居後","tip":"移民初期、自願入股→唐山祖；子孫繁衍、有血緣→開臺祖"}],"terms":[{"term":"為防臺而治臺","def":"清帝國領臺初期的治臺方針，目的在防止臺灣再成反清基地或盜賊巢穴，因而採取消極、限制的管理政策。"},{"term":"海禁政策","def":"清初為打擊鄭氏政權，禁止中國沿海人民出海，導致走私貿易興起；1684年納臺灣入版圖後解除。"},{"term":"渡臺禁令","def":"清初規定來臺須先申請證照、只准單身男子渡臺、不准攜眷，限制移民；1875年沈葆楨奏請廢除。"},{"term":"黑水溝","def":"清代移民對臺灣海峽的稱呼，海流湍急、風浪大，偷渡來臺者常喪命，故有「六死三留一回頭」之諺。"},{"term":"劃界封山","def":"清初在近山地區立碑或挖土牛溝劃定番界，嚴禁漢人越界開墾、與原住民通婚，以隔離漢原、避免衝突。"},{"term":"羅漢腳","def":"清代臺灣單身無業、四處遊蕩的男性移民，因渡臺禁令造成男女比例失衡而增多，常成為械鬥與民變的導火線。"},{"term":"牡丹社事件","def":"1871年琉球漁民在恆春遭原住民殺害，1874年日本藉口出兵臺灣南部；事後清廷改採積極治臺。"},{"term":"開山撫番","def":"牡丹社事件後沈葆楨推行的政策，解除劃界封山、開闢通往後山道路、在東部設官，強化對原住民的控制。"},{"term":"清法戰爭","def":"1884~1885年清帝國與法國因越南問題開戰，戰火波及基隆、淡水、澎湖，戰後臺灣建省。"},{"term":"臺灣建省","def":"1885年清廷宣布臺灣建省，劉銘傳任首任巡撫，推動鐵路、郵政、電報等現代化建設。"},{"term":"墾號","def":"清代漢人合資開墾的組織，如金廣福、陳賴章、陳和議墾號，向官府申請墾照後招佃開發土地。"},{"term":"隘墾","def":"清代漢人在近山地區設立隘寮、雇用隘丁連成隘防線，一面防禦原住民、一面向內山推進開墾的方式。"},{"term":"八堡圳","def":"康熙年間施世榜興築，引濁水溪灌溉彰化平原，是清代臺灣灌溉範圍最大的水圳。"},{"term":"郊","def":"又稱行郊，開港前臺灣商人組成的商業組織，負責兩岸貨物運銷並維護同業利益，如泉郊、廈郊、米郊、糖郊。"},{"term":"一府二鹿三艋舺","def":"清代俗諺，指臺灣府城、鹿港、艋舺三大港市，反映兩岸對渡貿易興盛及臺灣由南向北的開發。"},{"term":"開港通商","def":"1858年英法聯軍之役戰敗簽約後，臺灣於1860年代開放雞籠、淡水、安平、打狗為通商口岸，重返國際貿易。"},{"term":"洋行","def":"開港通商後外國商人在通商口岸設立的貿易組織，如英商德記洋行、寶順洋行，掌控臺灣的進出口貿易。"},{"term":"買辦","def":"開港通商後受洋行僱用、替外商處理在臺商務的漢人，部分累積財富成為新興商人，如李春生。"},{"term":"福爾摩沙烏龍茶","def":"英商陶德於開港後在北臺灣經營的烏龍茶品牌，外銷紐約、揚名歐美，帶動臺茶外銷熱潮。"},{"term":"械鬥","def":"民間各自糾集所屬團體以武力解決爭端，清代臺灣以祖籍區分最常見，如閩粵械鬥、漳泉械鬥。"},{"term":"民變","def":"人民以武力反抗政府的行動，起因多為吏治不良、治安不佳，代表為朱一貴、林爽文、戴潮春事件。"},{"term":"義民","def":"清代協助官府平定民變的民眾，如朱一貴、林爽文事件中助官的客家移民，獲朝廷褒揚。"},{"term":"唐山祖","def":"移民初期以原鄉同姓顯赫祖先為祭祀對象的宗族組織，成員同姓但未必有血緣關係。"},{"term":"開臺祖","def":"定居日久後以來臺第一代祖先為祭祀對象的宗族組織，成員有血緣關係。"},{"term":"祭祀公業","def":"開臺祖宗族撥出部分族產作為祭祀祖先的共有財產，用來建祠堂、修族譜、舉辦祭祀。"},{"term":"冒籍應考","def":"清代臺灣鄉試有保障名額，福建漳泉學子寄籍或假冒臺灣籍貫應考的現象，清廷以入籍年限規範。"},{"term":"熟番與生番","def":"清廷對原住民的分類：熟番居西部平原、納稅接受管理；生番居山區、東部，官府無法有效控制。"},{"term":"社學","def":"清廷為歸化平埔族設立的學校，教授漢文與儒家禮俗，推廣漢文化，加速平埔族漢化。"},{"term":"理番同知","def":"清廷設置專管原住民事務的官員，如駐彰化的北路理番同知，處理漢原土地糾紛與協商事件。"},{"term":"大港口事件","def":"1877年清廷開山撫番強開道路、過度使役原住民，引發花蓮阿美族部落反抗，遭清軍鎮壓。"},{"term":"加禮宛事件","def":"1878年噶瑪蘭族與撒奇萊雅族因開山撫番後漢人入墾，聯合反抗清廷，遭武力鎮壓，族人被迫四散。"}],"timeline":[{"time":"1683","event":"施琅率軍攻臺，鄭氏政權結束"},{"time":"1684","event":"臺灣納入清帝國版圖，設臺灣府隸屬福建省，一府三縣；開放鹿耳門對渡"},{"time":"1721","event":"朱一貴事件，事後增設彰化縣、淡水廳（1723）"},{"time":"1722","event":"清廷劃定番界、立碑封山，實施劃界封山"},{"time":"1727","event":"增設澎湖廳，形成一府四縣二廳"},{"time":"1731","event":"大甲西社事件爆發，平埔族群抗官"},{"time":"1786","event":"林爽文事件爆發，清代規模最大的民變；平定後諸羅縣改名嘉義縣"},{"time":"1812","event":"增設噶瑪蘭廳（今宜蘭），一府四縣三廳"},{"time":"1823","event":"中部平埔族群開始大規模遷入埔里"},{"time":"1858","event":"英法聯軍之役清帝國戰敗，簽訂《天津條約》等，臺灣須開港"},{"time":"1860年代","event":"臺灣開港通商，開放雞籠、淡水、安平、打狗，外商設立洋行"},{"time":"1862","event":"戴潮春事件爆發（同治元年）"},{"time":"1871","event":"琉球漁民漂流至恆春，遭牡丹社原住民殺害"},{"time":"1874","event":"牡丹社事件，日本出兵臺灣；沈葆楨來臺加強防務"},{"time":"1875","event":"沈葆楨奏請廢除渡臺禁令、推行開山撫番，增設臺北府"},{"time":"1877","event":"大港口事件，花蓮阿美族部落反抗清軍開路與勞役"},{"time":"1878","event":"臺灣對外貿易開始持續出超"},{"time":"1878","event":"加禮宛事件，噶瑪蘭族與撒奇萊雅族聯合抗清遭鎮壓"},{"time":"1879","event":"日本併吞琉球，改設沖繩縣"},{"time":"1884","event":"清法戰爭爆發，法軍進攻基隆、淡水、澎湖；劉銘傳來臺督辦防務"},{"time":"1885","event":"臺灣建省，劉銘傳任首任巡撫"},{"time":"1891","event":"基隆至臺北鐵路通車（臺北至新竹段1893年通車）"},{"time":"1895","event":"甲午戰爭後簽訂《馬關條約》，割讓臺灣、澎湖給日本"}],"sources":[{"name":"施琅〈恭陳臺灣棄留疏〉","gist":"清廷討論是否保留臺灣時，施琅主張臺灣土地肥沃、物產豐富，且為東南沿海屏障，應予保留。","clue":"「棄留」「拱衛東南沿海」→1683~1684年清領臺之初"},{"name":"清帝國耶穌會士測繪地圖（福建與臺灣）","gist":"康熙年間傳教士以西法測繪的地圖，臺灣僅畫出西半部。","clue":"只畫西半部→劃界封山，官方未實質控制東部"},{"name":"藍鼎元〈經理臺灣第二疏〉","gist":"指出臺灣婦女極少、無父母妻子的單身男子群聚，恐成地方之害。","clue":"僅有臺灣一府、婦女不及數百人、無賴群聚→康熙時期、渡臺禁令造成羅漢腳"},{"name":"藍鼎元〈諭閩粵民人〉","gist":"勸諭漳、泉、客家移民同為臺灣百姓，應相愛相親，勿相仇相怨、互相傷害。","clue":"漳泉、客莊、相仇相怨→械鬥；康熙60年來臺平亂→朱一貴事件"},{"name":"地方志對羅漢腳的描述","gist":"記載無田宅無妻子、不士不農不工不賈、單身游食四方、隨處結黨械鬥的男子。","clue":"無妻子、單身游食、械鬥→羅漢腳，源於渡臺禁令"},{"name":"清代描述鹿港商況的方志文字","gist":"記載鹿港帆檣林立、泉廈郊商居多、百貨充盈，為府城以外最大的貨市。","clue":"泉廈郊、鹿港、郡城以外最盛→開港前兩岸對渡貿易"},{"name":"諺語「第一驚死林國芳」","gist":"板橋林家林國芳藉租約糾紛逐出泉州佃農，引發漳泉衝突，朝廷欲押往福州受審。","clue":"漳州對泉州→分類械鬥；省會福州→建省之前"},{"name":"1870年代福爾摩沙島宣教地圖","gist":"歐美傳教士繪製的臺灣地圖，標示長老教會各宣道站，反映開港後宣教成果。","clue":"宣道站、長老教會→開港通商後；府城→馬雅各醫療傳教"},{"name":"日本將領出兵報備文書","gist":"以我國人民漂流臺灣遭番人殺害為由，奉天皇命登陸臺灣南部懲戒兇手。","clue":"天皇、漂流民遇害、臺灣南部番地→1874年牡丹社事件"},{"name":"日本官員牡丹社事件後談判報告","gist":"清承認日本征番為義舉並撫卹難民，日方認為可作為琉球屬日本版圖的證據。","clue":"征番地為義舉、撫卹難民、琉球屬我國→1874年牡丹社事件後"},{"name":"清日牡丹社事件後簽署條款","gist":"清方承認日本出兵為保民義舉，給遇害難民撫卹銀兩，並承諾約束生番。","clue":"保民義舉、撫卹銀兩、生番→1874年牡丹社事件後清日條約"},{"name":"番界禁令與開山撫番奏摺","gist":"前者主張漢人私入番界處以重刑；後者主張疏通生番所居的島內中心，以穩定內政抵禦列強。","clue":"番界、禁出入→劃界封山（清初）；疏通番地、列強環伺→開山撫番（牡丹社事件後）"},{"name":"馬偕通行證／傳教士紀錄","gist":"英國領事請法軍司令准許宣教士馬偕進入其占領地，或記載法軍包圍下救治馬偕。","clue":"傳教士可來臺→開港後；法軍占領、北部→清法戰爭的基隆、淡水"},{"name":"清代臺灣人口密度圖（1811年與1893年）","gist":"比較兩年度各廳縣人口與密度，1893年東部已納入行政區，北部淡水縣人口密度高。","clue":"東部空白消失→建省後設臺東直隸州；北部密度高→開港後茶、樟腦產業"}]},{"unit":4,"part":"臺灣史","title":"日本帝國時期的臺灣","summary":"學習日本統治臺灣五十年（1895~1945）的殖民體制、三階段統治政策、經濟建設、現代教育與政治社會運動、風俗文化變遷；會考常以史料關鍵字（公學校、總督府、神社、蓬萊米、嘉南大圳等）判斷時代，並考統治三階段的背景與措施排序。","sections":[{"heading":"殖民體制的建立","points":["1894年甲午戰爭清帝國戰敗，1895年簽訂《馬關條約》，將臺灣、澎湖割讓給日本","臺灣官紳成立臺灣民主國抗拒日本接收：以藍地黃虎旗為國旗、「永清」為年號，由唐景崧、丘逢甲、劉永福領導","民主國總統唐景崧原為末任臺灣巡撫，義軍統領丘逢甲；最後領導者先後離臺，民主國瓦解，抗日失敗","1895年日軍進入臺北城，臺灣總督在臺北舉行始政式，總督府開始管理臺灣","設臺灣總督府為最高統治機構；1896年依《六三法》，總督可頒布具法律效力的命令","總督集行政、立法、司法、軍事大權於一身（總督專制）；對照日本內地立法權在帝國議會，天皇僅能以緊急命令代替法律","警察遍設派出所，權力大到被稱為「大人」","沿用清代保甲制度：十戶一甲設甲長、十甲一保設保正，實施連坐；青壯年男子組壯丁團協助警察","保甲由日本用以輔佐警察與地方機構，執行調查戶口、宣達政令等公共事務","警察與保甲制度結合，嚴密監控臺灣社會，奠定統治基礎","日俄戰爭時日軍在苗栗虎頭山設海軍望樓與無線送信所監視俄艦，戰後立日露戰役紀念碑，宣揚殖民母國戰功"],"example":"題目出現藍地黃虎旗、「割讓」、「成立民主國」→臺灣民主國，背景是《馬關條約》。","fig":{"src":"../assets/fig/history/u4-s1.svg","cap":"1895 年日軍接收臺灣的進軍路線（示意）"}},{"heading":"統治政策的轉變","points":["無方針主義（1895~1919，武官總督）：各地武裝抗日頻繁，鎮撫兼施，高壓鎮壓並尊重臺人舊慣","1915年余清芳以宗教號召發動西來庵（噍吧哖）事件，不滿殖民政權；此後漢人改採非武裝抗日","內地延長主義（1919~1937，文官總督）又稱同化政策：背景為一次大戰後美國總統威爾遜提出民族自決，以及殖民地獨立運動風潮","內地延長主義標榜「日臺合一」，將日本法律引入臺灣，但臺人仍受差別待遇","差別待遇例：內地延長主義時期臺人就業仍受差別待遇，臺北同職業日人日薪約為臺人的兩倍以上","皇民化運動（1937~1945，武官總督）：中日戰爭爆發、配合南進政策，推動說日語、改日姓、參拜神社","皇民化時期以「特別志願兵」名義動員臺人從軍，徵召臺籍日本兵赴南洋作戰，或以軍伕身分派往戰地；並以漫畫等宣傳品宣揚為天皇效力","皇民化時期部分婦女被迫充當「慰安婦」；1941年太平洋戰爭爆發後美軍轟炸臺灣","中日戰爭後期，原住民自願或受徵調組成高砂義勇隊赴南洋作戰（北大武山大武祠、紀念碑即紀念陣亡義勇隊）","理蕃政策初期對高山原住民採防堵、安撫：在山區架設鐵絲網、木牆為隘勇線圍堵，並安排頭目赴日觀光，宣揚日本現代化成果","總督府延續清末制度，將部落領袖稱為「頭目」以方便管理","1910年代起為開發山林資源（樟腦、林木）實施五年理蕃計畫：軍警深入山區武力鎮壓、征討","五年理蕃計畫打通東西橫貫道路，作為開發東部的運輸幹線，並以教育同化使原住民歸順","霧社事件背景：總督府高壓理蕃、警察欺凌、強制勞役","1930年賽德克族頭目莫那・魯道發動霧社事件，遭軍警以飛機、毒氣鎮壓","霧社事件引起日本與國際關注，總督府重新檢討原住民政策，改採教育同化，並將部落集體遷往山下","抗日事件比較：臺灣民主國抗拒接收；西來庵不滿殖民政權、以宗教號召；霧社不滿高壓同化、山林資源遭掠奪、警察欺凌"],"example":"「1919一戰、1937中日戰爭」兩個轉折點：武官→文官→武官。","fig":{"src":"../assets/fig/history/u4-s2.svg","cap":"日治時期重要的武裝抗日事件"}},{"heading":"日治時期的經濟發展","points":["總督府追求臺灣財政獨立：日治初期財政需仰賴日本政府補助，改由臺灣納稅人負擔現代設施","民政長官後藤新平推動基礎建設：鴉片、樟腦專賣使總督府財政收入大增，逐漸擺脫日本國庫補助","專賣後收入大增：1897~1906年財政收入成長約三倍；菸、酒亦為專賣品，專賣制度對臺灣財政影響深遠","1935年臺灣博覽會「專賣館」銷售額居各館之冠，展出捲菸機等","後藤新平任民政長官時主持土地、林野、人口、舊慣等調查；1923年關東大地震後任內務大臣，以治臺經驗推動首都復興","進行土地、林野調查與1905年起的人口普查，掌握稅收與人力資源；土地調查確定土地所有權以增加田賦","1895年《官有林野及樟腦製造業取締規則》：無地券等證明的山林原野歸為官有；林野調查將無主山林收歸國有","原住民無法證明土地產權，傳統領域流失、失去獵場，生活空間被壓縮","1899年設立臺灣銀行，最初目的是使臺灣財經獨立，提供產業資金，並發行臺灣銀行券為統一貨幣，方便臺日間資金流通","臺灣銀行後成為日本對中國、南洋貿易擴張的金融後盾，被稱為「萬能銀行」","臺灣銀行發行的百元紙幣印有檳榔樹，俗稱「青仔欉」，因購買力驚人而少見","日治交通：各地修築公路、西部縱貫鐵路與阿里山鐵路、整建基隆與高雄港、興建飛行場（機場），設郵便局、電報、電話","1908年基隆至高雄西部縱貫鐵路通車：縱貫鐵路連結西部重要城鎮，突破河川多東西向的不便","阿里山森林鐵道1912年通車，以螺旋形與之字形路線上山運輸山區原木，見證林業開發，現為國家級文化景觀","基隆港聯絡日本、高雄港（打狗港）為南部貨物出口港；兩港對日本出口額逐年大增，反映米糖輸日；淡水、安平港則衰退","商業以基隆、高雄港與日本本土、南洋往來，商業組織為會社（公司），不同於清代的郊與洋行","日治前期「工業日本，農業臺灣」：獎勵日資設新式糖廠（糖業王國）、培育蓬萊米、建嘉南大圳，米糖大量銷往日本","獎勵日資設新式糖廠，取代舊式製糖業（糖廍），振興製糖業、增加日本資本家的競爭力","1900年代起新式製糖廠產量迅速超越舊式糖廍，糖廍產量逐漸趨近於零","蔗農受製糖會社剝削（「第一憨，種甘蔗予會社磅」）：被限制販售對象且遭偷斤減兩，引發蔗農抗爭（如1925年二林事件）","磯永吉培育蓬萊米；米糖爭地形成「米糖相剋」","八田與一建嘉南大圳（1930），為日治時期規模最大的水利工程，增加嘉南平原灌溉面積","嘉南大圳也解決臺灣西南沿海海埔新生地的鹽害，使鹽地逐漸變為良田；米糖產量在設糖廠、推廣蓬萊米、大圳完工後大增","鳥居信平為臺灣製糖株式會社開墾蔗田，在屏東採「地下水庫」做法興建二峰圳（1923年完成），至今仍供應屏東平原水源","1930年代起「工業臺灣，農業南洋」：配合南進政策，臺灣成為南進補給基地，積極發展機械、石化、造船等國防軍需工業","1934年日月潭水力發電所完工，紡織、食品加工等輕工業生產指數快速攀升、顯著成長","工業化使臺灣逐漸從農業社會邁向工業社會"],"example":"嘉南大圳1930、日月潭發電所1934：一個讓農業臺灣增產，一個讓工業臺灣起飛。","fig":{"src":"../assets/fig/history/u4-s3.svg","cap":"日治時期的交通與經濟建設"}},{"heading":"現代教育與社會運動","points":["日治引進西式教育，作為同化臺人與推動產業政策的工具；臺人也從中獲得現代知識","教育原則為差別待遇、隔離原則，以日語教學為主；日語漸成臺人共通語言，吸收知識也影響至今","初等教育：小學校（日人）、公學校（臺人）、蕃童教育所與蕃人公學校（原住民）","蕃童教育所的教師由日本警察擔任","1922年新教育令後臺人就學人數增加，但1926年臺人讀小學校僅約千人、日人讀公學校僅十餘人，隔離原則仍在","1941年小學校、公學校改稱國民學校；1943年實施六年國民義務教育，臺籍就學率大增","1943年實施義務教育後，臺籍兒童就學率超過70%（日人兒童早已近100%）","中等教育以實用為原則：設國語學校（培養公學校教師）、醫學校與職業學校，培育醫師、公學校教師與初級技術人才","1915年林獻堂等臺籍士紳爭取成立臺中中學校（今臺中一中），是第一所專門培育臺籍學生的中學","1928年成立臺北帝國大學（今臺灣大學），主要滿足在臺日人升學；臺人有志升學者多留學日本","留日學生回臺後成為推動政治社會運動的主角","修學旅行是日治校園生活的固定行程，參訪產業、歷史建築與人文景點，以增廣見聞；1935年舉辦始政40周年博覽會","1920年代受民族自決影響：林獻堂、蔣渭水成立臺灣文化協會（1921~1931），發行《臺灣民報》","文化協會舉辦讀報社、演講會、夏季學校等，啟迪民智、改良社會風氣","林獻堂等人推動臺灣議會設置請願運動（1921~1934），多次向日本帝國議會請願設立民選臺灣議會","臺灣民眾黨（1927~1931）為第一個合法政黨：宣導民權與地方自治，扶助農、工運動","臺灣地方自治聯盟（活動至1937年）以促進地方自治為單一目標，並容納在臺日本人參加，主張溫和的體制內改革","臺灣地方自治聯盟促成1935年首次地方議員選舉：僅半數議員民選、限制選民資格","1935年地方選舉雖受限制，但使臺人首次行使投票權，認識普選、自治、參政權","1937年中日戰爭爆發後，政治社會運動受總督府打壓而被迫中止、銷聲匿跡"],"example":"看到「公學校」就知道是日治；看到「林獻堂、蔣渭水、請願」就是1920年代非武裝抗日。"},{"heading":"新舊文化的交替與衝擊","points":["日治新文化樣貌：放足斷髮、現代衛生觀念、守法及守時習慣、都會文化及休閒活動（常考：現代衛生觀念）","總督府將吸食鴉片、纏足、辮髮視為三大陋習，並透過保甲與多方宣導推動放足、斷髮、易服改裝","鴉片漸禁政策（專賣、特許購買）：總督府卻藉專賣獲利，遭批評無根絕誠意","興建自來水、下水道，推廣霍亂等傳染病預防注射（接種）與西式醫療，傳染病獲得控制","日治初期在基隆、淡水、安平、打狗等港口實施船舶檢疫，防堵霍亂、鼠疫、天花；1917年前後全島已無鼠疫","醫療衛生改善使死亡率下降、人口快速成長：從1905年約300萬增至1943年約660萬","日人最初開發溫泉供軍警療養，1912年在金山開設全臺首座公共浴室，陸續建15處，培養臺人沐浴衛生習慣","使用西曆，引進一天24小時的標準時間制與星期制，要求學校、工廠、鐵路守時","引進司法制度與法院，培養守時守法觀念；引進左側通行等交通規範，由警察取締","推動都市計畫，興建西式建築、公園、博物館","1911年辛亥大洪災淹沒臺北盆地，總督府擴大河川調查、規畫治水，並藉機對臺北進行現代化市區改造","百貨公司、咖啡廳、社交舞等休閒娛樂在都市普及；1930年代臺北菊元百貨、臺南林百貨開幕，搭百貨公司電梯是時髦活動","也流行溫泉文化、鐵路觀光；1920年代起官方鼓勵登山健行，浸水營等古道一年有上千人前往，戰爭徵調年輕人後盛況不再","日治初期日本學者（如牧野富太郎）來臺調查動植物、地質與人類學；愛玉學名即由牧野命名，含臺語發音awkeotsang","新制度不完全落實於民間，現代化建設存在城鄉差距；不習慣穿鞋、搭電梯等反映新舊文化仍需調適","新舊文化交融、調適使臺灣社會成為漢人、日本、西洋文化並存的面貌（中式、日式、西式並存）","皇民化時期臺人夾在「日本國民」與「漢族」身分間，認同矛盾加劇"],"example":"「時的紀念日」鳴鐘校正鐘錶，是日治培養守時觀念的代表。"}],"confusions":[{"a":"臺灣民主國","b":"臺灣議會設置請願運動","diff":"臺灣民主國是1895年武力抗拒日本接收；請願運動是1920年代以合法手段爭取設立臺灣議會","tip":"黃虎旗、唐景崧→民主國；林獻堂、請願、議會→請願運動"},{"a":"無方針主義","b":"內地延長主義","diff":"前者依臺灣實際情況因地制宜、高壓鎮壓；後者視臺灣為日本內地延伸，把日本法律制度直接引入臺灣","tip":"武官＋鎮撫＝無方針；文官＋日臺合一＝內地延長"},{"a":"內地延長主義","b":"皇民化運動","diff":"內地延長重在制度同化以安撫臺人；皇民化要從精神上改造臺人成為效忠天皇的子民，並動員參戰","tip":"改日姓、說日語、拜神社、南洋作戰→皇民化"},{"a":"西來庵事件","b":"霧社事件","diff":"西來庵（1915）是余清芳以宗教號召的漢人武裝抗日；霧社（1930）是莫那・魯道領導的原住民抗日","tip":"宗教、噍吧哖→西來庵；賽德克族、理蕃、警察侵擾部落→霧社"},{"a":"工業日本，農業臺灣","b":"工業臺灣，農業南洋","diff":"前者（日治前期）臺灣供應米糖給日本；後者（1930年代起）配合南進政策，臺灣成為發展軍需工業的前進基地","tip":"蓬萊米、新式糖廠、嘉南大圳→前者；日月潭發電所、軍需工業→後者"},{"a":"公學校","b":"小學校","diff":"公學校是給臺灣人子弟讀的初等學校；小學校是給在臺日人子弟讀的，課程與日本內地相同","tip":"臺人讀「公」，日人讀「小」，原住民讀蕃童教育所（或蕃人公學校）"},{"a":"臺灣文化協會","b":"臺灣議會設置請願運動","diff":"文化協會屬文化啟蒙，以報紙、演講、讀報社啟迪民智；請願運動屬政治運動，多次向日本請願設立民選臺灣議會","tip":"演講、夏季學校、《臺灣民報》→文化協會；向帝國議會請願、設議會→請願運動"},{"a":"臺灣民眾黨","b":"臺灣地方自治聯盟","diff":"民眾黨（1927~1931）由蔣渭水成立，宣傳民權並扶助農工運動；自治聯盟（1930~1937）由林獻堂等人籌組，專注爭取地方自治","tip":"第一個政黨→蔣渭水民眾黨；促成1935年首次地方選舉→林獻堂自治聯盟"}],"terms":[{"term":"馬關條約","def":"1895年清帝國於甲午戰爭戰敗後與日本簽訂的條約，將臺灣、澎湖割讓給日本，開啟日本五十年殖民統治。"},{"term":"臺灣民主國","def":"1895年臺灣官紳為抗拒日本接收而成立的政權，以藍地黃虎旗為國旗，唐景崧為總統，不久即被日軍平定。"},{"term":"臺灣總督府","def":"日治時期在臺最高統治機構，臺灣總督為最高行政首長，建築即今總統府。"},{"term":"六三法","def":"1896年公布的「法律第六十三號」，授權臺灣總督頒布具法律效力的命令，使總督集行政、立法、司法、軍事大權於一身。"},{"term":"保甲制度","def":"日治沿用清代地方自衛組織，十戶為甲設甲長、十甲為保設保正，實施連坐，並由壯丁團協助警察維持治安。"},{"term":"民族自決","def":"一次大戰後美國總統威爾遜提出，主張各民族有權決定自身事務、不受他國干涉，激發臺人政治社會運動。"},{"term":"皇民化運動","def":"1937年中日戰爭爆發後推行，要臺人說日語、改日姓、穿和服、拜神社，使臺人成為效忠天皇的子民。"},{"term":"慰安婦","def":"二次大戰期間被日軍以各種方式強迫為軍隊提供性服務的婦女，皇民化時期部分臺灣婦女被迫充當。"},{"term":"軍伕","def":"戰爭期間被徵調為軍隊從事搬運、雜役等後勤工作的人員；中日戰爭後許多臺灣人以軍伕身分被派往戰地。"},{"term":"高砂義勇隊","def":"中日戰爭後期（太平洋戰爭）原住民自願或受徵調組成的部隊，被派往南洋叢林作戰，傷亡慘重。"},{"term":"隘勇線","def":"總督府在山區架設鐵絲網、木牆等防線並派隘勇駐守，限制原住民活動範圍，以防堵、圍困原住民。"},{"term":"五年理蕃計畫","def":"1910~1915年總督府為開發山林資源，派軍警進駐山區武力征討不願歸順的原住民部落。"},{"term":"霧社事件","def":"1930年賽德克族頭目莫那・魯道不滿警察侵擾與沉重勞役，率族人起事，遭日軍以飛機、毒氣鎮壓。"},{"term":"專賣制度","def":"總督府將鴉片、樟腦等商品列為專賣，由專賣局獨占經營，使財政收入大增，得以推動基礎建設。"},{"term":"林野調查","def":"總督府調查山林土地，將無法證明所有權的無主山林收歸國有，以利開發森林資源，壓縮原住民生活空間。"},{"term":"阿里山森林鐵道","def":"日治時期興建、1912年通車的登山鐵道，以螺旋形、之字形路線上山，用來運輸山區原木，見證林業開發。"},{"term":"會社","def":"日治時期對公司的稱呼；日資製糖會社等企業主導臺灣產業，取代清代的郊與洋行成為主要商業組織。"},{"term":"蓬萊米","def":"日治時期由磯永吉等人培育改良的稻米品種（1922年問世），產量大增並大量銷往日本，與甘蔗爭地形成米糖相剋。"},{"term":"嘉南大圳","def":"八田與一設計、1930年完工的水利工程，以烏山頭水庫蓄水，解決嘉南平原灌溉問題，使農產量大增。"},{"term":"二峰圳","def":"日籍工程師鳥居信平設計、1923年完工的屏東地下集水廊道，為開墾蔗田而建，至今仍穩定供應灌溉水源。"},{"term":"二林事件","def":"1925年彰化二林蔗農為爭取權益與警察爆發衝突，多人遭逮捕判刑，此後開啟全島性農民運動。"},{"term":"南進政策","def":"1930年代日本向東南亞（南洋）擴張的政策，以臺灣為補給與工業基地，發展軍需工業並動員臺人參戰。"},{"term":"日月潭水力發電所","def":"1934年完工，為民生與工業提供充足電力，配合工業臺灣政策發展。"},{"term":"蕃童教育所","def":"日治時期設於原住民部落的初等教育機構，教師由日本警察擔任，用來對原住民進行教育同化。"},{"term":"臺中中學校","def":"1915年林獻堂等臺籍士紳爭取設立，今臺中一中，是第一所專門培育臺籍學生的中學。"},{"term":"臺北帝國大學","def":"1928年成立，為日治時期臺灣唯一的大學，主要滿足在臺日人升學需求，今臺灣大學前身。"},{"term":"臺灣文化協會","def":"1921年林獻堂、蔣渭水等人成立（1931年結束），發行《臺灣民報》、舉辦文化演講，啟迪民智、喚醒民族意識。"},{"term":"臺灣議會設置請願運動","def":"1921~1934年林獻堂等人多次向日本政府請願設立民選臺灣議會，雖未成功但喚起臺人政治意識。"},{"term":"臺灣民眾黨","def":"1927年由蔣渭水等人成立（1931年結束），提倡民權、自治並支持農工運動，是臺灣史上第一個合法政黨。"},{"term":"臺灣地方自治聯盟","def":"1930年林獻堂等人成立，爭取地方自治，促成1935年臺灣首次地方議員選舉。"}],"timeline":[{"time":"1894","event":"清、日因朝鮮問題爆發甲午戰爭"},{"time":"1895","event":"簽訂《馬關條約》割讓臺澎；臺灣民主國抗日失敗，日本開始統治臺灣"},{"time":"1899","event":"成立臺灣銀行，發行統一貨幣"},{"time":"1905","event":"首次人口普查"},{"time":"1908","event":"基隆至高雄的西部縱貫鐵路通車"},{"time":"1910~1915","event":"五年理蕃計畫，武力征討山區原住民"},{"time":"1911","event":"辛亥大洪災淹沒臺北盆地，災後總督府全面調查河川並推動臺北市區改造"},{"time":"1912","event":"阿里山森林鐵道通車；金山開設全臺首座公共浴室"},{"time":"1915","event":"余清芳發動西來庵（噍吧哖）事件；臺中中學校創立"},{"time":"1918","event":"美國總統威爾遜提出民族自決，一次大戰結束"},{"time":"1919","event":"首位文官總督就任，進入內地延長主義時期"},{"time":"1921","event":"臺灣文化協會成立；臺灣議會設置請願運動開始"},{"time":"1922","event":"蓬萊米問世；總督府頒布新《臺灣教育令》，臺人就學人數增加"},{"time":"1923","event":"鳥居信平設計的屏東二峰圳（地下水庫）完工"},{"time":"1925","event":"二林事件：彰化二林蔗農爭取權益與警察衝突，開啟全島性農民運動"},{"time":"1927","event":"臺灣民眾黨成立，為第一個合法政黨"},{"time":"1928","event":"成立臺北帝國大學"},{"time":"1930","event":"霧社事件爆發；嘉南大圳完工；臺灣地方自治聯盟成立"},{"time":"1931","event":"臺灣文化協會、臺灣民眾黨相繼結束活動"},{"time":"1934","event":"日月潭水力發電所完工；臺灣議會設置請願運動結束"},{"time":"1935","event":"首次地方議員選舉（半數民選）；舉辦始政40周年臺灣博覽會，專賣館銷售額居各館之冠"},{"time":"1937","event":"中日戰爭爆發，推行皇民化運動，政治社會運動被迫中止"},{"time":"1941","event":"小學校、公學校改稱國民學校；太平洋戰爭爆發"},{"time":"1943","event":"實施六年義務教育"},{"time":"1945","event":"日本投降，二次大戰結束，日本結束對臺統治"}],"sources":[{"name":"藍地黃虎旗相關記載","gist":"外國記者記錄臺灣官民升起藍底黃虎的新國旗，欲建立新政權抗拒日本軍艦。","clue":"黃虎旗、新國旗、日本軍艦、成立民主國→1895年臺灣民主國，背景為《馬關條約》"},{"name":"《官有林野及樟腦製造業取締規則》","gist":"1895年總督府規定須持地券或確實證明申報才能擁有山林土地，否則歸為官有。","clue":"地券、無主山林原野歸官有、不承認原住民自然主權→日治林野調查使原住民失去獵場"},{"name":"《匪徒刑罰令》","gist":"1898年臺灣總督發布嚴刑峻法，日本國會卻無法審議。","clue":"總督發布命令不需國會審議→六三法授權、總督專制"},{"name":"批評屬地專制的報紙社論","gist":"主張臺灣是憲法施行區域而非附屬領地，批評總督府在立法、行政、司法上專制集權。","clue":"憲法不施行於臺灣、屬地制度、專制集權→批評《六三法》下的總督專制"},{"name":"〈南無警察大菩薩〉漫畫","gist":"把日治警察畫成多手菩薩，同時管左側通行、思想取締、犯人逮捕、惡疫預防、番人授產、救助救護等事務。","clue":"警察管理範圍無所不包→日治「警察政治」，人民稱警察為「大人」"},{"name":"日治時期臺人護照（大日本帝國外國旅券）","gist":"臺灣人前往廈門等中國地區須持日本政府發給的護照，上載本籍臺南州臺南市等資料。","clue":"PASSPORT OF JAPAN、大正年號、臺南州→《馬關條約》後臺灣隸屬日本，與中國分屬不同國家"},{"name":"蔣渭水〈臨床講義〉","gist":"診斷臺灣人患了「智識營養不良」症，文化運動是唯一治療法。","clue":"蔣渭水、文化協會、啟迪民智→1920年代文化啟蒙運動"},{"name":"《臺灣民報》創刊詞","gist":"指出日本統治表面平靜繁榮，但臺人經濟困苦；歐戰後思潮大變，呼籲同胞覺醒。","clue":"歸屬日本近三十年、歐洲戰後思潮大變→1920年代民族自決影響"},{"name":"臺灣議會設置請願運動宣傳單","gist":"批評集三權於一身的總督施行極端專制政治，主張臺灣人應參與特別立法、議定預算。","clue":"參與臺灣特別立法、議定預算、批評總督專制→臺灣議會設置請願運動"},{"name":"日治報紙社會新聞","gist":"新聞中出現公學校、自來水、警察、火車站、咖啡店等現代事物。","clue":"公學校、帝國大學、內地人、本島人、總督府→日治時期"},{"name":"霧社事件新聞報導","gist":"《臺灣日日新報》、《東京朝日新聞》報導霧社蕃人蜂起、襲擊警察駐在所，日方派軍隊出動。","clue":"霧社、能高郡、運動會當日、蕃人蜂起→1930年霧社事件，起因於高壓理蕃"},{"name":"吳新榮日記","gist":"記載日本治臺四十週年紀念日、美軍大空襲、二二八事件等經歷。","clue":"治臺四十週年＝1935；美軍空襲＝二戰末期；專賣局、長官公署＝1947"},{"name":"《改姓名讀本》","gist":"臺灣改姓名推進會出版，介紹改姓名的理念、申請手續與登記變更，並收錄總督訪問記。","clue":"改姓名、總督閣下、臺北帝國大學→皇民化運動鼓勵臺人改日本姓名"}]},{"unit":5,"part":"臺灣史","title":"當代臺灣","summary":"戰後臺灣從政權轉換、二二八事件、戒嚴與白色恐怖，走向解嚴與民主化；外交從鞏固、彈性到務實，兩岸由武力對抗到民間交流；經濟由進口替代、出口導向、十大建設到產業升級，文化由中華文化、美式、鄉土走向多元。會考常考史料判讀年代、事件先後排序與政策對應。","sections":[{"heading":"政權轉換與二二八事件","points":["民國34年日本投降，政府成立臺灣省行政長官公署接收臺灣，陳儀任行政長官","行政長官公署集行政、軍事大權於一身，類似日治時期的臺灣總督（府），且未重視臺籍菁英","戰後問題：官員貪汙濫權、多任用外省人；語言文化差異引發摩擦","經濟惡化：二戰末期臺灣遭美軍轟炸受損；戰後米糧短缺加上經濟管制，物資運往大陸支援國共內戰，公署無法有效調節→物價飛漲","物價飛漲實例：蓬萊白米每公斤1946年12月29.25元，1949年5月漲到18,722元","民國36年2月27日專賣局人員在臺北查緝私菸誤傷民眾，隔日抗議遭開槍驅離，衝突蔓延全臺","各地組二二八事件處理委員會要求改革；陳儀報請中央派兵來臺鎮壓並清鄉，造成大量傷亡","善後：陳儀免職，行政長官公署改為臺灣省政府；最高行政首長由行政長官改為省主席","影響：族群關係受創；民國80年代政府道歉賠償、訂和平紀念日"],"example":"記口訣「私菸→開槍→處委會→派兵清鄉→改省政府」。","fig":{"src":"../assets/fig/history/u5-s1.svg","cap":"二二八事件後國軍增援臺灣的路線（示意）"}},{"heading":"威權體制與白色恐怖","points":["民國36年底實施憲政，選出總統、副總統與中央民意代表","民國37年因國共內戰制定《動員戡亂時期臨時條款》（37～80年）：擴大總統職權、取消總統連任限制，使總統職權不受《憲法》限制","民國38年臺灣省政府（省主席兼警備總司令陳誠）頒布《戒嚴令》，自5月20日零時起臺灣全省戒嚴（38～76年）","《戒嚴令》防止共產勢力滲透，限制集會、結社、出版、言論等自由","施行範圍：《憲法》（民國36年）、《臨時條款》施行於全國；《戒嚴令》只施行於臺灣省","戒嚴長達38年，是世界上僅次於敘利亞的長期戒嚴；2007年起每年7月15日訂為解嚴紀念日","白色恐怖：民國40、50年代政府以「整肅匪諜」等罪名，不依法律程序逮捕、審判異議分子，造成許多冤案","許多政治犯被送往綠島「新生訓導處」監管（門牌流麻溝十五號），1951～1954年犯人與管理人員近三千名","受難者不分族群或性別，家屬也身心受禁錮；民眾多畏懼參與政治，影響社會正常發展","中央民意代表遷臺前在大陸各地選出，長期未全面改選，形成「萬年國會」","戰後原住民政策以「山地平地化」為方針：稱「山地同胞」、以漢名登記戶籍、推行國語運動，傳統文化流失"],"example":"文星案、殷海光事件等1960年代學術言論案件，都是白色恐怖下的噤聲。"},{"heading":"從戒嚴到民主化","points":["民國39年起實施地方自治，開放縣市長、地方民代選舉，但省主席、直轄市長仍官派","刊物比較：《自由中國》（1949～1960年，雷震）批評時政、擴展民主自由空間；《美麗島》雜誌（1979年，黨外人士）推動民主政治","雷震事件（民國49年）：雷震在《自由中國》批評時政並籌組中國民主黨，被捕入獄，由警備總部軍事法庭判刑十年","雷震罪名：「明知為匪諜而不告密檢舉」及「為有利於叛徒之宣傳」","民國68年中美斷交後，政府宣布暫停增額中央民意代表選舉，引起黨外不滿","美麗島事件（民國68年）：美麗島雜誌社在高雄舉辦「國際人權日紀念大會」遊行呼籲解嚴，引發警民衝突（憲警與民眾）","事件後政府在國際壓力下公開審判，多人以叛亂罪入獄，反使更多臺灣人認識黨外人士的民主訴求","政黨比較：中國民主黨（1960年，雷震）評論時政、宣揚民主憲政；民國75年民進黨成立（黨外人士）主張解嚴、回歸憲政","民國76年蔣經國宣布解嚴，開放黨禁、報禁","民國79年野百合學運要求廢除臨時條款、解散萬年國會","民國80年李登輝終止動員戡亂，解散「萬年國會」，中央民代全面改選","民國85年首次總統直選；民國89年首次政黨輪替；民國97年馬英九當選，二次政黨輪替","民國105年蔡英文當選，為首位女性元首","政府給予白色恐怖受難者賠償，設人權紀念園區，使社會朝向重視人權公義方向發展"],"example":"依序記「雷震49→美麗島68→民進黨75→解嚴76→野百合79→終止戡亂80→總統直選85」。"},{"heading":"外交局勢","points":["鞏固外交：爭取友邦，謀求「確保臺灣，光復大陸」","民國39年韓戰爆發，美國派第七艦隊協防臺灣海峽並提供美援","美援：1951～1965年美國總共提供近15億美元經濟援助，另有軍事援助與外交支持","韓戰後美軍顧問團駐臺；1955年起美軍協防臺灣司令部於臺北運作，1979年中美斷交後退旗撤離","民國43年簽《中美共同防禦條約》，將臺灣納入東亞（西太平洋）反共防衛體系，穩定臺海局勢","彈性外交背景：中蘇交惡，美國拉攏中共；民國60年中華人民共和國取得聯合國席位","民國60年聯合國大會通過2758號決議，承認中華人民共和國為中國唯一合法代表","我國本著「漢賊不兩立」立場主動宣布退出聯合國，日本等友邦紛紛斷交，邦交國銳減","邦交國數量：1960年代末最多約70國，退出聯合國後1970年代驟減至20餘國","彈性外交（民國60～77年）：著重與無邦交國發展經貿及文化交流，但仍堅持中華民國是中國唯一合法政府","民國68年美國與中共建交、與我國斷交，廢《中美共同防禦條約》，另訂《臺灣關係法》維持非官方往來","務實外交（民國77年李登輝繼任起）：不再堅持代表中國唯一合法政府，強調兩岸是分裂分治的政治實體","務實外交以經濟、民主為後盾參與國際組織：民國80年加入亞太經濟合作會議（APEC），民國91年加入世界貿易組織（WTO）","現況：免簽證國家大幅增加，但國際空間仍受中國打壓"],"example":"美援麵粉宣傳「小麥定比白米好」，就是韓戰後美國經濟援助的痕跡。"},{"heading":"兩岸關係","points":["戰役比較：國共內戰（民國34～39年）使政府遷臺、兩岸分治；韓戰（民國39～42年）使美國協防臺灣、提供美援，朝鮮分裂至今","民國38年10月1日中華人民共和國成立，同月古寧頭戰役國軍戰勝，12月中華民國政府遷臺","武力對抗（民國38～68年）：中共主張「武力解放臺灣」，我國主張反攻大陸（「光復大陸，反共復國」）","古寧頭戰役（民國38年）、八二三炮戰（民國47年）都發生在金門","八二三炮戰（民國47年）國軍在美國協防下反擊，此後兩岸不再有大規模武力對抗","政治對峙（民國68～76年）：中美建交後中共改採和平統戰，提出三通四流、一國兩制","一國兩制：臺灣可實施與中國大陸不同的政經制度、享有規定範圍內的自治地位，但未尊重我國主權","我國在政治對峙時期提出三不政策、三民主義統一中國","民間交流（民國76年起）：解嚴後開放大陸探親","民國80年終止動員戡亂，結束因應中共叛亂的全國動員，不再視中共為叛亂團體，兩岸在法律意義上的敵對狀態結束","終止動員戡亂後，政府改稱中共政權為「大陸當局」，定位為「控制大陸地區的政治實體」","兩岸事務機構：官方為我國行政院大陸委員會（陸委會）、中共國務院臺灣事務辦公室（國臺辦）","民間由陸委會委託海基會、中共國臺辦對應海協會受委託處理交流事務；民國82年辜汪會談","民國90年起「小三通」開放金門、馬祖、澎湖與對岸交流；民國97年開放直航「大三通」（兩岸直航）","小三通、大三通後，金門、馬祖由前線轉為交流據點","現況：兩岸交流頻繁，但中共不放棄武力犯臺、堅持一個中國，持續打壓我國外交空間"],"example":"金門北山播音牆民國56年向對岸心戰喊話，民國80年停播轉型觀光。"},{"heading":"經濟發展及其影響","points":["遷臺初期經濟重整：民國38年貨幣改革發行新臺幣，以4萬元舊臺幣換1元新臺幣，穩定物價與金融秩序","土地改革依序為三七五減租（38）、公地放領（40）、耕者有其田（42），使佃農轉型為自耕農，提高農業生產","農復會（中國農村復興聯合委員會）1948年由中美合組，推動土地改革、改組農民組織、發放美援","農復會1979年改組（後併為農委會），2023年農委會改制為農業部","民國40年代進口替代：以「農業培養工業」，外銷農產品賺外匯，發展紡織、食品加工等民生輕工業","進口替代同時限制外國相關產品進口；美援提供原料與技術","美援期間成立「懷特顧問公司」協助規劃款項運用，如協助茶葉公司轉型投資化肥廠，配合進口替代政策","推廣「以麵代米」：以美國小麥製麵粉供民眾換取白米，稻米外銷賺外匯，使麵食普及並奠定加工食品產業基礎","設立加工出口區背景：國內市場飽和、人口成長快速帶來就業需求","民國50年代出口導向：利用廉價勞力，在高雄、臺中等地設加工出口區吸引外資，兼具自由貿易區與工業區功能","出口導向輸出食品、成衣等輕工業產品，工業產值超越農業，經濟型態轉為以工業為主","民國60年代中東產油國爆發戰爭引發國際能源危機，蔣經國推動十大建設，加強交通、能源並發展重工業","十大建設六項交通：中山高速公路、鐵路電氣化、北迴鐵路、中正國際機場、臺中港、蘇澳港","十大建設三項重工業：大煉鋼廠、中國造船廠、石油化學工業；一項能源：核能發電廠，提供穩定電力發展工業","民國60年代起臺灣與香港、南韓、新加坡經濟快速成長，並稱「亞洲四小龍」","民國70年代產業升級：因工資上漲、環保意識抬頭及面臨國際競爭，轉向資訊、電子等高科技產業","民國69年設新竹科學工業園區發展高科技；民國80年代後自由化、國際化，面臨產業外移","經濟新課題：生產成本提高、勞力不足→政府引進（雇用）外籍移工（國際移工）","推動「南向」政策鼓勵投資東南亞，分散對中國投資的風險","工業化使農業重要性下降，農村人口外流、老化嚴重"],"example":"「芭比娃娃家庭代工、加工區女工車縫成衣」＝民國50年代出口導向。","fig":{"src":"../assets/fig/history/u5-s6.svg","cap":"十大建設的分布"}},{"heading":"社會文化的變遷","points":["戰後文化演變順序：中華文化→美國流行文化→鄉土文學→本土與原住民族文化→多元文化","戰後初期提倡中華文化以清除日本影響：推行國語運動、禁止公開場合說方言，使部分族群母語式微","戰後政府以「山胞」統稱高山族，要求以漢名登記戶籍、推行國語，造成族群身分認同與語言文化消失","民國40、50年代提倡反共文學；韓戰後美援來臺，美式飲食、音樂、電影等美式文化流行","戰後電影：1950年代配合官方政治宣傳；1960年代避免暴露社會黑暗；1970年代愛情、武俠、功夫、喜劇；1980年代初臺灣新電影","二二八事件涉及敏感政治問題，戒嚴時期成為歷史禁忌，電影不可能觸及，解嚴後才漸受重視","鄉土文學背景：民國60年代退出聯合國，內政與外交面臨嚴厲挑戰；經濟起飛造成城鄉差距擴大，知識分子關懷在地人民生活","鄉土文學以寫實手法關注農工小人物，如黃春明《兒子的大玩偶》","都市化帶來空氣汙染、噪音、城鄉差距問題；鄉村人口外移與老化，傳統產業發展困難並產生隔代教養問題","民國70年代經濟發展帶來環保、勞工問題；民國76年解嚴後社會運動蓬勃：反六輕、反核四，保障工作權、兩性平權","原住民正名、還我土地運動；民國83年修憲改稱「原住民」","解嚴後客家人走上街頭「還我母語」（還我客家話運動）；21世紀政府頒布《客家基本法》、成立客家委員會","2022年將12月28日全國客家日調整為「還我母語運動日」","民國70年代後政治社會逐漸開放、資訊普及，本土文化與原住民族文化受重視","新住民與國際移工增加，使臺灣文化更加豐富多元，族群平等成為主流價值"],"example":"「吉野村」改名「吉安鄉」，是戰後消除日本色彩、強化國家認同的例子。"}],"confusions":[{"a":"日治臺灣總督府","b":"戰後臺灣省行政長官公署","diff":"總督府是日本殖民統治機構（民國前17～民國34年）；行政長官公署是民國34年中華民國接收臺灣所設，二二八後改為臺灣省政府，兩者首長都握行政、軍事大權","tip":"「總督」＝日治；「陳儀、行政長官」＝戰後初期"},{"a":"《動員戡亂時期臨時條款》","b":"《戒嚴令》","diff":"臨時條款（民國37～80年）擴大總統職權、取消連任限制，由李登輝廢止；戒嚴令（民國38～76年）限制人民集會結社言論出版自由，由蔣經國解除","tip":"「總統權力」找臨時條款，「人民自由」找戒嚴令"},{"a":"雷震事件","b":"美麗島事件","diff":"雷震事件是民國49年《自由中國》批評時政並籌組中國民主黨；美麗島事件是民國68年美麗島雜誌社在高雄遊行呼籲解嚴","tip":"自由中國、組黨→雷震；高雄、人權日遊行→美麗島"},{"a":"彈性外交","b":"務實外交","diff":"彈性外交（民國60～77年）仍堅持中華民國是中國唯一合法政府，改與無邦交國經貿文化交流；務實外交（民國77年起）不再堅持代表全中國，視兩岸為分裂分治的政治實體","tip":"退出聯合國後→彈性；李登輝繼任、分裂分治、參與國際組織→務實"},{"a":"三不政策","b":"一國兩制","diff":"三不政策（不接觸、不談判、不妥協）是我國在政治對峙時期的主張；一國兩制是中共的統一主張","tip":"三不＝我國；一國兩制、和平統一、三通四流＝中共"},{"a":"陸委會、海基會","b":"國臺辦、海協會","diff":"陸委會是行政院下的官方機構，負責大陸政策，委託民間團體海基會實際處理兩岸交流；海協會是中共國臺辦下的對口單位","tip":"「委員會」＝官方、「基金會」＝民間白手套；「基」在臺灣、「協」在對岸"},{"a":"進口替代","b":"出口導向","diff":"進口替代（民國40年代）發展民生輕工業以減少進口；出口導向（民國50年代）設加工出口區吸引外資、外銷輕工業產品","tip":"「減少進口、滿足內需」→進口替代；「加工出口區、外銷賺外匯」→出口導向"},{"a":"十大建設","b":"產業升級","diff":"十大建設（民國60年代）因能源危機推動交通、能源、重工業；產業升級（民國70年代）發展資本與技術密集的高科技產業","tip":"港口、高速公路、鋼鐵造船→十大建設；半導體、科學園區→產業升級"},{"a":"日治時期國語運動","b":"戰後初期國語運動","diff":"日治時期由臺灣總督府推行日語以同化臺人，知識分子以日語吸收知識；戰後由行政長官公署、省政府推行中華民國國語（華語）以推廣中華文化、去日本化，方言受限、本土文化受打壓","tip":"國語＝日語→日治同化；國語＝華語、禁說方言→戰後去日本化"}],"terms":[{"term":"臺灣省行政長官公署","def":"民國34年政府為接收臺灣而設立的機構，由陳儀擔任行政長官，集行政、軍事大權，二二八事件後改為臺灣省政府。"},{"term":"二二八事件","def":"民國36年因專賣局查緝私菸誤傷民眾引發的全臺衝突，政府派兵鎮壓並清鄉，造成大量傷亡與族群隔閡。"},{"term":"清鄉","def":"二二八事件後軍警藉清查戶口、收繳武器等方式，持續掃蕩反政府分子的行動。"},{"term":"動員戡亂時期臨時條款","def":"民國37年因國共內戰制定，擴大總統職權並取消總統連任限制，民國80年由李登輝廢止。"},{"term":"戒嚴","def":"民國38年臺灣省政府頒布《戒嚴令》防止共產勢力滲透，限制人民集會、結社、出版、言論等自由，民國76年解除。"},{"term":"白色恐怖","def":"民國40、50年代政府以整肅匪諜等罪名，不依法律程序逮捕審判異議分子，造成許多冤案的現象。"},{"term":"萬年國會","def":"戒嚴時期中央民意代表長期未全面改選的現象，民國80年終止動員戡亂後才全面改選。"},{"term":"山地平地化","def":"戰後初期原住民政策方針，稱原住民為山地同胞、要求改漢名、推行國語，使其融入漢人體系。"},{"term":"黨外","def":"泛指國民黨以外的政治勢力，民國60、70年代常用來稱呼從事民主運動的人士。"},{"term":"野百合學運","def":"民國79年3月大學生聚集中正紀念堂廣場，提出廢除臨時條款、解散萬年國會等政治改革訴求。"},{"term":"美援","def":"韓戰後美國對我國提供的軍事與經濟援助，包括民生物資、工業原料與技術，有助臺灣經濟發展。"},{"term":"臺灣關係法","def":"民國68年美國與我國斷交後由美國國會通過，維持雙方非官方的經貿實質往來並出售防禦性武器。"},{"term":"彈性外交","def":"民國60年退出聯合國後的外交策略，著重與無邦交國發展經貿、文化交流，仍堅持中華民國為中國唯一合法政府。"},{"term":"務實外交","def":"民國77年李登輝繼任總統後推動，不再堅持代表全中國，以經濟實力與民主成就積極參與國際組織。"},{"term":"古寧頭戰役","def":"民國38年10月共軍進犯金門，國軍戰勝；與八二三炮戰同屬兩岸武力對抗時期的重要戰役。"},{"term":"八二三炮戰","def":"民國47年共軍猛烈炮擊金門，國軍在美國協防下反擊，此後兩岸不再有大規模武力對抗。"},{"term":"三通四流","def":"中共在政治對峙時期的統戰主張：通郵、通航、通商，以及經濟、文化、科技、體育交流。"},{"term":"一國兩制","def":"中共對臺灣、香港、澳門提出的統一主張，允許實施不同政經制度並享有有限自治，但不尊重我國主權。"},{"term":"海基會","def":"海峽交流基金會，民國80年由陸委會委託的民間團體，負責處理兩岸交流事務，對口為中共海協會。"},{"term":"辜汪會談","def":"民國82年海基會董事長辜振甫與海協會會長汪道涵在新加坡舉行的兩岸第一次正式會談。"},{"term":"農復會","def":"中國農村復興聯合委員會，1948年中美合組，推動土地改革與美援發放，奠定臺灣農業復興基礎，1979年改組，後併為農委會。"},{"term":"進口替代","def":"民國40年代經濟政策，以農業培養工業，發展紡織等民生輕工業並限制外國產品進口，減少對進口的依賴。"},{"term":"加工出口區","def":"民國50年代出口導向政策下於高雄等地設立，給予外商免稅等優惠，吸引外資發展勞力密集產業。"},{"term":"出口導向","def":"民國50年代經濟政策，設加工出口區吸引外資，外銷食品、成衣等輕工業產品，使臺灣轉為以工業為主。"},{"term":"十大建設","def":"民國60年代行政院長蔣經國為因應國際能源危機推動的交通、能源與重工業基礎建設。"},{"term":"亞洲四小龍","def":"民國60年代起經濟快速成長的臺灣、香港、南韓、新加坡四地的合稱。"},{"term":"新竹科學工業園區","def":"民國69年設立，推動資本與技術密集的高科技產業，使臺灣成為電子產業重鎮。"},{"term":"南向政策","def":"因生產成本提高、勞力不足，政府鼓勵企業投資東南亞等地，以分散對中國投資的風險。"},{"term":"國語運動","def":"戰後政府為清除日本文化影響、強化國家認同而推廣國語，禁止公開場合說方言，使部分母語式微。"},{"term":"鄉土文學","def":"民國60年代興起的文學風潮，以寫實手法關注農民、勞工等小人物生活，如黃春明《兒子的大玩偶》。"},{"term":"還我母語運動","def":"解嚴後客家族群為搶救族群文化、爭取語言權益平等而發起的街頭運動，如今12月28日訂為還我母語運動日。"}],"timeline":[{"time":"1945（民國34年）","event":"日本投降，成立臺灣省行政長官公署，陳儀接收臺灣"},{"time":"1947（民國36年）","event":"二二八事件爆發，事後改設臺灣省政府"},{"time":"1948（民國37年）","event":"制定《動員戡亂時期臨時條款》"},{"time":"1949（民國38年）","event":"5月20日起實施戒嚴、發行新臺幣、三七五減租；10月中華人民共和國成立、古寧頭戰役；12月政府遷臺"},{"time":"1950（民國39年）","event":"韓戰爆發，美國派第七艦隊協防臺海；開始實施地方自治"},{"time":"1951～1954（民國40～43年）","event":"綠島新生訓導處關押大批政治犯（白色恐怖）"},{"time":"1953（民國42年）","event":"實施耕者有其田"},{"time":"1954（民國43年）","event":"簽訂《中美共同防禦條約》"},{"time":"1958（民國47年）","event":"八二三炮戰"},{"time":"1960（民國49年）","event":"雷震事件"},{"time":"1966（民國55年）","event":"高雄設立加工出口區（民國50年代出口導向）"},{"time":"1970年代（民國60年代）","event":"推動十大建設；鄉土文學興起"},{"time":"1971（民國60年）","event":"退出聯合國"},{"time":"1979（民國68年）","event":"美國與我國斷交、訂《臺灣關係法》；美麗島事件"},{"time":"1980（民國69年）","event":"設立新竹科學工業園區"},{"time":"1986（民國75年）","event":"黨外人士成立民主進步黨，挑戰戒嚴時期的黨禁"},{"time":"1987（民國76年）","event":"解除戒嚴，開放黨禁、報禁與大陸探親"},{"time":"1988（民國77年）","event":"蔣經國過世，李登輝繼任總統，外交轉向務實外交"},{"time":"1990（民國79年）","event":"野百合學運"},{"time":"1991（民國80年）","event":"終止動員戡亂；成立海基會；加入APEC"},{"time":"1993（民國82年）","event":"辜振甫與汪道涵在新加坡舉行辜汪會談，為兩岸第一次正式會談"},{"time":"1996（民國85年）","event":"首次總統直選"},{"time":"2000（民國89年）","event":"首次政黨輪替"},{"time":"2001～2008（民國90～97年）","event":"開放小三通（90年）、加入WTO（91年）、兩岸大三通（97年）"},{"time":"2008（民國97年）","event":"二次政黨輪替"},{"time":"2016（民國105年）","event":"蔡英文就任總統，為臺灣首位女性元首"}],"sources":[{"name":"戰後初期蓬萊白米價格曲線","gist":"1946～1949年米價由每公斤數十元暴漲到上萬元。","clue":"米價短期暴漲→戰後初期米糧短缺、物價飛漲（民國38年發行新臺幣前）"},{"name":"陽春麵漲價漫畫","gist":"一碗陽春麵從1000元漲到2000、3000元，反映戰後初期物價飛漲。","clue":"物價短期暴漲→戰後初期經濟惡化（二二八背景）"},{"name":"二二八事件相關史料","gist":"記載查緝私菸誤傷民眾、民眾包圍公署，或臺籍人士要求改革行政長官公署的訴求。","clue":"專賣局、私菸、陳儀、處理委員會、派兵清鄉→二二八事件"},{"name":"陳儀致中央請兵電報","gist":"稱事件係奸匪利用御用紳士、流氓及「臺人治臺」排外觀念造成，請中央速調步兵來臺。","clue":"臺人治臺、請調兵來臺→民國36年二二八事件"},{"name":"二二八事件國軍鎮壓路線圖","gist":"標示主要衝突與傷亡區域，及國軍自基隆、高雄登陸後向全臺推進鎮壓的路線。","clue":"基隆／高雄登陸、鎮壓路線→民國36年二二八事件"},{"name":"二二八紀念碑","gist":"碑體四柱各加「二」字橫架合計「八」，頂端有裂痕的鐘象徵受傷的人民。","clue":"二、二、八造型→二二八事件對族群關係的影響"},{"name":"臺灣省政府、臺灣省警備總司令部戒嚴令","gist":"民國38年5月19日由主席兼總司令陳誠布告，自5月20日零時起全省戒嚴，並列禁止事項與處死刑罪行。","clue":"警備總司令部、陳誠、全省戒嚴→民國38年"},{"name":"國軍反攻大陸疆域圖","gist":"箭頭由臺灣出發指向中國大陸及北方俄羅斯領土的「國軍反攻」想像地圖。","clue":"國軍反攻、反共抗俄→武力對抗時期「光復大陸」主張"},{"name":"戒嚴時期出版管制規定","gist":"出版品不得宣傳共產主義、詆毀元首、違背反共抗俄國策。","clue":"反共抗俄、禁書、限制集會結社→戒嚴時期（民國38～76年）"},{"name":"防匪諜標語","gist":"「匪諜自首，既往不究」「隱瞞匪諜，與匪同罪」「公共場所，不談國家機密」等標語牌。","clue":"匪諜、自首、與匪同罪→白色恐怖（民國40、50年代）"},{"name":"美援麵粉宣傳海報","gist":"「中美合作」麵粉袋，鼓吹小麥比白米好。","clue":"中美合作握手標誌→韓戰後1950年代美援"},{"name":"兩岸往來統計表","gist":"鳳梨罐頭外銷或國人出國統計中，某地在特定年代數據為0。","clue":"1950年後貿易為0→中國大陸（兩岸分治）；1987年前無人前往→解嚴前未開放探親"},{"name":"聯合國大會2758號決議","gist":"1971年聯大以76票贊成通過恢復中華人民共和國合法權利，承認其為中國唯一合法代表。","clue":"2758、恢復中華人民共和國席位→民國60年我國退出聯合國"},{"name":"十大建設示意圖","gist":"標示中山高速公路、北迴鐵路、鐵路電氣化、中正國際機場、臺中港、蘇澳港、大煉鋼廠、中國造船廠、石油化學工業、核能發電廠。","clue":"交通、港口、鋼鐵造船石化、核電→民國60年代十大建設（因應能源危機）"},{"name":"中美斷交抗議照片／聲明","gist":"民眾抗議卡特政府與匪建交，或總統抗議美國承認匪偽政權。","clue":"卡特、與匪建交、《臺灣關係法》→民國68年"},{"name":"黨外雜誌（美麗島、民主陣線等）","gist":"1980年代黨外雜誌要求新聞言論自由、擴大政治參與。","clue":"黨外、爭取言論自由、辦報不必核准→訴求解除戒嚴"},{"name":"解嚴後社會運動次數示意圖","gist":"1990年代後臺灣每年抗議、遊行累計次數的變化折線圖。","clue":"抗議、遊行次數大增→解嚴（民國76年）後社會運動蓬勃"},{"name":"宣告動員戡亂時期終止總統令稿","gist":"民國80年總統令稿，事由為宣告動員戡亂時期終止，由行政院院長郝柏村副署。","clue":"動員戡亂時期終止、郝柏村→民國80年李登輝總統"},{"name":"南向政策合作地區分布圖","gist":"標示南亞、東南亞、大洋洲國家為投資合作對象。","clue":"東南亞、南亞投資、分散對中國投資風險→南向政策（民國80年代以後）"},{"name":"臺灣經濟成長率曲線圖（1952～2006年）","gist":"1974年前後與2001年前後各有一次明顯下跌，後者甚至出現負成長。","clue":"1970年代谷底→能源（石油）危機、十大建設；2001年前後負成長→全球景氣衰退"}]},{"unit":6,"part":"中國與東亞史","title":"商周至隋唐時期","summary":"從商周封建、東周變革到秦朝中央集權，再到察舉、九品官人法、科舉的選才演變，以及農牧互動、胡漢融合、唐代文化外傳；會考多以史料關鍵字判斷時代與制度。","sections":[{"heading":"商周的封建制度","points":["商朝：西元前16世紀建於黃河下游；殷墟陸續發現刻在甲骨上的文字（甲骨文），證實商朝已進入歷史時代","商王以分封承認各地既有勢力，維繫商王共主地位，但彼此關係鬆散、商王控制力有限，是封建的雛形","西周：周人興起於黃河中游，滅商後為加強對東方新征服地區的控制，分封宗族、親戚與功臣為諸侯，授予土地、爵位、人民、財物","諸侯帶軍隊前往封地建立封國、駐守要地以護衛王室；各封國是王室的戰略據點，學者稱為「武裝殖民」","周王為天下共主，諸侯的身分與領地世襲","宗法制度：以血緣親疏確立貴族尊卑與繼承順序；禮樂制度：依身分等級使用不同器物與儀式","商周時期青銅器是藝術品，也是區分貴族與平民、彰顯貴族身分的表徵","社會分貴族、平民、奴隸：貴族世襲權力、壟斷禮樂與官職，統治平民與奴隸；只有貴族能受教育，社會流動不易","西周晚期血緣聯結淡薄、諸侯坐大，又遭犬戎入侵，周平王將國都由鎬京東遷雒邑，進入東周","比較：西周首都鎬、政治重心在周王室；東周首都雒邑，王室衰微、諸侯稱霸稱王，禮崩樂壞、平民崛起"],"example":"銘文「你與子孫將世代享有燕國的封地」＝天子分封、諸侯世襲，是封建制度的運作。"},{"heading":"東周的變革與封建崩解","points":["東周（前8～前3世紀）分春秋、戰國；王室衰微、諸侯崛起，爭霸兼併，封建秩序瓦解，同時平民崛起","各國為富國強兵，重用有才能的士人或平民推動改革，用人唯才；貴族沒落、平民崛起","設立郡縣：地方首長由國君任免、不再世襲，強化中央對地方的控制","編戶齊民：將人民編入戶籍以掌握人力，作為徵稅、徵兵、分派勞役的依據；並頒布法律使貴族與平民同受規範","西元前4世紀秦國任用商鞅變法：以法治、編列戶籍富國強兵，加強對人民的控制，使平民納稅服勞役","商鞅變法提倡軍功、按軍功授爵位，奠定秦國富強基礎，為秦統一奠基","東周流落民間的貴族以學識謀生，私人講學興起、平民崛起，知識不再被貴族壟斷，平民有機會受教育","東周各種學說蓬勃發展，如主張施行仁政的儒家"],"example":"看到「登錄戶籍」的人口、年齡資料，目的就是掌握人力、徵收賦稅與勞役。"},{"heading":"秦朝的中央集權","points":["西元前221年秦王嬴政滅六國、統一天下，以「皇帝」為尊號，自稱始皇帝","東周鄒衍提出「五德終始」說，以五行相生相剋解釋朝代更替；秦始皇自認水德取代周的火德，崇尚黑色","秦始皇東巡時在泰山舉行最早的封禪大典，以五行之說強化政權正當性，並以小篆刻石記功","秦始皇認為「天下苦戰不休，以有王侯」，戰亂源於分封王侯，故廢封建、全國推行郡縣制以求天下寧息","中央體制：君主之下設丞相；地方郡設郡守、縣設縣令，郡縣長官皆由中央任免、不再世襲，確立中央集權","秦朝社會結構為皇帝→官僚→平民，以法治國","統一前各國文字、貨幣各異（齊刀幣、楚蟻鼻錢、韓趙魏布錢）；秦統一文字為小篆、貨幣為圓形方孔的半兩錢","並統一度量衡、車軌，促進各地文化與經濟交流","厲行法治、焚書坑儒控制思想，役使百姓修長城、陵墓等大型工程","高壓統治與過度耗損人力引發民怨，百姓起而推翻秦朝","秦朝雖短亡，但中央集權的政治體制確立，為後代沿用，成為日後國家統治的常態"],"example":"封建＝天子分封諸侯、諸侯世襲；郡縣＝皇帝→郡→縣，官員由皇帝派任。"},{"heading":"選才制度的發展","points":["選才制度是統治者為有效控制地方、吸納人才而選拔官員的制度","歷代任官標準：西周血緣→東周個人才華（用人唯才）→漢道德品行與儒家經學→魏晉家世→隋唐至清分科考試","秦代與漢初以吏為師，多任用熟悉法律、官方文書的人才","漢武帝因政權擴大與人口增長增設選才辦法：重視儒家，察舉由地方推舉「孝子」「廉吏」任官","漢武帝並設太學教授儒家經典，優秀者任官（經學取士）","漢代官方崇尚儒學、經學取士，使儒家成為中國文化主流思想，並形成世族傳承經學、經學傳家、累世為官的世族","經學發展趨勢：東周萌芽→漢代因漢武帝崇儒、經學取士而興起至極盛→魏晉南北朝中衰","魏晉南北朝政局分裂、社會動盪，人民流離失所，地方難以推舉人才，曹魏（3世紀）改由中央選任官員而創九品官人法","九品官人法：中正官依家世、才能、品德將士人分九等授官","九品官人法重家世，造成「上品無寒門，下品無世族」；世族講究門當戶對","世族掌控政治權力，擁有土地且享有減免賦稅等經濟特權，對統治者維繫政權造成很大影響","魏晉南北朝高門士族：南方有南遷的瑯琊王氏、陳郡謝氏與江南吳郡朱、張；北方有博陵崔、清河崔等及漢化鮮卑元氏","東晉王導、謝安所屬的王、謝兩族世代為高官；「舊時王謝堂前燕，飛入尋常百姓家」反映世族後來沒落","隋代（6世紀末）為抑制世族創科舉，由士人報名參加考試取才；唐朝擴大實施、標準漸完善，唐以後沿用至清末","社會流動是個人社會地位發生移動（向上或向下）的現象","科舉使平民可憑個人努力入仕，平民任官機會增加、促進社會流動，也帶動讀書教育風氣"],"example":"世族興衰：漢朝形成（萌芽：經學傳家、累世當官）→魏晉南北朝鼎盛→隋唐科舉與唐末戰亂後沒落、逐漸退出政治舞臺。"},{"heading":"農牧民族的互動與絲路","points":["黃河流域農業民族與北方草原游牧民族長期互動","草原民族在長城以北、部落聯盟、畜牧為主，物產不足時靠貿易或南下掠奪取得資源","農業民族在長城以南、中央集權，以修長城、武力征伐對抗草原民族","歷代主要草原民族：西周犬戎、東周至漢匈奴、魏晉南北朝胡族（如鮮卑）、唐突厥","東周晚期各國築長城抵禦匈奴；秦始皇連接各國長城防範匈奴，長城成為農牧分界線","漢初國力較弱，對匈奴採和親政策；漢武帝時才出兵討伐匈奴","漢武帝派張騫出使西域（今新疆、中亞一帶），原為聯絡西域國家夾擊、抵制匈奴（軍事目的）","張騫通西域增進對西域的認識，促成絲路：長安→西域→西亞→大秦（羅馬帝國），東西貿易更活絡","西元前2世紀匈奴自月氏奪得河西地區；漢朝後設酒泉、武威、張掖、敦煌四郡並駐軍屯墾，暢通絲路","中國絲綢大量銷往西方，經多次轉手運到羅馬，一兩絲綢價值一兩黃金，使羅馬黃金外流","西域的音樂、繪畫、雜技、葡萄、胡麻等物產漢代傳入中國，佛教也經絲路傳入"],"example":"秦漢主要外患＝匈奴；隋唐主要外患＝突厥；契丹、女真是宋代以後。","fig":{"src":"../assets/fig/history/u6-s5.svg","cap":"漢代的絲路：張騫通西域後，東西貿易往來頻繁"}},{"heading":"魏晉南北朝的胡漢融合與江南開發","points":["魏晉南北朝分合：三國（魏）→西晉短暫統一→北方十六國、北朝與南方東晉、南朝對峙→隋統一","漢末許多北方草原民族陸續南遷黃河流域，被漢人通稱為「胡」，與漢人雜處、互動頻繁，因風俗差異常起衝突","西晉末年（4世紀初）永嘉之禍：胡人攻陷洛陽，晉室南渡在長江流域建立東晉，中國陷入南北分裂","胡人在黃河流域建立政權，致力胡漢融合以穩固統治；魏晉南北朝是民族融合的重要時期","鮮卑族北魏首都初在平城（今山西大同），採北重南輕；向南擴張後戰略轉為南重北輕","北魏孝文帝以「南伐」名義由平城遷都洛陽，並改革舊俗推動漢化","孝文帝漢化：改漢姓（拓跋改元）、說漢語、穿漢服、鼓勵胡漢通婚","2023年洛陽發現北魏皇家倉窖遺址，收存經運河調運的糧食","胡漢融合也有胡化：漢人衣著飲食受胡族影響（如胡人食用乳製品的習慣），奠定隋唐盛世基礎","南方：北方漢人南遷長江中下游，帶來農耕技術與勞動力，加速江南開發，奠定經濟重心南移基礎"],"example":"「新亭對泣」＝永嘉之禍後世族南渡；「分道揚鑣」＝孝文帝遷都洛陽後胡漢官員爭路。","fig":{"src":"../assets/fig/history/u6-s6.svg","cap":"北魏孝文帝遷都洛陽"}},{"heading":"隋唐的民族互動","points":["隋朝結束魏晉南北朝分裂，重新統一中國","唐初國力未穩，對突厥採和親；統一後北伐，唐太宗大敗（滅）東突厥，強化對西域與絲路的掌控","唐太宗滅東突厥後，西北各族尊為「天可汗」，唐帝國成為東亞秩序盟主；唐朝國力強盛、積極開拓疆土","唐代皇室具胡人血統（如唐太宗鬍鬚捲曲，有「髭聖」之稱），對外族採平等開放態度，外族亦可任官","外族商人、僧侶、留學生紛紛來華，大量移居中國","首都長安為國際性大都市，胡商雲集；唐人生活受西域文化影響，流行胡服、胡食、胡樂、胡舞，深染「胡風」","「漢戴胡帽，胡戴漢帽」體現民族文化交流；唐三彩常以胡人和駱駝為題材，反映胡風盛行"],"example":"看到胡衫、胡帽、翻領窄袖、唐三彩，就判斷是兼容並蓄的唐代。"},{"heading":"宗教傳入與中國文化外傳","points":["佛教源於印度、早期在西域流行，漢代經絲路傳入中國","魏晉南北朝戰亂頻繁，宗教成為精神寄託，加上帝王提倡、佛經翻譯而廣為流傳，建龍門、雲岡石窟、莫高窟","北魏君主提倡佛教，在京城附近開鑿石窟雕佛像象徵皇帝，呈現宗教依靠皇權、皇權藉宗教強化統治","唐初玄奘前往印度（天竺）取經，回國後主持佛經翻譯，促進佛教鼎盛並中國化（如禪宗），再傳往日本、朝鮮半島","長安大慈恩寺藏經塔（大雁塔）收藏玄奘自印度帶回的佛經、塑像，寺中設翻經院譯經","伊斯蘭教唐代（7世紀）由阿拉伯商人傳入中國；另有景教、摩尼教等，展現宗教多元","大食第三任統治者奧斯曼時遣使拜會唐高宗、介紹伊斯蘭教義，一般認定為伊斯蘭教傳入中國的開端","唐代大食遣使來華共37次、日本派遣唐使19次，新羅除使節外也有大批留學生來華","日本、新羅派遣唐使、留學生學習漢字、曆法、儒學、佛教與律令制度，形成東亞文化圈：如日本模仿唐制推動大化革新、新羅被稱為「君子國」","日本與新羅都城仿長安城規畫興建，呈棋盤狀格局，反映唐文化外傳","日本7世紀中期模仿唐制推動大化革新（唐化運動），學習儒家思想、律令制度、文字，建立以天皇為中心的集權國家","4世紀中國儒家思想與佛教東傳朝鮮半島；5～7世紀高句麗、新羅、百濟三國鼎立時佛教快速發展，一度成為國教","新羅7世紀中期統一朝鮮半島，為加強中央集權並合法化統治而修建佛寺；僧侶經唐西行求法，發展出韓國特色佛教","新羅被稱為「君子國」：全力模仿中國文字、曆法、儒學和佛教","唐太宗時文成公主嫁吐蕃（今西藏）和親促進漢藏交流，並宣揚佛教、將農業技術帶入西藏","唐與大食（阿拉伯帝國）爆發怛羅斯之役，唐軍戰敗，被俘士兵中有造紙工匠，造紙術（漢代蔡倫改良）因而西傳"],"example":"東亞文化圈四要素：漢字、儒學、中國化佛教、律令（典章）制度。","fig":{"src":"../assets/fig/history/u6-s8.svg","cap":"唐代文化的對外交流"}}],"confusions":[{"a":"西周","b":"東周","diff":"西周首都鎬、周王室為政治重心、封建身分世襲階級嚴明；東周首都雒邑、王室衰微諸侯稱霸、封建瓦解平民崛起","tip":"鎬、封建成熟→西周；雒邑、春秋戰國、禮崩樂壞→東周"},{"a":"封建制度","b":"郡縣制度","diff":"封建是天子分封土地爵位給諸侯、世襲且地方獨立性強；郡縣是地方長官由國君或皇帝直接任免、不世襲，有助中央集權","tip":"看到「世襲、封地、諸侯」→封建；「任免、直轄、不再世襲」→郡縣"},{"a":"西周的貴族","b":"魏晉南北朝的世族","diff":"貴族靠血緣分封而世襲身分；世族是漢代經學傳家、累世為官形成，再靠九品官人法重家世而壟斷官職","tip":"血緣、禮樂、宗法→貴族；家世、門第、門當戶對、上品無寒門→世族"},{"a":"察舉／經學取士","b":"九品官人法","diff":"察舉由地方推舉孝子廉吏、太學考核儒學；九品官人法由中正官依家世、才德把士人評為九等授官","tip":"孝廉、太學、儒家→漢代；中正官、九品、家世→曹魏以後"},{"a":"九品官人法","b":"科舉制度","diff":"九品官人法由官員評定、實際重家世，助長世族；科舉以考試取才，目的在抑制世族、增加平民任官機會","tip":"評定等第→九品；考試、進士、試卷、金榜→科舉（隋至清末）"},{"a":"草原民族","b":"農業民族","diff":"草原民族在長城以北、部落聯盟、以畜牧為主，常以貿易或掠奪取得資源；農業民族在長城以南、中央集權、以農業為主，修長城或武力征伐抵禦","tip":"部落、畜牧、南下掠奪→草原；長城以南、農耕、築長城→農業"},{"a":"張騫出使西域的目的","b":"張騫出使西域的影響","diff":"目的是聯絡西域國家共同抵制匈奴（軍事外交）；影響是增進對西域認識、開通絲路，促成東西貿易與文化交流","tip":"問「目的」選對抗匈奴；問「影響」選絲路、西域物產東傳、東西貿易活絡"},{"a":"漢初對匈奴和親","b":"唐代文成公主嫁吐蕃","diff":"漢初國力弱，和親是換取邊境和平的權宜之計；文成公主嫁吐蕃在唐太宗國力強盛時，促進漢藏交流、帶入佛教與農業技術","tip":"匈奴、國力弱→漢初和親；吐蕃、西藏、佛教→唐代文成公主"},{"a":"北魏孝文帝漢化","b":"唐代胡風盛行","diff":"孝文帝是胡人君主主動學漢文化（胡人漢化）；唐代是漢人生活吸收胡人文化（漢人胡化）","tip":"遷都洛陽、改漢姓→北魏；胡服、胡食、唐三彩、天可汗→唐"},{"a":"張騫出使西域","b":"遣唐使","diff":"張騫是漢朝派往西域、原為聯合夾擊匈奴，結果促成絲路；遣唐使是日本派往唐朝學習制度文化","tip":"長安→西域→羅馬、絲綢→漢；日本、新羅→長安、大化革新→唐"}],"terms":[{"term":"封建","def":"王朝統治者將土地與爵位分封給諸侯，使其建立封國，並擁有世襲的領地與人民，以護衛王室的制度。"},{"term":"宗法制度","def":"西周以血緣親疏確立貴族尊卑關係與身分繼承順序，與天子血緣愈親近者地位愈尊貴、權力愈大。"},{"term":"禮樂制度","def":"西周規範貴族依身分等級使用不同的器物與儀式，以展現地位高低、維繫封建秩序，平民奴隸不得使用。"},{"term":"郡縣制","def":"將地方劃為郡、縣，長官由國君或皇帝直接任免且不世襲；東周已出現，秦朝推行全國。"},{"term":"編戶齊民","def":"東周各國將人民編入戶籍並頒布法律，使臣民統一受國君管理，以掌握人力、徵稅徵兵。"},{"term":"商鞅變法","def":"西元前4世紀秦國任用商鞅改革，厲行法治、編列戶籍、獎勵耕織、按軍功授爵，奠定秦國富強與統一基礎。"},{"term":"皇帝制度","def":"秦王嬴政統一天下後以「皇帝」為尊號，自稱始皇帝，成為中國兩千多年帝制的開端。"},{"term":"五德終始","def":"東周鄒衍以五行相生相剋解釋朝代更替的理論，用以強調政權的神聖性與合理性；秦自認水德而尚黑。"},{"term":"封禪","def":"帝王在泰山祭祀天地、宣告功業以確立王朝合法性與神聖性的典禮；秦始皇最早舉行，漢武帝等也曾舉行。"},{"term":"察舉","def":"漢武帝時由地方長官定期向中央推舉「孝子」「廉吏」並授予官職的選才方式。"},{"term":"太學","def":"漢武帝在中央設立的學校，由博士教授儒家經典，考核成績優秀的學生可以任官。"},{"term":"世族","def":"漢代經學傳家、累世為官形成的大家族，魏晉南北朝藉九品官人法壟斷官職並享經濟特權。"},{"term":"九品官人法","def":"曹魏創立，中正官依家世、才能、品德將士人分為九等授官，造成上品無寒門、下品無世族。"},{"term":"科舉制度","def":"隋朝為抑制世族而創的考試選才制度，唐以後沿用至清末，增加平民任官機會、促進社會流動。"},{"term":"和親","def":"漢初國力較弱，以宗室女子嫁給匈奴單于並贈送財物，換取邊境和平的政策；唐代文成公主嫁吐蕃也屬和親。"},{"term":"西域","def":"漢代對玉門關、陽關以西地區的稱呼，約為今日新疆、中亞一帶，是絲路必經之地。"},{"term":"絲路","def":"漢代張騫通西域後，由長安經西域、西亞通往大秦（羅馬帝國）的商路，中國絲綢大量西傳。"},{"term":"永嘉之禍","def":"西晉末年（4世紀初）胡人攻陷洛陽、俘虜皇帝，晉室南渡建立東晉，中國陷入南北分裂。"},{"term":"天可汗","def":"唐太宗擊敗東突厥後，西北各族所尊奉的稱號，代表唐朝為東亞國際秩序的盟主。"},{"term":"唐三彩","def":"唐代以黃、綠、褐等色釉燒製的陶器，常以胡人、駱駝為造型，反映唐代胡風盛行。"},{"term":"佛教中國化","def":"佛教傳入中國後與儒、道等本土思想融合，發展出禪宗等具本土特色的宗派，再傳往日本、朝鮮。"},{"term":"遣唐使","def":"日本派往唐朝的使節團，隨行有留學生、留學僧，學習中國政治制度與思想文化。"},{"term":"大化革新","def":"7世紀日本天皇模仿唐朝律令制度推動的改革，建立中央集權國家。"},{"term":"君子國","def":"新羅7世紀統一朝鮮半島後全力模仿中國文字、曆法、儒學與佛教，因而得到的稱號。"},{"term":"東亞文化圈","def":"唐代漢字、儒學、中國化佛教、典章制度傳入日本、新羅等地，成為東亞共通要素而形成的文化圈。"},{"term":"怛羅斯之役","def":"8世紀唐朝與大食（阿拉伯帝國）在中亞爆發的戰役，促成中國造紙術西傳。"}],"timeline":[{"time":"西元前16世紀","event":"商人在黃河下游建國，分封各地既有勢力"},{"time":"西元前11世紀","event":"周人滅商建立周朝（西周），實施封建制度"},{"time":"西元前8世紀","event":"西周末年犬戎入侵，周平王東遷雒邑，開啟東周"},{"time":"西元前4世紀（前359／前356）","event":"秦國任用商鞅變法，厲行法治、編列戶籍"},{"time":"西元前221","event":"秦王嬴政統一六國，建立皇帝制度、推行郡縣制"},{"time":"西元前139","event":"漢武帝派張騫出使西域，開通絲路"},{"time":"西元前134","event":"漢武帝推舉孝廉，察舉制度開始"},{"time":"西元1世紀","event":"佛教經絲路傳入中國"},{"time":"220（3世紀）","event":"曹魏實施九品官人法"},{"time":"4世紀","event":"中國儒家思想與佛教東傳朝鮮半島"},{"time":"311","event":"永嘉之禍，胡人攻陷洛陽，晉室南渡建立東晉"},{"time":"493","event":"北魏孝文帝遷都洛陽，推動漢化"},{"time":"6世紀末（589）","event":"隋朝統一中國，605年始設科舉取士"},{"time":"7世紀","event":"玄奘赴天竺取經；伊斯蘭教由阿拉伯商人傳入中國"},{"time":"630","event":"唐太宗平東突厥，被尊為「天可汗」"},{"time":"641","event":"唐朝文成公主和親吐蕃，促進漢藏交流"},{"time":"646","event":"日本模仿唐制推動大化革新"},{"time":"7世紀中期","event":"新羅統一朝鮮半島，全力模仿中國文化"},{"time":"8世紀（751）","event":"唐與大食爆發怛羅斯之役，造紙術西傳"},{"time":"907","event":"唐朝滅亡，進入五代十國"}],"sources":[{"name":"周代分封銘文","gist":"天子命太保侍奉天子，大封土地，子孫世代享有燕國封地並管理部族。","clue":"天子、封地、子孫世代→西周封建制度"},{"name":"鄒衍「五德終始」說與五行相生相剋圖","gist":"以金木水火土的相生相剋說明朝代更替；秦以水德取代周的火德，崇尚黑色。","clue":"尚黑、水德→秦；漢武帝視秦為正統，依土剋水改為土德尚黃"},{"name":"秦始皇「天下苦戰不休，以有王侯」語","gist":"秦始皇認為天下長期戰亂源於分封王侯，若再立國等於「樹兵」，難求寧息。","clue":"王侯、樹兵、求其寧息→秦始皇廢封建、行郡縣"},{"name":"《史記．蒙恬列傳》","gist":"蒙恬為秦將，北方築長城防禦匈奴，司馬遷評其迎合君主、不恤民力。","clue":"秦、長城→匈奴；司馬遷的評價屬歷史解釋"},{"name":"敦煌壁畫「張騫往西域大夏國問名號時」","gist":"描繪張騫持笏跪拜騎馬的漢武帝辭行，把出使西域附會為引入佛教。","clue":"屬後人附會的歷史錯位；張騫出使實為聯合西域對抗匈奴"},{"name":"戶籍文書（建初十二年）","gist":"登記某家庭成員的姓名、性別、年齡與人數，並註明「登錄戶籍」。","clue":"人口、年齡、登錄戶籍→編戶齊民，目的在掌握人力、徵稅與勞役"},{"name":"《世說新語》《宋書》世族故事","gist":"寒門出身者求為世族或拜訪世族，均被「移我遠客」拒絕往來。","clue":"世族、寒門、門第、齊武帝→魏晉南北朝重門第"},{"name":"杜牧〈江南春〉","gist":"「南朝四百八十寺，多少樓臺煙雨中」描寫江南佛寺林立。","clue":"南朝、佛寺眾多→魏晉南北朝戰亂，佛教成為精神寄託而興盛"},{"name":"「傳絲公主」彩繪木版畫","gist":"約600～800年的木版畫，描繪東方公主嫁往和闐、在頭飾中夾帶蠶卵與桑種，使養蠶技術西傳。","clue":"蠶卵、桑種、和闐→絲路上的技術轉移（與怛羅斯之役造紙術西傳相近）"},{"name":"白居易〈寄胡餅與楊萬州〉","gist":"白居易仿長安做法烤胡麻餅寄給友人，比較口味是否像長安輔興坊名店。","clue":"胡麻餅、京都（長安）→唐代胡食流行；胡麻相傳漢代經絲路傳入"},{"name":"大秦景教流行中國碑","gist":"記載景教在長安設寺傳教的情形。","clue":"景教、摩尼教、伊斯蘭教傳入、長安→唐代"},{"name":"唐代接見使節壁畫","gist":"唐朝官員接待拜占庭帝國、新羅、東北少數民族使者。","clue":"新羅使者、拜占庭使者同時出現→唐代"}]},{"unit":7,"part":"中國與東亞史","title":"宋、元至盛清時期","summary":"學習遼宋金的和戰、蒙古帝國與元朝統治、宋元商貿與科技文化交流，以及明清政局、朝貢體制、海禁與白銀貿易、傳教士帶來的中西交流；會考多以史料判讀時代（歲幣、驛站、市舶司、冊封、白銀、禁教等關鍵字）。","sections":[{"heading":"遼宋金的和戰","points":["10世紀初契丹族建遼，取得長城以南的燕雲十六州，成為東亞強權","遼國稱霸時，東北的女真、西北的西夏都向遼稱臣納貢","遼取得燕雲十六州後，長城失去防禦功能，北宋北方門戶洞開","宋太祖趙匡胤建宋、定都汴京（開封），重文輕武而軍力貧弱","11世紀初遼南侵，宋真宗親征後簽訂澶淵之盟：宋遼約為兄弟之邦，宋每年給遼銀絹歲幣","澶淵之盟是中國首度與周邊國家建立對等（平等）外交關係，宋遼維持一百多年和平","12世紀初女真族建金，金國仿效漢人制度；金先與北宋聯合滅遼，後與南宋南北對峙，最後亡於蒙古","北宋與金結盟（海上之盟）聯金滅遼：約定滅遼後交還燕京等地，宋將原給遼的歲幣轉給金","金滅遼後隨即南下攻陷汴京、俘虜皇帝，史稱靖康之禍，北宋滅亡","宋室南渡定都臨安（杭州）建立南宋，宋金長期南北對峙；13世紀蒙古聯合南宋滅金","南宋與金議和：東以淮水、西以秦嶺為界，南宋向金稱臣，每年繳納貢銀、絹各25萬（宋也給金歲幣）","外族攻陷首都亡國的兩個例子：西晉（永嘉之禍）、北宋（靖康之禍）"],"example":"外交政策口訣：北宋「聯金滅遼」、南宋「聯蒙滅金」，結果都是引狼入室。"},{"heading":"蒙古帝國與元朝統治","points":["13世紀初鐵木真統一蒙古各部，被尊為「成吉思汗」（意為偉大的君主）","成吉思汗與繼位者發動三次西征，分封四大汗國，建立橫跨歐、亞兩洲的大帝國；西征期間滅西夏，並與南宋聯手滅金","蒙古西征使絲路沿線納入統治，廣設驛站，促進歐亞商旅往來、文化交流與民族融合","13世紀中期忽必烈（元世祖）建立元朝、定都大都（今北京），南下消滅南宋統一中國，被視為中國的王朝之一","元朝南下滅宋完成統一，蒙古成為首個統治整個中國的草原民族；蒙古帝國後來分裂為元與四大汗國","元朝實施差別待遇的族群政策：蒙古人、色目人（西域各族，常管財政）、漢人、南人；蒙古人、色目人在政治、法律、科舉享特權","元代「漢人」指原受金統治的漢人、契丹人、女真人；「南人」指原南宋統治的漢人及南方各族，地位最低","元代科舉也有差別待遇：蒙古、色目人放右榜，考試場數與作答字數較少；漢人、南人放左榜，考試較難","元世祖後帝位繼承糾紛不斷，元末又連年災荒、財政混亂、民變四起，加速元朝瓦解","14世紀中葉朱元璋驅逐蒙古統治者退回北方，元朝遭明驅逐後退居長城以北"],"example":"四大汗國：欽察、窩闊臺、察合臺、伊兒汗國（在今伊朗一帶）；義大利人馬可波羅曾到元朝見忽必烈。","fig":{"src":"../assets/fig/history/u7-s2.svg","cap":"蒙古帝國的三次西征與四大汗國"}},{"heading":"宋元的經濟與城市發展","points":["宋代自占城引進早熟稻，稻米產量提升，使稻米成為最重要的糧食作物","早熟稻使糧食增加，促進人口成長，帶動經濟活動更活躍","宋元海陸貿易熱絡：宋在邊境設市場與遼金貿易；元代蒙古將絲路納入勢力範圍","宋代以海路貿易為主：造船、航海技術進步使商人出海","唐中期以後阿拉伯（穆斯林）商人主導印度洋、南海至中國東南沿海的貿易，宋元時延伸至東亞","市舶司設於廣州、泉州等港口，管理商船、收取關稅，類似今日海關；市舶司徵收的關稅成為政府重要收入","僑居中國經商的穆斯林稱「蕃客」，多聚居於官府在對外口岸畫定的「蕃坊」，蕃坊受市舶司管理","泉州是宋元時期世界最重要的港口之一","貿易繁盛使貨幣需求增加，開始廣泛使用紙鈔，例如元代寶鈔通行全國","唐代以前的坊市制度把坊（住宅區）與市（商業區）分開；宋代起坊市合一，政府解除營業地點與時間限制","宋代打破限制後夜市興旺、住商混合；汴京、臨安、大都成為國際都市","北宋張擇端〈清明上河圖〉反映汴京繁榮"],"example":"看到「市舶司＋色目人官員＋穆斯林商人」→元代泉州；看到「夜市、住商混合」→宋代。"},{"heading":"宋元的學術科技與文化交流","points":["宋代重視文人政治，學者將佛教等思想與儒家融合形成理學；南宋朱熹集大成","朱熹《四書集注》（四書指《論語》《孟子》《大學》《中庸》）為元代以後科舉定本，並傳入朝鮮、日本","三大科技成就：火藥、活字印刷術、指南針；火藥用於軍事並經蒙古西征傳入歐洲，改變戰爭型態","火藥西傳後，15世紀歐洲為抵擋火炮發展出又矮又厚的星形城牆堡壘","北宋畢昇發明膠泥活字（活字印刷術），改善以往刻版不能重新排版的缺點，提高印刷效率","指南針用於航海並經阿拉伯人傳到歐洲，指南針西傳有助日後新航路發現","宋代《萍洲可談》記載舟師夜觀星象、晝看太陽，陰天依靠指南針判斷船隻位置","指南針後發展為羅盤，並據以繪製針路圖","伊斯蘭教在唐代傳入；宋元海陸交通暢通、蒙古帝國橫跨歐亞，吸引穆斯林來華經商、定居、任官","穆斯林商人建清真寺傳播伊斯蘭教，如泉州清淨寺","穆斯林將西域曆法、天文學、醫學、數學等知識傳入中國","元朝在首都與全國26個地點建天文觀測臺，為編製全國通用曆法提供數據"],"example":"中西交流方向：西→中是曆法、天文、醫學、數學；中→西是火藥（蒙古人）、指南針（阿拉伯人）。"},{"heading":"明清政局變遷","points":["元末朱元璋發布〈諭中原檄〉，以恢復華夏、驅逐蒙古為號召，但願撫養知禮義的非華夏族類","明太祖朱元璋驅逐蒙古人結束元朝，建立明帝國，定都南京；但蒙古退居長城以北仍威脅明朝","明成祖遷都北京並修築長城以防範蒙古；成祖北伐蒙古，國勢達到鼎盛","首都變遷：北宋汴京（開封）、南宋臨安（杭州）、元大都（北京）、明應天（南京）→北京、清北京","明朝外患：北方蒙古、東南沿海倭寇（明初因此實施海禁）、明末東北女真崛起建「大清」並改族名為滿洲；內憂為流寇（李自成）","明中期以後內政腐敗，北方蒙古與東南倭寇進犯，國勢漸衰","明將戚繼光因應東南沿海地形，以狼筅等長短兵器配合創制鴛鴦陣，多次擊退倭寇","明末內憂為流寇：天災饑荒，災民與飢兵形成流寇，李自成攻陷北京，明朝滅亡（1644）","明亡後吳三桂引清軍入關，清兵定都北京，平定流寇、消滅南明，康熙年間征服臺灣","康熙、雍正、乾隆年間將蒙古、西藏、新疆納入統治，並以婚姻拉攏蒙古","清對漢人高壓（薙髮留辮、文字獄）與懷柔（科舉、禮遇明遺臣）並行","清初推行易服、薙髮、圈地、投充、逃人五項政令；薙髮是女真舊俗，金代統治黃河以北時就曾強迫漢人薙髮","清代文字獄例：徐述夔因「清風不識字，何得亂翻書」等詩句遭戮屍"],"example":"元與清都是少數民族統治中國、定都今日北京，但元對漢人差別待遇，清則高壓懷柔並行。"},{"heading":"天朝體制與東亞國際秩序","points":["明清以「天朝」自居，外國君主須接受中國冊封以示臣服，成為藩屬，才能與中國往來","朝貢體系：宗主國對藩屬國冊封、賞賜；藩屬國對宗主國朝覲、進貢，形成以中國為中心的世界觀","藩屬國遣使朝貢可獲賞賜，並能藉朝貢之名在官方監督下貿易；琉球、朝鮮等周邊國家因朝貢利潤豐厚而紛紛前往","朝鮮國王也使用中國年號；朝鮮使節明代稱「朝天使」","清代朝鮮文化上視清為夷狄，將使節改稱「燕行使」，但政治上仍承認清朝","元代周達觀隨使團出使真臘（吳哥），將見聞寫成《真臘風土記》","15世紀初（1405～1433）明成祖派鄭和下西洋，到東南亞、印度洋，最遠達非洲東岸，使南洋各國來朝，朝貢體制達到顛峰","鄭和聘用中國東南沿海的水手與熟悉海路的穆斯林，利用阿拉伯人的海上航線出航","15世紀發展出「過洋牽星術」，以牽星板測星體仰角推算緯度","明代《武備志》收錄的航海圖被認為與鄭和寶船船隊有關","鄭和下西洋奠定閩、粵居民移往東南亞發展的基礎","藩屬國也可獲中國保護：16世紀末豐臣秀吉侵略朝鮮，明朝視朝鮮為屏障，出兵助朝鮮擊退日本","明朝並想冊封日本、將其納入朝貢體系，和議未成","19世紀中西方列強入侵後，天朝體制逐漸崩潰"],"example":"「使節團前往中國」「接受冊封」「進貢物產、獲賜宴賞」→明清朝貢體制。","fig":{"src":"../assets/fig/history/u7-s6.svg","cap":"鄭和下西洋的航線（1405～1433）"}},{"heading":"明清的商貿活動","points":["明清國內貿易發達，出現各具特色的專業市鎮","明清手工業分工細密，專業市鎮興起，如江西景德鎮以瓷器聞名","明初為防倭寇實施海禁，只允許官方朝貢貿易","海禁期間東南沿海居民仍違禁私自出海，形成亦商亦盜的海商集團","具武裝力量的海商（如顏思齊、鄭芝龍）進行走私貿易","16世紀中葉明朝平定倭寇後局部解除海禁，明代後期海禁趨緩，沿海貿易再度興起，海商活動遍及日本與東南亞","加上歐洲人在東南亞建據點，海上貿易熱絡，鄭芝龍曾壟斷東南沿海貿易","15世紀末新航路開通，葡萄牙占澳門、西班牙占馬尼拉，以美洲與日本白銀購買中國絲綢、瓷器、茶","西班牙人開採美洲白銀，荷、葡、英等國商人運至亞洲購買中國絲綢、瓷器，加速全球經濟網絡形成","布勞岱爾稱1450～1640年為「漫長的16世紀」：歐洲以美洲白銀轉輸亞洲，逐漸取代中國控制世界經濟","明初寶鈔不能兌現、不能付稅，發行過量造成通貨膨脹而貶值，之後改以白銀為主要貨幣","白銀大量流入中國成為重要交易媒介；美洲白銀大量輸入後取代紙幣，明清形成白銀與銅錢並用的貨幣制度","玉米、番薯、馬鈴薯等耐旱高產的美洲作物傳入，緩解中國人口快速成長造成的糧食不足","明末徐光啟《農政全書》記載番薯自海外傳入閩廣，耐旱易生，閩廣人賴以救饑","清初為封鎖臺灣鄭氏實施海禁，康熙平臺後解除","清乾隆時限定廣州一口通商以集中管理外商，引發中英貿易衝突，直到晚清《南京條約》才結束閉關自守"],"example":"1550～1645年白銀從日本、美洲流入中國；歐洲王公貴族搶購的中國商品是瓷器。"},{"heading":"明清的中西文化交流","points":["宗教改革後天主教積極向外傳教，耶穌會士利瑪竇16世紀末來華","利瑪竇為求順利傳教，尊重中國人祭祖祀孔、允許教徒祭祖（利瑪竇規矩），並以西學吸引士人","利瑪竇以西學獲得士大夫認同，奠定天主教在華發展基礎","利瑪竇與徐光啟合譯《幾何原本》；西方數學、地理、天文、火炮傳入，湯若望在清初掌欽天監修曆","西方地理學帶來有完整經緯度的地圖，如利瑪竇繪製《坤輿萬國全圖》、康熙時的《皇輿全覽圖》","明末傳教士傳入歐洲火炮技術，北京城配置數百門歐洲大炮","中國典籍、瓷器、園林建築傳入歐洲，掀起18世紀歐洲的「中國熱」","清初教廷禁止中國教徒祭祖祀孔引發禮儀之爭；禮儀之爭後康熙曾下令禁教但未嚴格實施","雍正因傳教士捲入宮廷政爭，下令全面禁教、驅逐傳教士（1723），中西文化交流中斷","天主教在明代傳入日本，與當地文化衝突引起社會不安，日本因而實施鎖國，限制傳教士與西方商人活動","日本17世紀前期起鎖國（1633～1854；翰林作1639），僅許中國、荷蘭商人在長崎貿易","日本人經荷蘭人吸收的西方知識稱「蘭學」"],"example":"天婦羅由葡萄牙天主教徒傳入日本；鎖國時期荷蘭人只能住在長崎的出島。"}],"confusions":[{"a":"澶淵之盟（宋遼）","b":"宋金議和（南宋與金）","diff":"澶淵之盟在11世紀初北宋與契丹遼國訂立，約為兄弟之邦的平等關係；宋金議和在靖康之禍後，南宋與女真金國南北對峙。","tip":"契丹＋兄弟之邦→澶淵之盟；女真＋汴京淪陷＋臨安→南宋"},{"a":"靖康之禍","b":"永嘉之禍","diff":"靖康之禍是北宋末女真攻陷汴京、北宋滅亡；永嘉之禍是西晉末胡人攻陷洛陽、晉室南渡。","tip":"女真→靖康（宋）；胡人五胡→永嘉（晉）"},{"a":"金（女真）","b":"大清（滿洲）","diff":"金是北宋末女真族建立，與南宋南北對峙，後被蒙古所滅；大清是明末女真改族名滿洲後建立，統一中國，清末為中華民國取代。","tip":"女真＋北宋末＋南北對峙→金；滿洲＋明末＋入關統一→清"},{"a":"元代族群政策","b":"清代統治政策","diff":"元代依族群分四等差別待遇，任用色目人管財政；清代對漢人高壓（薙髮、文字獄）與懷柔（科舉、禮遇遺臣）並行，以婚姻拉攏蒙古。","tip":"色目人、南人→元；薙髮留辮、文字獄→清"},{"a":"市舶司","b":"驛站","diff":"市舶司是設在港口管理商船、收關稅的官方機構（始於唐，宋元盛行）；驛站是蒙古帝國提供官員、使節、商旅換馬休息的陸路設施。","tip":"港口、關稅→市舶司；換馬、牌符、陸路→驛站"},{"a":"早熟稻（北宋）","b":"美洲作物（明清）","diff":"北宋自占城（今越南）引進早熟稻，使稻米成為最重要糧食作物；明代起番薯、馬鈴薯、玉米自美洲傳入，緩和人口增加的糧食不足。","tip":"占城、稻米→宋；番薯、玉米、馬鈴薯、新航路→明清"},{"a":"元代寶鈔","b":"明代寶鈔","diff":"元代寶鈔通行全國，因應商貿繁盛下的貨幣需求；明初寶鈔不能兌現、不能付稅，發行過量而貶值，後被白銀取代。","tip":"通行全國、伊兒汗國仿效→元；發行過量、白銀取代→明"},{"a":"宋元中西交流","b":"明清中西交流","diff":"宋元主要透過穆斯林與蒙古西征交流（伊斯蘭曆法、醫學入華，火藥、指南針西傳）；明清則是耶穌會士傳入西學、帶回中國典籍瓷器。","tip":"穆斯林、色目人→宋元；利瑪竇、耶穌會、禮儀之爭→明清"},{"a":"明初海禁","b":"清初海禁","diff":"明初海禁為防範倭寇，只准官方朝貢貿易；清初海禁為封鎖臺灣鄭氏政權，康熙平臺後解除。","tip":"倭寇→明；鄭成功、鄭氏→清"}],"terms":[{"term":"燕雲十六州","def":"位於長城以南的土地，遼國取得後獲得漢人農業生產支援，並可隨意南下，北宋一直想收復。"},{"term":"西夏","def":"宋代位於中國西北的政權，曾向遼稱臣納貢，後於蒙古西征期間被蒙古所滅。"},{"term":"澶淵之盟","def":"11世紀初宋真宗親征後與遼訂立和約，約為兄弟之邦，宋每年給遼銀、絹歲幣，建立平等外交關係。"},{"term":"歲幣","def":"宋朝每年給予遼、金的銀、絹等財物，用以換取和平。"},{"term":"靖康之禍","def":"金國滅遼後南下攻陷汴京，俘虜北宋皇帝，北宋滅亡，宋室南渡建立南宋。"},{"term":"成吉思汗","def":"13世紀初統一蒙古各部的鐵木真所獲尊號，發動第一次西征。"},{"term":"四大汗國","def":"蒙古西征後分封諸王建立的欽察、窩闊臺、察合臺、伊兒汗國，最初受大汗統轄後漸獨立。"},{"term":"驛站","def":"蒙古帝國設置，提供官員、信使、旅人休息換馬的處所，促進歐亞商旅往來。"},{"term":"色目人","def":"元代對西域各族的稱呼，地位僅次於蒙古人，常受任命管理財政與經濟事務。"},{"term":"市舶司","def":"設在廣州、泉州等港口的官方機構，負責管理商船、檢查貨物與收取關稅，類似今日海關。"},{"term":"蕃坊","def":"宋元時期官府在對外港口畫定、供外國（穆斯林）商人聚居的區域，受市舶司管理。"},{"term":"交子","def":"宋代因銅錢外流、貨幣不足，四川商人聯合發行的紙幣，被視為中國紙幣的起源。"},{"term":"寶鈔","def":"元代發行並通行全國的紙幣，因應商貿繁盛下的貨幣需求，伊兒汗國曾仿效失敗；明初寶鈔則因發行過量貶值。"},{"term":"坊市合一","def":"宋代起政府解除商業活動的地點與時間限制，住宅區與商業區混合並出現夜市。"},{"term":"理學","def":"宋代學者融合佛教等思想與儒學形成的學說，南宋朱熹集大成，又稱新儒學。"},{"term":"回回","def":"元代對來華穆斯林的統稱，他們帶來天文曆法、醫藥等知識並傳播伊斯蘭教。"},{"term":"倭寇","def":"原指劫掠中國沿海的日本海盜，16世紀以後多為漢人，長期劫掠東南沿海或走私貿易。"},{"term":"戚繼光","def":"明代抗倭名將，因應東南沿海地形創制鴛鴦陣，多次擊退倭寇。"},{"term":"流寇","def":"明末饑荒造成災民與飢兵結合形成的武裝集團，以李自成勢力最大，攻陷北京使明朝滅亡。"},{"term":"薙髮留辮","def":"清初強迫漢人男子剃去前額頭髮、留辮子，依滿洲髮式以示臣服，屬高壓統治手段。"},{"term":"文字獄","def":"清朝從文字作品中多次羅織罪名、構成冤獄，用以打壓漢人士人的反清思想。"},{"term":"康雍乾盛世","def":"清朝康熙、雍正、乾隆三朝，將蒙古、臺灣、西藏、新疆相繼納入版圖的鼎盛時期。"},{"term":"朝貢體制","def":"明清以天朝自居，外國君主接受冊封成為藩屬、遣使朝貢，才能與中國往來貿易並獲保護。"},{"term":"朝貢貿易","def":"外國接受中國冊封成為藩屬後，藉進貢名義在官方監督下與中國通商的貿易方式。"},{"term":"燕行使","def":"清代朝鮮派往北京的使節；朝鮮文化上不認同清朝，將明代的「朝天使」改稱燕行使。"},{"term":"鄭和下西洋","def":"15世紀初明成祖派鄭和率艦隊出使東南亞、印度洋，最遠達非洲東岸，使朝貢體制達到顛峰。"},{"term":"過洋牽星術","def":"15世紀的航海觀星技術，用牽星板測量星體在水平線上的仰角以推算緯度，以「指」為單位記錄。"},{"term":"海禁","def":"禁止人民私自出海的政策；明初為防倭寇、清初為封鎖臺灣鄭氏而實施。"},{"term":"專業市鎮","def":"明清手工業分工細密後興起、以特定產品聞名的市鎮，例如以瓷器聞名的江西景德鎮。"},{"term":"利瑪竇規矩","def":"耶穌會士利瑪竇允許中國教徒祭祖祀孔的傳教方式，並以西學吸引士人，為後繼傳教士遵循。"},{"term":"禮儀之爭","def":"清初羅馬教廷反對中國教徒祭祖祀孔引起的爭議，最後雍正下令全面禁教。"},{"term":"鎖國政策","def":"日本17世紀前期起禁止人民出海，只准中國、荷蘭商人在長崎貿易（1633～1854；翰林作1639）。"},{"term":"蘭學","def":"日本鎖國時期經由長崎荷蘭商人吸收的歐洲科學、醫學與技術，奠定日本近代科學基礎。"}],"timeline":[{"time":"916","event":"契丹建國（遼）"},{"time":"960","event":"宋太祖趙匡胤建立宋朝，定都汴京"},{"time":"1004","event":"宋遼簽訂澶淵之盟，約為兄弟之邦（翰林作1005）"},{"time":"12世紀初","event":"女真族建立金國，與北宋聯合滅遼"},{"time":"1127","event":"靖康之禍，北宋滅亡；宋室南渡建立南宋，定都臨安"},{"time":"1206","event":"鐵木真統一蒙古各部，被尊為成吉思汗"},{"time":"1218","event":"蒙古首次西征（翰林作1219）"},{"time":"1227","event":"蒙古滅西夏"},{"time":"1234","event":"蒙古聯合南宋滅金"},{"time":"1271","event":"忽必烈建立元朝，定都大都"},{"time":"1279","event":"元滅南宋，統一中國"},{"time":"1368","event":"朱元璋驅逐蒙古人，建立明朝，定都南京"},{"time":"1405～1433","event":"鄭和七次下西洋，最遠抵達非洲東岸"},{"time":"16世紀中葉","event":"明朝平定倭寇、局部解除海禁；葡萄牙人租借澳門，西班牙人以馬尼拉為據點"},{"time":"1582","event":"耶穌會士利瑪竇抵達澳門，隨後進入中國傳教"},{"time":"1592～1598","event":"豐臣秀吉侵略朝鮮，明朝出兵援助"},{"time":"1633","event":"日本開始鎖國，只許中國、荷蘭商人在長崎貿易（翰林作1639）"},{"time":"1644","event":"李自成攻陷北京，明朝滅亡；清兵入關占領北京"},{"time":"康熙～乾隆年間","event":"蒙古、西藏、新疆陸續納入清朝版圖，國勢達到極盛"},{"time":"1683","event":"康熙年間清朝征服臺灣，之後解除海禁"},{"time":"1723","event":"雍正皇帝下令全面禁教，驅逐傳教士"}],"sources":[{"name":"澶淵之盟相關史料","gist":"宋遼約為兄弟之邦，宋每年給遼銀、絹，雙方數十年不知戰爭。","clue":"契丹、兄弟之邦、歲幣、燕雲十六州、宋真宗親征→北宋與遼"},{"name":"泉州清淨寺","gist":"宋元時期穆斯林商人在泉州興建的清真寺，見證伊斯蘭教隨海上貿易傳入。","clue":"泉州、清真寺、穆斯林商人→宋元海上貿易與伊斯蘭文化傳入"},{"name":"《萍洲可談》","gist":"宋代筆記，記載舟師夜觀星象、晝看太陽，陰天依靠指南針判斷船隻位置。","clue":"舟師、陰天看指南針→宋代指南針用於航海"},{"name":"宋金議和（紹興和議）條款","gist":"南宋與金以淮水、秦嶺為界，宋向金稱臣，每年繳納銀、絹各25萬。","clue":"淮水、秦嶺、稱臣、失去首都→南宋與金；對照澶淵之盟是兄弟之邦"},{"name":"《馬可波羅遊記》與汗八里","gist":"義大利人馬可波羅描述元朝大都（汗八里）的繁榮與完善的驛站制度。","clue":"大汗、汗國使者、驛站換馬、汗八里→元代大都"},{"name":"元代由中國出使西方的遊記（波斯文原稿、敘利亞文版）","gist":"13世紀末，有人由大都出發前往耶路撒冷朝聖，後成為伊兒汗國聯合基督教世界對抗穆斯林的使者，行經巴格達、君士坦丁堡、羅馬、巴黎。","clue":"13世紀末、大都出發、伊兒汗國、陸路西行→元代驛站與歐亞交流"},{"name":"《真臘風土記》","gist":"元代周達觀隨使團到吳哥（真臘），記錄柬埔寨的風土民情。","clue":"南人周達觀、真臘、使團說服歸順→元代"},{"name":"〈諭中原檄〉","gist":"元末朱元璋北伐時發布，指元以北狄入主中國，號召驅逐蒙古、恢復中國統治。","clue":"宋祚傾移、元以北狄入主中國、夷狄居外→元末朱元璋起兵建明"},{"name":"「通番事蹟記」碑","gist":"記載明朝使節七次出使，經占城、暹羅、古里，最遠達東非。","clue":"成祖、中官鄭和、造大船、遠達非洲東岸→鄭和下西洋"},{"name":"《武備志》航海圖（過洋牽星圖）","gist":"17世紀出版的《武備志》收錄航海圖與過洋牽星圖，與明代國家寶船船隊西航有關。","clue":"寶船、牽星、忽魯謨斯、古里、橫渡印度洋→鄭和下西洋"},{"name":"明代士大夫贈利瑪竇詩","gist":"讚美來自八萬里外的西方人遠渡重洋、仰慕中華、深契儒理。","clue":"西方人、八萬里、深契吾儒理→利瑪竇融入儒家文化傳教"},{"name":"《農政全書》","gist":"明末徐光啟編纂的農書，記載番薯由海外傳入閩廣、耐旱高產可救饑荒。","clue":"番薯、海外得此種、閩廣救饑→明代美洲作物傳入"},{"name":"清初易服、薙髮等五項政令","gist":"清初入主中原後推行易服、薙髮、圈地、投充、逃人五項政令，引起民間強烈反彈。","clue":"異族入主中原、薙髮易服、圈地→清初高壓統治；女真曾在金代強迫漢人薙髮"},{"name":"廣州「回教三忠」墓碑","gist":"紀念三位回族將領為南明堅守廣州、城破殉難。","clue":"南明、外族軍隊圍廣州→清初以武力消滅南明"},{"name":"清初海禁令","gist":"因鄭成功勢力未滅，下令沿海文武官員嚴禁商民船隻私自出海。","clue":"鄭成功、嚴禁出海→清初海禁（對照明初海禁是防倭寇）"},{"name":"《皇輿全覽圖》","gist":"康熙時由傳教士參與、以西方經緯度測量法繪製的中國全圖。","clue":"康熙、傳教士、經緯度測繪→清初西學（地理學）的應用"},{"name":"雍正禁教諭令","gist":"以西洋人在地方生事惑眾為由，令傳教士往住澳門。","clue":"聖祖（康熙）、西洋人、住澳門→雍正禁教，中西文化交流趨於沉寂"},{"name":"朝鮮「測雨臺」雨量計","gist":"刻有「乾隆庚寅五月造」，實為朝鮮發明，因國王受中國冊封而使用清朝年號。","clue":"外國使用中國年號、接受冊封、遣使朝貢→明清天朝體制"}]},{"unit":8,"part":"中國與東亞史","title":"晚清時期","summary":"學習晚清從一口通商、鴉片戰爭到辛亥革命前，中國與日本面對西力衝擊的回應（自強運動、明治維新）、甲午戰後的制度改革（戊戌變法、庚子後新政、立憲運動）及通商口岸帶來的社會文化變遷；會考常以史料關鍵字判斷事件、排列改革與戰爭的因果順序。","sections":[{"heading":"鴉片戰爭與不平等條約","points":["1757年起乾隆限制外商只能在廣州貿易（一口通商），且須透過公行交易，不得直接與官府交涉","一口通商時期各國商館匯集廣州城牆與河岸間，以國旗為標記；歐洲茶葉需求遽增是貿易熱絡主因","英國向中國大量購買茶、絲、瓷器，貿易逆差嚴重","英國兩度遣使（馬加爾尼、阿美士德）交涉放寬通商限制，因天朝觀念與跪拜禮節爭議無功而返，衝突越發激烈","18世紀末荷蘭使節遵行叩首禮順利完成祝壽任務；英國使節則因拒行叩首禮而通商交涉失敗，日後以武力反制中國","英國自印度走私鴉片入中國，造成白銀大量外流","鴉片輸入使白銀外流、銀價上漲（銀貴錢賤）：一兩白銀可換銅錢由1800年約1070文升至1849年約2355文","道光帝派林則徐到廣州查禁鴉片：強制沒收並銷毀英商鴉片，英商利益受損","英國決定出兵，藉此打開中國門戶，1840年爆發鴉片戰爭","1842年《南京條約》：賠款、割讓香港、開放上海、寧波、福州、廈門、廣州五口通商，結束一口通商","1843年續約中國喪失多項主權：租界（國中之國）破壞領土主權；協定關稅破壞關稅自主權","領事裁判權破壞司法自主權；片面最惠國待遇使外國單方面享優惠","鴉片戰爭影響：中國閉關自守政策遭打破，開始受不平等條約束縛，天朝體制受到衝擊，歐美各國紛紛要求訂約"],"example":"題目出現「租界」「領事裁判權」「五口通商」→時間一定在1842年鴉片戰爭之後；只有廣州能貿易→1757~1842年","fig":{"src":"../assets/fig/history/u8-s1.svg","cap":"鴉片戰爭與南京條約的五口通商"}},{"heading":"英法聯軍與自強運動","points":["英法聯軍起因是英國希望修約、要求與中國全面通商遭拒，聯合法國出兵（1857~1860年）","1858年簽《天津條約》等：公使駐京、增開通商口岸、外人可到內地遊歷傳教","英法聯軍後增開長江沿岸、北方及臺灣（雞籠、淡水、安平、打狗）口岸，列強勢力由沿海深入內地","自強運動因英法聯軍期間見識西方船堅炮利而起，1861~1894年推動，推手為恭親王奕訢及曾國藩、李鴻章等地方官員","目標「師夷長技以制夷」；設總理各國事務衙門統籌外交，日後成為推行自強運動的機構","清廷外交機構演變：禮部四驛館接待藩屬朝貢→《天津條約》各國公使駐北京→1861年設總理衙門","→《辛丑和約》將總理衙門改為外務部，居六部之首","自強運動內容：辦兵工廠、船廠、北洋艦隊，興鐵路、電報，派留學生、設同文館","自強運動期間中國開始自辦鐵路（唐胥鐵路、龍號機車），負責運輸任務","期間沈葆楨、劉銘傳在臺修砲臺、建鐵路、架電報、設郵局與新式學堂","李鴻章與曾國藩、左宗棠、張之洞並稱晚清「中興四大名臣」","李鴻章一生簽下30多個條約，多為不平等條約，評價正反皆有","缺失：偏重器物層面、缺乏整體規畫，又遭守舊派阻撓","保守讀書人認為只讓工具西化而不讓價值觀西化是不徹底的錯誤，因而全面反對西化，成為自強運動阻力","自強運動結果甲午戰爭戰敗，證明成效有限；但傳播新觀念、培養人才，奠定中國現代化基礎","對照：明治維新則使日本在甲午戰爭、日俄戰爭皆戰勝","清末戰爭與改革的因果：英法聯軍刺激自強運動；甲午戰爭刺激戊戌變法與革命；八國聯軍刺激庚子後新政"],"example":"北洋艦隊、江南製造局、福州船政學堂、同文館、廣方言館→自強運動（器物層面，1861年起）","fig":{"src":"../assets/fig/history/u8-s2.svg","cap":"英法聯軍與天津條約、北京條約"}},{"heading":"日本明治維新與東亞變局","points":["17世紀起日本鎖國，只准中國、荷蘭船到長崎貿易","中日通商限制比較：中國因傳教爭議（雍正禁教）與管理外商，乾隆限廣州通商","日本因天主教衝擊，17世紀前期江戶幕府鎖國，僅長崎限中、荷","1853年美國海軍將領培里率艦叩關、美軍登陸日本（黑船事件）","隔年（1854年）日本被迫開港通商、結束（解除）鎖國，有志之士鼓吹維新運動","1868年起明治天皇推動明治維新，全面效法西方，器物與文化全面現代化","明治維新內容：遷都東京、採行君主立憲、推行義務教育、派使節團訪歐","建立現代化陸海軍、發展工業","日本西南部造船廠、煤礦、鐵工廠等23處遺址列世界遺產，見證1850～1900年代日本由封建社會快速轉型為工業國家","明治維新後日本成為亞洲第一個現代化國家，國力大增後向外擴張","日本擴張順序：1874年牡丹社事件出兵侵犯臺灣→1879年併吞琉球→介入朝鮮內政","→1894～1895年甲午戰爭擊敗中國、1895年取得（殖民）臺灣→1904~1905年日俄戰爭勝俄→1910年併吞朝鮮","甲午戰爭日本擊敗中國，象徵明治維新有成，20世紀初許多中國人選擇赴日留學","朝鮮興宣大院君（1864年起掌權）強硬鎮壓天主教、閉關自守、立斥和碑，擊退法軍與美軍","1876年朝鮮與日本簽訂《朝日修好條約》（江華島條約），日本取得領事裁判權等，是朝鮮首個不平等條約","日俄戰爭後《樸茨茅斯條約》：俄國失去遠東制海權、沙皇專制動搖；日本逐步躍居世界強權","日俄戰爭期間日本漫畫將俄國畫成章魚，諷刺其觸手伸向土耳其、波斯、西藏、清帝國、朝鮮等地","東南亞多淪為殖民地：清法戰爭（1884年）因越南問題而起，結果臺灣建省、越南成為法國殖民地","英國以印度為據點向馬來半島、緬甸擴張"],"example":"自強運動＝器物、地方官推動；明治維新＝全面西化、天皇由中央推動 → 甲午戰爭日本勝","fig":{"src":"../assets/fig/history/u8-s3.svg","cap":"明治維新後日本的對外擴張"}},{"heading":"甲午戰爭、瓜分危機與戊戌變法","points":["1894年朝鮮內亂，中日皆出兵，亂平後日本不撤兵，爆發甲午戰爭","自強運動時期建立的北洋艦隊，在甲午戰爭黃海海戰遭重創","1895年初日軍水陸夾攻威海衛，主帥丁汝昌自盡，經營10餘年的北洋艦隊全軍覆沒，清帝國戰敗","1895年《馬關條約》（李鴻章、伊藤博文）：賠款、承認朝鮮獨立自主、割讓臺灣澎湖、允許日人在通商口岸設廠","《馬關條約》原割讓遼東半島，後因俄國等國介入（三國干涉還遼），由中國出錢買回","列強援引片面最惠國待遇比照在通商口岸設廠；1894年後外國在華設廠由16家增至136家","戰後列強掀起瓜分風潮，強行租借港灣、劃分勢力範圍；美國提出門戶開放、利益均霑","各國勢力範圍：俄國長城以北東北（租旅順、大連）、德國山東（膠州灣）、英國長江流域（威海衛、新界）","日本以福建、法國以西南（廣州灣）為勢力範圍","租借港灣期滿可收回，如英國租借香港新界（1898～1997年），香港於1997年回歸","一戰時日本強占德國在山東的勢力範圍，並提出二十一條要求，日後引發五四運動","甲午戰後知識分子出現改革（康梁變法）與革命（孫中山）兩種救亡途徑","甲午戰後部分知識分子對體制內改革失望，轉而提出體制外的革命訴求","1898年光緒皇帝任用康有為、梁啟超推動戊戌變法，偏重制度改革：裁撤冗員、精簡政府機構、設京師大學堂","戊戌變法時，主張器物改革已遇困境的自強派，曾短暫支持康梁提出的體制改革","戊戌變法缺失：內容龐雜、動搖守舊派利益","慈禧太后與守舊派發動戊戌政變，光緒被軟禁、康梁逃往海外，變法僅103天，稱「百日維新」","京師大學堂為北京大學前身，主張「中學為體，西學為用」，是戊戌變法唯一留存（保留）的新政"],"example":"「朝鮮問題」「馬關」「設廠製造」→甲午戰爭；「京師大學堂」「康、梁」→戊戌變法","fig":{"src":"../assets/fig/history/u8-s4.svg","cap":"甲午戰爭形勢圖（1894～1895）"}},{"heading":"八國聯軍、庚子後新政與立憲運動","points":["英法聯軍後傳教士深入內地、教案頻傳；傳教士偏袒教民，民眾鴉片戰爭後又飽受欺凌，仇洋反教","教民仗教會撐腰橫行地方（「未入教，尚如鼠；既入教，便如虎」），清廷又要百姓向教會賠款，加深民教衝突","義和團出自山東的民間宗教團體，以「扶清滅洋」為號召，在北京燒教堂、殺傳教士與使節，其行為由慈禧太后默許","1900年英、法、德、俄、美、日、奧、義組八國聯軍攻陷北京，慈禧挾光緒逃往西安；俄國趁機占領東北","1901年《辛丑和約》：鉅額賠款（清末賠款最多）、拆砲臺、各國駐軍使館區，國防財政重創","八國聯軍後慈禧為挽回人心，1901年起推動庚子後新政：編練新軍、推動新式教育","庚子後新政於1905年廢除始於隋代的科舉制度","1904~1905年日俄戰爭是日俄爭奪中國東北利益；日本戰勝被視為「立憲勝專制」，朝野認為「立憲優於專制」","立憲派主張以憲法約束君主、國會監督內閣，達成君民共治","清廷派大臣出國考察，1906年在輿論壓力下宣布預備立憲；1908年公布《憲法大綱》","1909年各省成立諮議局，舉辦議員選舉，是中國首次民意代表選舉","1911年成立責任內閣卻多為皇親貴族，被譏為「皇族內閣」，立憲派失望而轉向支持革命","清廷面對西力的回應：無意改革（1842～1860）→自強運動（1861～1894）→戊戌變法（1898）","→庚子後新政（1901～1911）→立憲運動（1906～1911）"],"example":"八國聯軍口訣「餓的話每日熬一鷹」（俄德法美日奧義英）；廢科舉＝庚子後新政，皇族內閣＝立憲運動","fig":{"src":"../assets/fig/history/u8-s5.svg","cap":"八國聯軍進攻路線與俄國占領東北"}},{"heading":"晚清社會文化的變遷","points":["鴉片戰爭後開五口通商、英法聯軍後增設口岸；外國人在通商口岸設租界，引進現代化設施，上海為代表","上海為《南京條約》增開口岸之一，西方商人在此發展貿易，不久取代廣州成為最大貿易港，有「東方華爾街」之稱","上海公共租界工部局成立於19世紀中期，在租界內實行自治、徵稅與城市建設，董事會多由外僑組成、英國人占多數","19世紀末上海為半封建、半殖民的國際大都市","上海租界中保皇與革命、中與西、新與舊各種思潮雜處，小說家在此批評舊思想","通商口岸發展國際貿易與工商業，提供就業機會、吸引人口移居，也間接增加婦女就業機會","新事物：西餐咖啡、西服、西式建築、自來水、電燈、電車火車、電報電話、電影百貨公園，洋貨成身分象徵","城市新風貌：斷髮放足風氣日盛、西服洋裝流行；西式馬車、自行車、人力車，20世紀初有汽車；19世紀上海已有電燈","新式教育培育新知識分子；外國人引進新式報刊（如美國傳教士創辦的《萬國公報》），加速新思潮傳播","報刊雜誌（如《萬國公報》《申報》）介紹中外時事與西方新思潮，知識分子藉此發表言論，增進公眾對公共事務的關心","傳統家族觀念：累世同居共財、家族重於個人、重孝道倫理；婦女遵守「三從四德」附屬家庭","傳統婚姻憑「父母之命」，目的為傳宗接代；西方思想傳入後，部分知識分子提倡戀愛與婚姻自由","太平天國主張男女平等，禁止買賣婚姻、納妾、纏足，女子可應試、任官、從軍","傳教士與新知識分子（如梁啟超）提倡女權：解放纏足、設女子學校、追求就業參政，婦女意識提升（如秋瑾投身革命）","20世紀初知識分子創辦《女報》《女學報》《女子世界》《中國女報》等女性刊物，多在上海發行，倡導女權與女學","何香凝自幼拒纏足，與廖仲愷的婚姻稱「天足緣」；留日投入革命，發表〈敬告我同胞姊妹〉推動婦女覺醒"],"example":"1844年寧波女塾、1897年中國女學會→開港後傳教士與知識分子提倡女學","fig":{"src":"../assets/fig/history/u8-s6.svg","cap":"晚清開放的通商口岸"}}],"confusions":[{"a":"鴉片戰爭","b":"英法聯軍","diff":"鴉片戰爭因林則徐禁煙、開沿海五口；英法聯軍因英國要求全面通商修約，增開長江沿岸與臺灣口岸、火燒圓明園","tip":"沿海五口→鴉片戰爭；深入內地、臺灣開港、天津條約→英法聯軍"},{"a":"協定關稅","b":"領事裁判權","diff":"協定關稅是進口稅率須與外國協商，喪失經濟（關稅）主權；領事裁判權是外人在華犯罪由其領事依本國法審判，喪失司法主權","tip":"稅→協定關稅；審判、犯罪、訴訟→領事裁判權"},{"a":"南京條約","b":"馬關條約","diff":"南京條約（1842，鴉片戰爭）割香港、開五口；馬關條約（1895，甲午戰爭）割臺澎、朝鮮獨立、允許設廠","tip":"香港、五口→南京；臺澎、朝鮮、設廠→馬關"},{"a":"自強運動","b":"戊戌變法","diff":"自強運動（1861）由地方官員推動、學西方器物技術；戊戌變法（1898）由光緒與康梁推動制度改革","tip":"兵工廠、艦隊、同文館＝自強（器物）；京師大學堂、康梁＝戊戌（制度）"},{"a":"自強運動","b":"明治維新","diff":"兩者同在19世紀中期起步，自強只學器物且由地方推動；明治維新全面西化、由天皇中央推動，甲午戰爭見高下","tip":"器物 vs. 全面西化（含君主立憲）"},{"a":"明治維新","b":"大化革新","diff":"明治維新是19世紀中期日本全面學習西方的現代化改革；大化革新是7世紀中期日本仿效唐朝制度的改革","tip":"西化、君主立憲→明治維新；唐化、律令→大化革新"},{"a":"租借港灣","b":"勢力範圍","diff":"租借港灣是列強向中國租用特定港口，期滿可收回；勢力範圍是列強在某一地區享有獨占利權（鐵路、礦產等）","tip":"旅順、膠州灣、威海衛、廣州灣、新界→租借；東北、山東、長江流域、福建、西南→勢力範圍"},{"a":"庚子後新政","b":"立憲運動","diff":"新政是八國聯軍後慈禧為挽回人心推動（廢科舉、新軍）；立憲運動是日俄戰爭後要求制憲、開國會","tip":"廢科舉→新政；憲法、國會、責任內閣、皇族內閣→立憲"}],"terms":[{"term":"一口通商","def":"1757年起清廷限定外國商人只能在廣州貿易，並須透過公行交易，不得直接與官府交涉。"},{"term":"公行","def":"清代專門負責對外貿易的中國商行組織，受官方支持、壟斷對外貿易，外商只能透過它交易。"},{"term":"五口通商","def":"1842年《南京條約》開放上海、寧波、福州、廈門、廣州通商，結束一口通商。"},{"term":"租界","def":"外國在中國通商口岸劃定的居住經商區域，外國人不受中國政府管轄，形同「國中之國」。"},{"term":"協定關稅","def":"中國對進口貨物的稅率須與外國協商，失去自主決定關稅的權利。"},{"term":"領事裁判權","def":"外國僑民在中國不受中國法律約束，由其所屬國領事依該國法律處理，使中國喪失司法主權。"},{"term":"片面最惠國待遇","def":"中國若給予其他國家新權利或優惠，享有此待遇的國家可一併援例享有，但中國無對等權利。"},{"term":"總理各國事務衙門","def":"1861年設立、負責對外事務的機構，也是推行自強運動的主要機構，顯示中國進入西方主導的國際秩序。"},{"term":"師夷長技以制夷","def":"學習西方的長處（船堅炮利等技術）來抵抗西方列強，為自強運動的主要目標。"},{"term":"外務部","def":"1901年《辛丑和約》規定將總理衙門改為外務部，位居六部之首，顯示清廷被迫接受西方國際關係"},{"term":"黑船事件","def":"1853年美國海軍將領培里率艦隊到日本要求開港，日本被迫開港通商、結束鎖國。"},{"term":"《朝日修好條約》","def":"1876年朝鮮與日本在江華島簽訂，日本取得領事裁判權、貿易權等，為朝鮮首個不平等條約"},{"term":"三國干涉還遼","def":"甲午戰後《馬關條約》割讓遼東半島，俄、德、法出面干涉，日本被迫歸還，由清廷出款贖回"},{"term":"瓜分風潮","def":"甲午戰爭後列強強行向中國租借港灣、劃分勢力範圍，例如德國以山東為勢力範圍。"},{"term":"門戶開放政策","def":"美國於瓜分風潮時提出，要求列強開放勢力範圍供各國貿易、利益均霑，獲英國支持後得列強認可"},{"term":"戊戌政變","def":"1898年慈禧太后與守舊派發動政變，軟禁光緒皇帝，康、梁逃往海外，戊戌變法僅103天即失敗"},{"term":"百日維新","def":"1898年戊戌變法因戊戌政變而失敗，僅維持約103天，故稱百日維新。"},{"term":"京師大學堂","def":"戊戌變法時設立的新式學校，教授西方知識，為今北京大學前身，也是變法唯一保留的成果。"},{"term":"義和團","def":"練習義和拳的民間團體，以「扶清滅洋」為號召燒教堂、殺洋人，1900年引發八國聯軍。"},{"term":"辛丑和約","def":"1901年八國聯軍後簽訂，中國支付鉅額賠款，並拆除北京至出海口砲臺、各國駐軍使館區。"},{"term":"諮議局","def":"清末預備立憲時於1909年在各省設立的民意機構，議員經選舉產生，是中國首次民意代表選舉"},{"term":"皇族內閣","def":"1911年清廷成立的責任內閣，成員多為皇親貴族，顯示改革無誠意，使立憲派轉向支持革命。"},{"term":"通商口岸","def":"依不平等條約開放外國人通商居住的港口城市，成為中國接觸西方物質、知識與文化的窗口。"},{"term":"工部局","def":"19世紀中期成立的上海公共租界管理機構，行使近似政府的權力，負責治安、稅收與建設，由外僑董事會主導"},{"term":"萬國公報","def":"美國傳教士創辦的新式報刊，介紹西洋歷史地理、自然科學與各國時事，傳播新知。"},{"term":"《申報》","def":"晚清在上海發行的重要報紙，與《萬國公報》等新媒體成為介紹中外時事、傳播西方新思潮的管道"},{"term":"太平天國","def":"19世紀中洪秀全以拜上帝會為基礎建立的政權，勢力及長江中下游，主張男女平等，後遭清廷剿平"},{"term":"不纏足運動","def":"晚清新知識分子與傳教士提倡女權，反對婦女纏足的運動，與興辦女學同為婦女角色轉變的代表"},{"term":"天足","def":"指未纏足的天然雙足；晚清提倡不纏足，何香凝與廖仲愷的婚姻即被稱為「天足緣」"}],"timeline":[{"time":"1757","event":"乾隆限制外商只能在廣州貿易，實施一口通商"},{"time":"1793","event":"英國派馬加爾尼來華交涉放寬通商，因拒行跪拜禮（叩首禮）無功而返"},{"time":"1839","event":"道光帝派林則徐到廣州查禁鴉片"},{"time":"1840~1842","event":"鴉片戰爭，清廷戰敗簽訂《南京條約》，割香港、開五口通商"},{"time":"1843","event":"簽訂《南京條約》續約，給予英國協定關稅、領事裁判權、設立租界、片面最惠國待遇等特權"},{"time":"1851","event":"洪秀全建立太平天國，勢力擴及長江中下游"},{"time":"1853","event":"美國培里率艦叩關（黑船事件），日本被迫開港（1854年開港通商）"},{"time":"1857~1860","event":"英法聯軍，簽訂《天津條約》等，增開口岸（含臺灣）、外人可入內地傳教"},{"time":"1858","event":"英法聯軍期間簽訂《天津條約》，增開通商口岸，列強勢力深入內地"},{"time":"1861","event":"設總理各國事務衙門，自強運動展開"},{"time":"1868","event":"日本明治天皇推動明治維新"},{"time":"1874","event":"日本以牡丹社事件為由出兵侵犯臺灣"},{"time":"1876","event":"朝鮮與日本在江華島簽訂《朝日修好條約》，為朝鮮首個不平等條約"},{"time":"1879","event":"日本併吞琉球"},{"time":"1884","event":"清法戰爭，越南成為法國殖民地"},{"time":"1894~1895","event":"甲午戰爭，清廷戰敗簽訂《馬關條約》，割讓臺灣、澎湖"},{"time":"1898","event":"光緒皇帝推動戊戌變法，戊戌政變後失敗（百日維新）"},{"time":"1900","event":"義和團事變引發八國聯軍攻陷北京"},{"time":"1901","event":"簽訂《辛丑和約》；慈禧推動庚子後新政"},{"time":"1904~1905","event":"日俄戰爭，日本戰勝俄國"},{"time":"1905","event":"清廷廢除科舉"},{"time":"1906","event":"清廷下詔預備立憲，立憲運動展開"},{"time":"1908","event":"清廷公布《憲法大綱》（憲法草案）"},{"time":"1909","event":"清廷預備立憲，各省成立諮議局，舉辦中國首次民意代表選舉"},{"time":"1910","event":"日本併吞朝鮮"},{"time":"1911","event":"成立責任內閣被譏為「皇族內閣」；辛亥革命爆發"}],"sources":[{"name":"林則徐致外國君主文書","gist":"欽差大臣到廣州查禁鴉片前，致書英國君主，指英國本國禁食鴉片甚嚴，要求停止輸入。","clue":"欽差大臣、廣州、鴉片、白銀外流 → 鴉片戰爭前"},{"name":"《南京條約》及續約","gist":"清廷賠款、割讓香港、開放五口通商，並允許租界、協定關稅、領事裁判權、片面最惠國待遇。","clue":"租界、領事審判、五口、香港 → 1842年後"},{"name":"朝鮮「斥和碑」","gist":"興宣大院君在全國豎立，宣示「洋夷侵犯，非戰則和，主和賣國」，表達閉關排外決心","clue":"洋夷、斥和、大院君 → 19世紀中後期朝鮮閉關自守"},{"name":"中國鐵路零公里紀念碑碑文","gist":"「中華鐵路，師夷之技，源唐胥始，於龍號起」，記中國自辦鐵路的起源","clue":"師夷之技、唐胥鐵路、龍號 → 自強運動"},{"name":"日本明治憲法（大日本帝國憲法）","gist":"19世紀末發布，規定天皇神聖不可侵犯、擁有主權、統帥軍隊並任命內閣，人民權利在限制下獲承認","clue":"天皇神聖不可侵犯、任命內閣 → 明治維新君主立憲；日俄戰爭後中國鼓吹立憲"},{"name":"清廷甲午宣戰詔書","gist":"稱朝鮮為大清藩屬，指責日本派兵欺壓、強令改革政治，倭船開炮挑釁，因而宣戰","clue":"藩屬、倭人、強令改革政治、添兵保護 → 1894年甲午戰爭（導火線朝鮮）"},{"name":"《馬關條約》","gist":"清廷承認朝鮮獨立自主、割讓臺灣澎湖、賠款，並允許日人在通商口岸設廠。","clue":"朝鮮、臺澎、設廠、李鴻章與伊藤博文 → 甲午戰爭後"},{"name":"康有為上光緒書","gist":"主張效法日本變法、開制度局，推動制度層面改革。","clue":"康梁、采鑒於日本、制度局 → 戊戌變法"},{"name":"清廷宣戰／懲處縱庇拳匪諭旨","gist":"清廷將變亂歸咎王大臣縱庇拳匪、圍攻使館，釀成大禍。","clue":"拳匪、扶清滅洋、圍攻使館、洋鬼子 → 義和團與八國聯軍"},{"name":"苗栗虎頭山日露戰役紀念碑","gist":"日俄戰爭時日軍在虎頭山設望樓監視波羅的海艦隊，戰後建碑紀念，2024年登錄為歷史建築","clue":"日露戰役、旅順、波羅的海艦隊、對馬海峽、樸茨茅斯條約 → 日俄戰爭（1904～1905）"},{"name":"清末《欽定憲法大綱》評論","gist":"憲法由皇帝頒布，強調皇帝神聖不可侵犯，民權未提，被批借憲政之名行專制之實。","clue":"預備立憲、國會、責任內閣、皇族內閣 → 立憲運動（日俄戰爭後）"}]},{"unit":9,"part":"中國與東亞史","title":"現代國家的興起","summary":"學習民國建立、袁世凱與軍閥統治、山東問題與五四運動、新文化運動、北伐與十年建設、國共衝突，以及日本侵華與太平洋戰爭；會考常以史料關鍵字判斷時期與事件先後順序。","sections":[{"heading":"辛亥革命與民國建立","points":["甲午戰後知識分子追求制度改革：立憲派（康有為、梁啟超）主張君主立憲；革命派（孫文）主張推翻清廷、建立民主共和","1894年甲午戰爭刺激下，孫中山成立興中會，後組中國同盟會，屢遭打壓卻漸獲社會支持","清廷推動立憲卻成立責任內閣，名單多為皇族（「皇族內閣」），成效有限，部分立憲派失望而轉向支持革命","清末改革派菁英積極收回利權（尤其鐵路）；皇族內閣破壞康熙以來滿漢均衡的雙頭政治，成為革命導火線","1911年清廷宣布鐵路收歸國有，引發保路運動（四川最激烈），清廷自湖北調兵入川鎮壓","湖北新軍：甲午戰後以新式武器與訓練方式改組的軍隊；被調入四川鎮壓保路運動，使湖北守備空虛","革命黨趁湖北防務空虛，1911年10月10日武昌起事成功，湖北革命軍成立軍政府；南方各省接連宣布獨立（辛亥革命）","辛亥革命三條件：意識形態（共和、反滿）、組織（興中會、同盟會）、機會（鐵路國有引發保路運動）","1912年1月1日中華民國臨時政府於南京成立，孫文任臨時大總統，以五色旗為國旗，結束兩千多年帝制","民國成立後以民國紀年、陽曆計日，取代原本的帝王紀年與農曆計日","南北議和：1911年底南方獨立省分（孫中山）與清廷（袁世凱）談判，次年2月議定清室優待，袁世凱促使宣統皇帝（溥儀）退位","清室優待條件：皇帝辭位後尊號不廢、以外國君主之禮相待、歲用四百萬兩由民國撥付、暫居宮禁","清帝退位後孫文依約辭職，由袁世凱接任臨時大總統"],"example":"記口訣「鐵路國有→保路運動→武昌起事→民國建立→清帝退位」；雙十國慶源自武昌起事。","fig":{"src":"../assets/fig/history/u9-s1.svg","cap":"武昌起事後各省紛紛宣布獨立（1911）"}},{"heading":"袁世凱當權與軍閥統治","points":["袁世凱藉編練新軍掌握大權；民國成立後藉口北京兵變不願南下南京就職，臨時政府因而遷往北京（遷都北京）","臨時參議院通過《臨時約法》採內閣制以制衡袁世凱：限制總統職權，由國會議員組成的內閣掌握行政權","民國2年國會大選國民黨大勝（眾議院269席、參議院132席），依內閣制多數黨領袖宋教仁可望出任國務總理","民國2年主導黨務的宋教仁隨即遇刺，國民黨發動二次革命討袁失敗","民國2年10月袁世凱脅迫國會選他為正式大總統，隨後解散國會、廢除《臨時約法》改以新約法","袁世凱利用一戰列強無暇東顧之機建立專制；民國4年接受帝制，改國號「中華帝國」、以民國5年為洪憲元年","洪憲帝制失敗主因：遭各界反對，未獲列強與親信將領支持，袁世凱只好撤銷帝制、恢復共和，不久病逝","民國5～17年軍閥統治：軍隊私有化，袁死後各地將領憑武力割據，爭奪北京政府主導權，內戰不斷","軍閥特色：依附列強、私募軍隊，企圖奪取象徵中央的北京政府，常以武力解決政治糾紛；如東北由張作霖控制","民國6年段祺瑞掌握北京政府，對德宣戰使中國正式加入一戰；並拒絕恢復《臨時約法》，另立新國會","張勳復辟：民國6年張勳到北京調解政爭，趁機擁溥儀復辟恢復帝制，旋遭段祺瑞驅逐，溥儀被迫退位","民國6年孫文號召護法，在廣州另立政府（軍政府），推孫中山為大元帥，形成南北分裂","廣州軍政府不受列強承認，列強仍以北京政府為中國唯一合法政府","民初袁世凱稱帝、軍閥毀法期間，政權均以北京為首都，革命派視北京為反革命勢力的巢窟"],"example":"袁世凱年表：元年臨時大總統→2年正式大總統→3年廢約法→4年接受二十一條→5年稱帝後身亡。"},{"heading":"山東問題與五四運動","points":["山東問題三階段：甲午戰後德國以山東為勢力範圍、租借膠州灣；一戰期間日本強占並提二十一條；一戰後巴黎和會將山東權益交給日本","甲午戰後瓜分危機（瓜分風潮）：德國畫定山東為勢力範圍，並租借膠州灣（以青島為中心），取得山東權益","19世紀末《膠澳租借條約》使膠州灣成為德國租借地（租期99年），德國建港、修鐵路並命名新市區為青島","民國3年一戰爆發，日本藉口對德宣戰，強占德國在山東的勢力範圍","民國4年日本提出「二十一條要求」，袁世凱（北京政府）於5月9日被迫接受部分內容，被稱為「五九國恥」","二十一條引發全國反日，政府將5月9日定為國恥紀念日；民國初年反日聲浪高漲，各地發起抵制日貨行動","民國8年巴黎和會決議由日本繼承德國在山東的權益（中國為戰勝國仍遭拒）","民國8年5月4日北京大學等校學生在天安門抗議，喊出「外爭主權，內除國賊」「還我青島」「廢除二十一條」","五四運動擴及全國：各地罷市、罷工、抵制日貨","影響：北京政府拒簽對德和約；促成社會各階層覺醒，強化國家與民族意識","五四運動後各地大學學生運動興盛，並擴大新文化運動的影響","1922年華盛頓會議簽訂《解決山東懸案條約》，中國出讓部分經濟、政治特權後收回青島"],"example":"山東權益流向：德國（瓜分風潮）→日本（一戰強占、二十一條）→巴黎和會確認→五四運動。"},{"heading":"新文化運動與社會變遷","points":["背景：清末西式教育培養出新知識分子，認為器物與制度改革不足，須全面改革思想文化","清末以來新知識分子取代傳統士紳，扮演傳播知識、批評社會的角色；新文化運動強調個人獨立自主","民國4年陳獨秀創辦《青年雜誌》（後改《新青年》）為開端；北京大學校長蔡元培提倡學術自由，成為重鎮","推廣白話文（胡適、陳獨秀），以通俗白話取代文言文；民國6年胡適發表〈文學改良芻議〉，打響白話文變革第一槍","白話文不用文言、不講究平仄諧韻，胡適嘗試白話詩創作；魯迅〈狂人日記〉為白話文創作典範","白話文與新式標點符號流行，有助教育普及","鼓吹「德先生」（民主）與「賽先生」（科學），挑戰儒家傳統，部分人主張全盤西化、「打倒孔家店」","新文化運動中儒家傳統地位受挑戰，學術思想呈現百家爭鳴","引進共產主義等西方學說，民國10年陳獨秀等人在俄國共產黨策動指導下，於上海成立中國共產黨","五四運動時學生被批評激進，北大校長蔡元培仍親自挺身保護學生","民初社會變遷：婦女解放追求男女平等（婚戀自由、男女共學、就業參政）；關注兒童（幼稚園、兒童讀物），強調兒童本位","婦女教育：清末傳教士與新知識分子提倡女子教育；新文化運動時女性可與男性同校共學、就讀大學，衝擊「男女授受不親」","婦女投入職場：任職公營機關、大學任教、自行創業","婦女參政：清末秋瑾參與革命，民初女性參與五四遊行、積極爭取參政權","民初新女性主張提升婦女政治教育，如中等以上學校政治學程須與男子相當","兒童教育：清末開辦蒙養院為正式學前教育，新文化運動時改稱幼稚園、培育專門師資，並以科學方法研究兒童心理","民初知識分子批評兒童讀物陳腐、夾雜迷信封建思想，主張創作符合兒童需要的讀物"],"example":"新文化運動屬「思想文化層次」改革，對照自強運動（器物）、戊戌變法與立憲（制度）。"},{"heading":"北伐統一與十年建設","points":["民國8年孫中山重組中國國民黨（簡稱國民黨），因應五四運動後的民情變化，以建立軍隊、對付軍閥為目標","中國共產黨民國10年成立，源於新文化運動引進西方學說","孫中山三次在廣東建立政權；民國10年任廣州政府非常大總統，民國12年成立大元帥大本營，決定聯俄並籌建黃埔軍校","孫中山與蘇聯特使簽訂《孫文越飛宣言》確立與蘇聯合作，並題「今後之革命非以俄為師斷無成就」","民國12年孫文「聯俄容共」：接受蘇聯經費武器，共產黨員以個人名義加入國民黨（第一次國共合作）","莫斯科中山大學配合聯俄容共為中國培育革命人才；清黨後國民政府與之斷絕關係，該校不久廢校","民國13年（1924）孫文在蘇聯協助下於廣州成立黃埔軍校（陸軍軍官學校），蔣中正任校長，為中國首個現代軍事學校","孫中山在黃埔軍校的開學訓詞，後來成為中華民國國歌歌詞","民國14年3月孫文逝世，7月廣州政府改組為國民政府，取代大元帥大本營","國民黨北伐宣言：推倒軍閥及其所賴以生存的帝國主義，使中國脫離「次殖民地」地位，為實行三民主義第一步","民國15年蔣中正由廣州誓師北伐；民國16年國民政府遷武漢遭親共人士控制","寧漢分裂：民國16年蔣中正清黨、在南京（寧）另立國民政府，國共決裂","武漢（漢）政府後來也結束與中共合作，併入南京政府，國民黨繼續北伐","北伐最後一步：民國17年底東北軍閥張學良（張作霖之子）宣布歸順國民政府，北伐完成，中國統一，定都南京","建國三階段：軍政（以軍領政，依《臨時約法》）→民17北伐完成→訓政（以黨領政）→民36公布憲法→憲政","實施訓政（軍政→訓政→憲政）：民國20年5月頒布《訓政時期約法》，由國民黨全國代表大會行使統治權","《訓政時期約法》規定中央執行委員會選任國府委員並解釋約法","訓政時期國民黨以黨治國、一黨執政、黨國合一，掌握絕對政治權力，引發輿論批評","民國25年國民政府頒布憲法草案，後因對日戰爭爆發，制憲工作停擺","十年建設（民國17～26年）奠定抗日基礎：財政重整稅收、收回關稅自主權、廢兩改元（民22）、發行法幣（民24）","十年建設的教育與交通：廣設中小學、推動平民教育；修築鐵公路、發展航空","協定關稅（值百抽五）源自《南京條約》續約，因片面最惠國待遇擴及16國；北伐完成後國民政府修訂稅則收回關稅自主權","十年建設成果數據：飛行航線1929年58→1936年7790；工廠1913年245→1932年2695；小學1912年2795→1932年13185所"],"example":"北伐路線：廣州→武漢／南京→北京，張學良東北易幟使「名義上統一」。","fig":{"src":"../assets/fig/history/u9-s5.svg","cap":"北伐統一（1926～1928）"}},{"heading":"國共衝突與西安事變","points":["國共決裂後中共轉往農村，在江西瑞金建立的政權稱「中華蘇維埃共和國」，勢力擴大","民國19年起國民政府多次圍剿中共（國民政府自稱「剿共」）；民國23年中共撤離江西，次年抵陝西北部延安，稱「兩萬五千里長征」","國民政府因日本侵略加劇，1931～1936年採「攘外必先安內」，加緊剿共並避免與日擴大衝突，對日本侵擾隱忍","國民政府主張先消滅赤匪、削平粵逆、完成統一才能禦侮；中共則批評國民政府「不抵抗」「攘外必先安內」","北平學生多次上街抗議、請願，要求改變對日政策","中共宣傳「停止內戰，一致抗日」，影響在陝西剿共的東北軍領袖張學良","民國25年12月張學良在西安兵諫、拘禁蔣中正（西安事變），協議後釋放","影響：國民政府停止剿共；民國26年中日全面開戰，國共宣布一致抗日（第二次合作），中共轉危為安、藉機發展勢力","國共第一次合作因親共人士控制武漢國民政府、蔣中正清黨而結束；第二次合作因戰後日軍占領區接收問題而破裂，爆發國共內戰"],"example":"一次合作（民12～16，為北伐）vs 二次合作（民26～34，為抗日）；轉折點分別是清黨與西安事變。","fig":{"src":"../assets/fig/history/u9-s6.svg","cap":"中共長征與西安事變"}},{"heading":"日本擴張與中日戰爭","points":["日本明治維新後工業化、向外擴張；1920年代晚期（1929年）世界性經濟危機重創日本","軍國主義（以擴充軍備、發動侵略為國家發展宗旨）抬頭，欲藉擴張獲取資源，中國成為首要擴張目標","1894年甲午戰爭、1910年併吞朝鮮，以朝鮮為進攻中國的跳板","近代中日關係：牡丹社事件1874→甲午1894→日俄1904→二十一條1915→巴黎和會1919→九一八1931→七七1937→珍珠港1941","民國20年（1931）九一八事變：日軍自行炸毀南滿鐵路柳條湖段鐵軌嫁禍東北軍，藉口炮轟瀋陽、進攻瀋陽","張學良遵循先安內再攘外政策未抵抗，日軍（關東軍）占領東北","九一八事變後國民政府命令軍隊避免與日軍衝突，將日軍暴行訴諸國際聯盟，要求日軍撤退，待公理解決","民國21年日本扶植溥儀成立滿洲國，軍政大權操於日人","九一八事變後國際派調查團赴東北調查，日本唆使滿洲國阻撓、安排假民意稱頌日軍統治","日本占領東北後推動滿洲農業開發，主張結合漢人農民拓墾、日本農民集團移民與朝鮮移民水田耕作","東北大學是中國第一所抗日流亡大學：九一八後由瀋陽遷北平、西安、四川三臺，戰後1946年遷回瀋陽，流亡15年","民國26年7月7日盧溝橋（七七）事變，中日全面開戰（八年抗戰）","民國26年日軍進攻上海（淞滬會戰）企圖速戰速決；國民政府採「以空間換取時間」遷都重慶；同年底日軍攻陷南京，展開南京大屠殺","重慶位於四川盆地，地勢封閉易守難攻，成為戰時首都，但遭日軍6年多的地毯式轟炸，死傷數萬人","1937年底中國各勢力：日本陣營（滿洲國、華北、南京上海一帶）、國民黨陣營（以重慶為中心）、共產黨陣營（以延安為中心），新疆、西藏尋求獨立","戰時人民三苦：平民傷亡（空襲、軍事衝突）、物資短缺（生產停頓、物價攀升）、徵調勞動力（從軍、軍伕、慰安婦）","戰爭苦難還包括：經濟停頓（給中共壯大空間）、人體實驗、徵召臺籍日本兵與高砂義勇隊","戰時平民死傷人數高於軍隊，如美國空襲日本與投擲原子彈、日軍空襲重慶等","戰時日本為彌補勞動力不足，在殖民地與占領區強制徵用朝鮮勞工與中國俘虜，如長崎端島煤礦"],"example":"日本侵華地點順序：朝鮮（1910）→東北（1931）→華北盧溝橋（1937）→上海→南京→東南亞（1941後）。","fig":{"src":"../assets/fig/history/u9-s7.svg","cap":"日本侵略東亞"}},{"heading":"太平洋戰爭與戰時外交","points":["1938年近衛文麿號召「大東亞新秩序」，以臺灣為南進基地；1940年正式提出「大東亞共榮圈」，實以日本利益為優先","日本南進政策：以「大東亞共榮圈」為號召擴張東南亞，掠奪石油、橡膠等戰爭資源","「ABCD包圍網」：美、英、中、荷對日經濟制裁；日軍南下占領法屬印度支那後，美國全面禁運石油（美、英實施石油禁運）","民國30年（1941）底日本為突破封鎖，偷襲美國夏威夷珍珠港，美國對日宣戰，中國亦正式宣戰，二戰歐亞戰場合流","日軍占領英、美等歐美國家在東南亞與大洋洲的殖民地，鼓吹「大東亞共榮圈」；後期同盟國反攻，日本敗退","臺灣是日本南進基地，戰爭末期成為盟軍空襲目標；總督府在臺灣徵召志願兵前往南洋作戰","民國初年政府即交涉收回領事裁判權（如民國11年公文），直到1943年簽訂平等新約才真正廢除","民國32年起同盟國與中國訂立平等新約，解除《南京條約》以來不平等條約束縛（領事裁判權取消）","1943年中英新約：英國放棄通商口岸制度、上海與廈門公共租界特別法院等條約權利，及任用英籍人士為海關總稅務司的權利","開羅會議（民國32年）由蔣中正、羅斯福、邱吉爾（中美英）三國領袖參加，宣言戰後東北、臺灣、澎湖歸還中華民國","開羅宣言使臺灣戰後由中華民國接收；國籍轉換讓曾為日本從軍的臺灣人（如看護婦）戰後未獲合理對待，對戰爭結束的稱呼也出現爭議","雅爾達會議（民國34年，美英蘇）密約：美英為爭取蘇聯對日宣戰而犧牲中國權益，同意蘇聯取得東北權益","雅爾達會議也決定由美、英、法、蘇四國分區占領德國","民國34年8月美國在廣島、長崎投下原子彈，日本無條件投降，二戰結束；戰後日本長期承受輻射傷害"],"example":"珍珠港事變是中國由「獨立作戰」轉為「與同盟國並肩作戰」的轉折，也是廢除不平等條約的契機。","fig":{"src":"../assets/fig/history/u9-s8.svg","cap":"太平洋戰爭：日本最大勢力範圍（約 1942 年）"}}],"confusions":[{"a":"立憲派","b":"革命派","diff":"立憲派（康有為、梁啟超）主張仿效西方君主立憲、保留皇帝；革命派（孫中山）主張推翻君主專制、建立民主共和","tip":"保皇、君主立憲→立憲派；推翻清廷、民主共和→革命派"},{"a":"民國元年的南北對立","b":"民國6年的南北分裂","diff":"民國元年是北方清帝國與南方中華民國對立，經南北議和清帝退位而結束；民國6年是段祺瑞掌控的北京政府與孫中山在廣州成立的軍政府對立","tip":"清帝國對中華民國→民元；北京政府對廣州軍政府、護法→民6"},{"a":"二次革命","b":"護法運動","diff":"二次革命（民國2年）是國民黨因宋教仁遇刺起兵討袁；護法運動（民國6年）是孫文為維護《臨時約法》對抗段祺瑞，在廣州另立政府造成南北分裂","tip":"宋教仁→二次革命；段祺瑞、廣州→護法"},{"a":"袁世凱廢除臨時約法","b":"段祺瑞拒復臨時約法","diff":"袁世凱於民國3年在二次革命後解散國會、廢除《臨時約法》；段祺瑞於民國6年拒絕恢復《臨時約法》並另立新國會，引發護法運動","tip":"民3、總統獨攬大權→袁世凱；民6、參加一戰、護法→段祺瑞"},{"a":"二十一條要求","b":"巴黎和會","diff":"二十一條（民國4年）是日本向袁世凱索取山東等特權，稱五九國恥；巴黎和會（民國8年）是一戰後列強決議日本繼承德國山東權益，引發五四運動","tip":"袁世凱、五九國恥→二十一條；凡爾賽和約、學生抗議→巴黎和會"},{"a":"新文化運動","b":"五四運動","diff":"新文化運動（民國4年起）是思想文化改革，提倡白話文、民主與科學；五四運動（民國8年）是反對巴黎和會山東決議的愛國抗議","tip":"德先生賽先生、白話文、新青年→新文化；還我青島、外爭主權→五四"},{"a":"《臨時約法》","b":"《訓政時期約法》","diff":"《臨時約法》（民國元年）由臨時參議院通過，採責任內閣制以制衡袁世凱；《訓政時期約法》（民國20年）規定由國民黨代表國民行使統治權、以黨治國","tip":"參議院、臨時大總統、內閣制→臨時約法；國民黨全國代表大會、以黨治國→訓政時期約法"},{"a":"第一次國共合作","b":"第二次國共合作","diff":"第一次（民國12～16年）因孫文聯俄容共、為北伐打倒軍閥，止於清黨；第二次（民國26～34年）因西安事變停止剿共、共同抗日，戰後爆發內戰","tip":"黃埔、北伐→一次；西安事變、抗日→二次"},{"a":"攘外必先安內","b":"停止內戰，一致抗日","diff":"攘外必先安內是國民政府先剿共再抗日的方針；停止內戰，一致抗日是中共的宣傳口號，影響張學良發動西安事變","tip":"國民政府、剿共→攘外必先安內；中共、張學良兵諫→停止內戰一致抗日"},{"a":"九一八事變","b":"七七事變","diff":"九一八事變（民國20年）日軍攻瀋陽、占領東北、次年建滿洲國；七七事變（民國26年）在北平近郊盧溝橋，引爆中日全面戰爭","tip":"瀋陽、東北、滿洲國→九一八；盧溝橋、宛平、全面開戰→七七"},{"a":"淞滬會戰","b":"南京大屠殺","diff":"淞滬會戰（民國26年8月）是日軍進攻上海、國軍頑強抵抗，打破三月亡華計畫；南京大屠殺（民國26年底）是日軍攻陷首都南京後屠殺投降軍民","tip":"上海、三月亡華→淞滬會戰；首都陷落、屠殺平民、照片證據→南京大屠殺"},{"a":"開羅會議","b":"雅爾達會議","diff":"開羅會議（民國32年）中美英參與，宣言戰後東北、臺灣、澎湖歸還中華民國；雅爾達會議（民國34年）美英蘇參與，中國未受邀，同意蘇聯取得東北權益","tip":"有蔣中正、臺澎歸還→開羅；有蘇聯、出賣東北→雅爾達"}],"terms":[{"term":"興中會","def":"1894年甲午戰爭時孫中山成立的革命組織，主張推翻清廷，後與其他團體組成中國同盟會。"},{"term":"民主共和","def":"國家主權屬於全體人民、元首由人民選出的體制；相對於世襲皇帝擁有統治權的君主專制。"},{"term":"國體","def":"國家的型態與元首產生方式，如君主國元首多世襲，共和國元首為總統等，由選舉或指派產生。"},{"term":"湖北新軍","def":"甲午戰後清廷以新式武器與訓練方式改組的軍隊；保路運動時被調入四川，使武昌防務空虛。"},{"term":"保路運動","def":"1911年清廷將民間集資興建的鐵路收歸國有，各地士紳群起反對，以四川最激烈，成為辛亥革命的導火線。"},{"term":"武昌起事","def":"1911年10月10日革命黨趁湖北防務空虛在武昌起事，南方各省紛紛獨立，為辛亥革命開端，也是雙十國慶由來。"},{"term":"清室優待條件","def":"1912年南北議和時中華民國給清室的條件：尊號不廢、歲用四百萬兩、暫居宮禁，以換取宣統退位。"},{"term":"《臨時約法》","def":"民國元年臨時參議院通過，為制衡袁世凱改採內閣制，規定總統重大決議須經國會同意；後遭袁世凱廢除。"},{"term":"二次革命","def":"民國2年宋教仁遇刺，輿論懷疑袁世凱主使，國民黨起兵討伐袁世凱，最終失敗。"},{"term":"洪憲帝制","def":"民國4年底袁世凱接受帝號，改國號為中華帝國、以民國5年為洪憲元年，遭各界反對而被迫取消。"},{"term":"軍閥統治","def":"民國5～17年袁世凱死後，各地將領憑藉武力割據一方，爭奪北京政府主導權，內戰不斷。"},{"term":"張勳復辟","def":"民國6年總統黎元洪請張勳到北京調解政爭，張勳趁機擁溥儀恢復帝制，不久被段祺瑞驅逐而失敗。"},{"term":"護法運動","def":"民國6年孫中山以維護《臨時約法》為號召，率部分國會議員南下廣州成立軍政府，形成南北分裂。"},{"term":"中華民國軍政府","def":"民國6年孫中山南下護法，在廣州成立的政府，推孫中山為陸海軍大元帥，與北京政府對立。"},{"term":"二十一條要求","def":"民國4年日本向袁世凱政府提出，要求給予山東等地特權，袁世凱被迫接受部分內容，稱「五九國恥」。"},{"term":"五四運動","def":"民國8年5月4日北京學生抗議巴黎和會將德國山東權益交予日本，喊出外爭主權、內除國賊，擴及全國。"},{"term":"《解決山東懸案條約》","def":"1922年華盛頓會議期間中日簽訂，中國出讓部分經濟、政治特權，正式收回青島等山東權益。"},{"term":"新文化運動","def":"民國4年起以陳獨秀《青年雜誌》為開端，推廣白話文、提倡民主與科學、批判傳統思想的思想文化改革。"},{"term":"新知識分子","def":"清末以來接受西式教育的知識分子，取代傳統士紳傳播知識、批評社會，推動新文化運動。"},{"term":"蒙養院","def":"清末開辦的正式學前教育機構；新文化運動時改稱幼稚園，並配合培育專門師資。"},{"term":"聯俄容共","def":"民國12年孫文為取得蘇聯援助，同意中共黨員以個人名義加入國民黨，形成第一次國共合作。"},{"term":"黃埔軍校","def":"1924年孫中山在蘇聯協助下於廣州創辦的陸軍軍官學校，蔣中正任校長，為北伐培養軍事人才。"},{"term":"清黨","def":"民國16年北伐期間蔣中正以武力清除國民黨內的共產黨員，並在南京另立國民政府，國共決裂。"},{"term":"訓政","def":"北伐統一後依孫文建國三階段實施，由國民黨訓練人民參政、以黨治國，頒布《訓政時期約法》。"},{"term":"《訓政時期約法》","def":"民國20年國民政府公布的根本大法，規定訓政時期由國民黨代表國民行使統治權，以黨治國。"},{"term":"法幣","def":"民國24年國民政府指定銀行發行的法定貨幣，搭配廢兩改元，解決清末以來幣制混亂的問題。"},{"term":"攘外必先安內","def":"1930年代國民政府面對日本侵略的方針：先剿滅中共再抵抗日本，引發張學良等人不滿。"},{"term":"西安事變","def":"民國25年12月張學良在西安兵諫拘禁蔣中正，要求停止內戰一致抗日，事後國共合作抗日。"},{"term":"九一八事變","def":"1931年9月18日日軍炸毀瀋陽附近南滿鐵路柳條湖鐵軌、嫁禍中國，藉故攻占瀋陽並占領東北。"},{"term":"滿洲國","def":"九一八事變後，日本於民國21年在東北扶植溥儀成立的政權，軍政大權實際操於日人手中。"},{"term":"八年抗戰","def":"民國26年七七事變至34年日本投降，中國對日抗戰的勝利，又稱八年抗戰。"},{"term":"淞滬會戰","def":"民國26年8月日軍進攻上海，企圖速戰速決，國軍頑強抵抗，打破日本三個月亡華的計畫。"},{"term":"三月亡華","def":"中日戰爭初期日本企圖在三個月內滅亡中國的速戰速決計畫，因國軍在淞滬會戰頑強抵抗而失敗。"},{"term":"以空間換取時間","def":"中日戰爭初期國民政府不敵日軍，遷都重慶、進行持久戰，拖垮日本速戰速決企圖的戰略。"},{"term":"戰時首都（陪都）","def":"中日戰爭時期國民政府遷都的重慶，位於四川盆地易守難攻，為抗戰大後方的政治中心。"},{"term":"ABCD包圍網","def":"1940年代初美國、英國、中國、荷蘭對日本實施的經濟制裁與貿易限制，促使日本偷襲珍珠港。"},{"term":"大東亞共榮圈","def":"1940年代日本宣傳帶領東亞國家脫離西方殖民、建立共存共榮新秩序，實則掩護其侵略擴張。"},{"term":"平等新約","def":"民國32年起美、英等同盟國與中國簽訂新約，放棄領事裁判權等在華特權，解除不平等條約束縛。"}],"timeline":[{"time":"1894","event":"甲午戰爭期間孫中山成立興中會，展開革命運動"},{"time":"1911（宣統3年）","event":"鐵路國有引發保路運動；10月10日武昌起事，辛亥革命爆發"},{"time":"1912（民國元年）","event":"1月中華民國臨時政府於南京成立，孫文任臨時大總統；2月清廷確定清室優待條件，宣統皇帝宣布退位，袁世凱接任"},{"time":"1913（民國2年）","event":"宋教仁遇刺，二次革命失敗；10月袁世凱脅迫國會選舉他為正式大總統，隨後解散國會"},{"time":"1914（民國3年）","event":"第一次世界大戰爆發，日本強占德國在山東的勢力範圍"},{"time":"1915（民國4年）","event":"日本提出二十一條要求（五九國恥）；陳獨秀創辦《青年雜誌》，新文化運動開始；12月袁世凱接受推戴為皇帝，定民國5年為洪憲元年"},{"time":"1916（民國5年）","event":"袁世凱取消帝制後病逝，進入軍閥統治"},{"time":"1917（民國6年）","event":"張勳擁溥儀復辟失敗；段祺瑞主導北京政府對德宣戰、拒絕恢復《臨時約法》，孫文護法、在廣州另立政府，南北分裂"},{"time":"1917（民國6年）","event":"胡適發表〈文學改良芻議〉，推動白話文運動"},{"time":"1919（民國8年）","event":"巴黎和會決議日本繼承德國山東權益，爆發五四運動"},{"time":"1921（民國10年）","event":"中國共產黨在上海成立"},{"time":"1921（民國10年）","event":"孫中山在廣州建立中華民國政府，任非常大總統"},{"time":"1922（民國11年）","event":"華盛頓會議簽訂《解決山東懸案條約》，中國收回青島"},{"time":"1923～1924（民國12～13年）","event":"孫文聯俄容共；成立黃埔軍校"},{"time":"1925（民國14年）","event":"3月孫中山逝世；7月國民政府在廣州成立"},{"time":"1926（民國15年）","event":"蔣中正由廣州誓師北伐"},{"time":"1927（民國16年）","event":"蔣中正清黨，在南京另立國民政府，國共決裂"},{"time":"1928（民國17年）","event":"張學良東北歸順，北伐完成；開始訓政與十年建設"},{"time":"1931（民國20年）5月","event":"國民政府公布《中華民國訓政時期約法》"},{"time":"1931（民國20年）","event":"九一八事變，日軍攻占瀋陽、占領東北"},{"time":"1932（民國21年）","event":"日本扶植溥儀成立滿洲國"},{"time":"1934～1935（民國23～24年）","event":"中共撤離江西，長征抵陝北延安"},{"time":"1936（民國25年）","event":"國民政府頒布憲法草案，後因中日戰爭制憲停擺"},{"time":"1936（民國25年）","event":"西安事變，國民政府停止剿共"},{"time":"1937（民國26年）","event":"七七（盧溝橋）事變，中日全面開戰；淞滬會戰、遷都重慶、南京大屠殺"},{"time":"1938（民國27年）","event":"日本首相近衛文麿號召建立「大東亞新秩序」"},{"time":"1939（民國28年）","event":"第二次世界大戰歐洲戰場爆發"},{"time":"1940（民國29年）","event":"日本正式提出「大東亞共榮圈」構想"},{"time":"1941（民國30年）","event":"ABCD包圍網形成，美國全面禁止對日輸出石油"},{"time":"1941（民國30年）","event":"日軍偷襲珍珠港，太平洋戰爭爆發，中國正式對日宣戰"},{"time":"1943（民國32年）","event":"同盟國與中國訂平等新約；開羅會議"},{"time":"1945（民國34年）","event":"雅爾達會議；美國於廣島、長崎投原子彈，日本無條件投降"}],"sources":[{"name":"德國在山東的勢力範圍圖","gist":"標示清末德國在山東的勢力範圍與膠州灣租借地。","clue":"山東、膠州灣、青島、（德）→山東問題源頭"},{"name":"青島路名變遷","gist":"青島街道名稱由德式（漢堡街、俾斯麥街）改為日式（深山町、萬年町），收回後改為河南路、江蘇路等中國地名。","clue":"德式→日式→中國地名＝德國租借→日本占領→中國收回"},{"name":"秋瑾創辦《中國女報》","gist":"清末革命女性秋瑾創辦的女性雜誌，提倡女權、婦女解放。","clue":"秋瑾、女報、女權→清末民初婦女解放"},{"name":"武昌起事前後形勢圖","gist":"標示四川保路運動、武昌起事、南京成立中華民國與宣布獨立的南方省分。","clue":"四川、武昌、南京、獨立省分集中在南方、清廷仍在北京→辛亥革命"},{"name":"武昌起事革命軍旗（鐵血十八星旗）","gist":"紅底黑色九角星綴黃色圓點，武昌起事後湖北軍政府使用，介於清帝國黃龍旗與民國五色旗之間。","clue":"黃龍旗→革命軍旗→五色旗→武昌起事後、民國成立前"},{"name":"清帝退位詔書","gist":"宣布將統治權公諸全國、定為共和立憲國體，由袁世凱全權組織臨時共和政府與民軍協商統一。","clue":"統治權公諸全國、共和立憲、袁世凱組織臨時共和政府→1912年清帝退位"},{"name":"民國2年國會選舉各黨席次表","gist":"國民黨在參、眾兩院皆為第一大黨，多數黨領袖卻在赴北京途中遇刺。","clue":"參議院、眾議院、國民黨最多席、國務總理、遇刺→民國2年宋教仁案"},{"name":"民國初年漫畫〈環遊地球〉","gist":"猴子沿地球順時鐘由專制、立憲跑到共和，暗示政局將再回到專制。","clue":"共和之後是專制→袁世凱解散國會、廢約法、稱帝"},{"name":"《新青年》封面（LA JEUNESSE）","gist":"陳獨秀主撰的雜誌，前身為民國4年創刊的《青年雜誌》，揭開新文化運動序幕。","clue":"新青年、陳獨秀主撰、LA JEUNESSE→新文化運動"},{"name":"陳獨秀、胡適等新文化運動論述","gist":"主張以白話取代艱澀文言文，批判孔教、禮法、貞節等舊思想，鼓吹民主與科學。","clue":"《青年雜誌》《新青年》、白話、德先生賽先生、破壞孔教、個人獨立"},{"name":"古德諾《共和與君主論》","gist":"1915年美籍學者主張中國習於君主政治，共和太驟，以君主立憲較為適宜。","clue":"1915年、由專制一變而為共和、君主制較共和制為宜→袁世凱稱帝輿論"},{"name":"洪憲紀元銀幣","gist":"袁世凱稱帝時鑄造的錢幣，鑄有「中華帝國」「洪憲紀元」字樣與龍紋。","clue":"中華帝國、洪憲→民國5年（1916）袁世凱稱帝"},{"name":"愛國紀念章（抵制日貨、勿忘國恥）","gist":"民初愛國人士製作的徽章，寫有「抵制日貨，始終勿渝」「同胞勿忘國恥」。","clue":"國恥、抵制日貨→二十一條、巴黎和會後的反日浪潮"},{"name":"民國6年軍閥割據示意圖","gist":"以不同顏色標示各主要軍閥派系的割據範圍，廣州另有政權。","clue":"多色塊割據、北京與廣州並立→軍閥統治、南北分裂"},{"name":"孫中山大元帥府（廣州士敏土廠）","gist":"孫中山1917～1925年在廣東建立政權，兩度以士敏土廠為大元帥府，對抗北方軍閥政府。","clue":"廣州、大元帥、護法、軍閥林立、國家大法→民國6年後南北分裂"},{"name":"胡適〈文學改良芻議〉","gist":"民國6年胡適發表，主張文學改良、以白話取代文言，被視為白話文變革的第一槍。","clue":"胡適、文學改良、白話→新文化運動"},{"name":"五四運動〈北京學界全體宣言〉","gist":"痛陳日本在和會要求併吞青島、管理山東，呼籲各界起來救國，中國的土地可以征服而不可以斷送。","clue":"萬國和會／巴黎和會、青島、山東、凡爾賽和約、學生罷課、外爭主權內除國賊"},{"name":"五四運動紀念郵票","gist":"郵票印有「紀念五四運動」「爭取民主自由」「打破專制枷鎖」，以鐵鎚擊斷鎖鏈為圖案。","clue":"五四、爭取民主自由、打破枷鎖→爭取國家主權"},{"name":"民初兒童文學與《小朋友》雜誌","gist":"民初出版兒童故事、兒童雜誌，顯示社會開始重視兒童、以兒童為本位。","clue":"兒童讀物、童話、小朋友雜誌→民初關注兒童"},{"name":"《孫文越飛宣言》與孫文題字「以俄為師」","gist":"孫中山與蘇聯特使越飛發表宣言，確立與蘇聯合作推動革命，後題「今後之革命非以俄為師斷無成就」。","clue":"越飛、以俄為師、黃埔軍校→聯俄容共"},{"name":"國民黨北伐宣言","gist":"宣示北伐目的在推倒軍閥與帝國主義，使中國脫離次殖民地地位，實行三民主義。","clue":"推倒軍閥、帝國主義、次殖民地、三民主義第一步→北伐"},{"name":"國民政府告國民書（民國20年9月23日）","gist":"九一八事變後政府說明將日軍暴行訴諸國聯，命令軍隊避免衝突，要求國民保持鎮靜，並表示已有自衛決心。","clue":"東三省暴行、本月十八日、訴諸國聯、避免衝突→九一八事變後不抵抗、訴諸國際"},{"name":"〈松花江上〉歌詞","gist":"描寫東北人民在九一八事變後失去家鄉、流亡關內的悲痛與思鄉之情。","clue":"家在東北松花江上、那個悲慘的時候、流浪關內→九一八事變"},{"name":"滿洲國宣傳海報（保衛新國家國境）","gist":"以滿洲國為主體，描繪滿洲國軍隊守衛國境、驅逐中華民國勢力，宣傳「我們的新國家」。","clue":"滿洲國國旗（五色旗）、國境、新國家→1932～1945年東北"},{"name":"張學良兵諫自述","gist":"與蔣委員長對「安內攘外」意見衝突，勸諫無效後以武力拘禁蔣委員長。","clue":"東北軍、兵諫、安內攘外／攘外安內、停止內戰一致抗日→西安事變"},{"name":"抗戰宣傳海報「持久抗戰，最後勝利」","gist":"畫面為中國士兵持國旗壓制日本士兵，標語強調不屈不撓、持久抗戰。","clue":"持久抗戰、敵人武力終有窮時→中日戰爭時期以空間換取時間"},{"name":"近衛文麿「大東亞新秩序」宣言與解密公文","gist":"1938年號召以日本為盟主建立共存共榮的新秩序，1940年擴大為大東亞共榮圈；解密公文顯示重視占領地物資與大和民族利益。","clue":"共存共榮、南進基地臺灣、日本為盟主、解放歐美統治的亞洲→日本侵略的宣傳口號"},{"name":"1943年《中英新約》條文","gist":"英王放棄在中國通商口岸制度、上海廈門公共租界特別法院等現行條約權利，並放棄任用英籍人士為海關總稅務司。","clue":"英王陛下放棄……條約權利、海關總稅務司→平等新約，中國對日宣戰後與盟國平等往來"},{"name":"平等新約紀念郵票（1943）","gist":"中華郵政發行，紀念美、英等國與中國簽訂平等新約、放棄在華特權。","clue":"1943、平等新約、中英美國旗、領事裁判權取消→太平洋戰爭後同盟國合作"},{"name":"日本天皇終戰詔書","gist":"表明接受美、英、中、蘇聯合公告，因敵方使用殘酷炸彈、戰局不利而停止作戰。","clue":"朕、帝國、向美英宣戰、殘酷之炸彈（原子彈）→1945年日本無條件投降"},{"name":"滿洲國郵票加蓋中華民國字樣（東北暫用）","gist":"滿洲國發行的郵票，戰後加蓋「中華民國」「限東北貼用」等字改作他用。","clue":"滿洲國原票＋中華民國加蓋→1945～1949年接收東北時期"}]},{"unit":10,"part":"中國與東亞史","title":"當代東亞的局勢","summary":"學習國共內戰、中華人民共和國從大躍進、文化大革命到改革開放的發展，以及冷戰下韓戰、越戰、中美蘇關係與東南亞國際組織的演變；會考常以史料、宣傳海報與統計圖判斷事件與時序。","sections":[{"heading":"國共內戰","points":["背景：中日戰爭期間中共趁機擴張；戰後獲蘇聯援助，接收日軍在東北的物資武器","起因：國共雙方為爭奪戰後日本占領區的接收問題，在各地爆發衝突","戰後東北曾將滿洲國郵票加蓋「中華民國」暫作使用，反映1945～1949年政府接收東北的過渡時期","民國34年底美國派馬歇爾來華調處國共，在政治協商會議前成立三人小組會議，最終未達共識","馬歇爾以美國駐華特使身分調停國共失敗，返國後出任美國國務卿，後獲諾貝爾和平獎；國共衝突愈演愈烈、內戰擴大，美國停止援助國民政府","民國36年頒布並實施《中華民國憲法》；37年蔣中正獲選為行憲後第一任總統，國民政府改組為中華民國政府","民國37年頒布《動員戡亂時期臨時條款》，擴大總統職權，憲政難以落實","內戰初期國民黨擁有軍事優勢，但長期戰爭導致通貨膨脹、物價飆漲，政府又無法妥善解決通貨膨脹","戰局逆轉：加上官員貪汙腐敗（腐化），民怨四起，國民政府統治陷入危機，局勢轉而有利中共","內戰期間通貨膨脹：100元法幣民國26年可買兩頭牛，30年一大袋麵粉，34年兩顆雞蛋，38年僅一小張紙","戰後通膨：一袋米1937年12元→1948年6月670萬元→同年8月6,300萬元，財政金融全面崩潰","1947～1948年中國貨幣供應量增幅暴增（1948年約36%），反映內戰時期通膨失控、經濟崩潰","民國38年（1949年）底中華民國政府撤退至臺灣，形成兩岸分治"],"example":"100元法幣：1937年可買兩頭牛，1949年只能買一小張紙——通貨膨脹是國民政府失去民心的關鍵。","fig":{"src":"../assets/fig/history/u10-s1.svg","cap":"國共內戰與中共勢力擴張（1945～1949）"}},{"heading":"中共建政初期與文化大革命","points":["1949年10月1日中華人民共和國成立，定都北京，中國共產黨一黨專政，毛澤東為領導人","土地改革：沒收地主土地分給貧農、再收歸國有；中共利用群眾鬥爭地主以取得農民支持，土地改革成功是中共穩定政權的最大原因","初期統治：計畫經濟將民間企業收歸國有；鎮反運動、思想改造控制知識分子","中共建政初期外交向蘇聯靠攏，1950年以「抗美援朝」派志願軍援助北韓","大躍進（1958年起）：毛澤東以「超英趕美」為目標，推行人民公社（集體生產、吃大鍋飯）與土法煉鋼，號召「全民大煉鋼鐵」","人民公社讓農民集體生活、集體生產，也利於政府管理","大躍進將約70萬個農業合作社整編為約2.4萬個人民公社，每社最少3萬人，一切集中化、組織化以增加產量","大躍進結果：生產意願低落、各地虛報產量（浮誇風）、只煉出廢鐵，引發大饑荒，數千萬人死亡","受1958～1960年大躍進影響，1960年代初中國GDP成長率跌至負值（約-27%），經濟嚴重衰退","文革背景：大躍進失敗後毛澤東地位受挑戰，為奪回權力、重掌大權而發動文化大革命（1966~1976年）","文革：毛澤東鼓動青年組紅衛兵，喊「革命無罪，造反有理」「破四舊，立四新」，批鬥師長、破壞文物","文革塑造個人崇拜（小紅書《毛語錄》），群眾對毛的個人崇拜達到頂點","文革造成社會動盪、經濟衰退、教育停頓，被稱「十年浩劫」；1976年毛澤東逝世、四人幫被捕後結束","文革輸出革命：1960年代中共支持東南亞共產黨革命，部分非洲與中南美洲領導人前往北京學習毛澤東思想","文革影響1968年法國學運：法國抗議運動中出現毛澤東肖像、《毛語錄》，甚至有穿紅衛兵裝的法國青年","1981年中共決議徹底否定文化大革命；近年出現「不能用後三十年否定前三十年」的說法，改稱文革為「艱辛探索」","2025年中國實施「農村集體經濟組織」，被批評為人民公社的再現、共產黨鞏固政權的手段"],"example":"記時序口訣：抗美援朝（1950）→大躍進（1958）→文革（1966）→改革開放（1978）。"},{"heading":"改革開放與六四天安門事件","points":["文革後經濟衰弱，鄧小平掌權，1978年起推動「對內改革，對外開放」，逐步放寬經濟限制","在沿海設經濟特區（深圳、珠海、汕頭、廈門、海南），利用低廉勞力、便利海運、優惠政策吸引外國資金與技術","改革開放以廉價勞動力吸引外資，中國成為世界工廠；收入大增：城鎮居民1978年約343元→2018年約3.9萬元，農村約134元→1.5萬元","改革開放負面影響：發展集中於東部沿海，區域發展失衡、城鄉差距與貧富差距擴大","2003～2013年中國官方吉尼係數約0.47～0.49，超過聯合國警戒值0.4，反映改革開放後貧富不均","六四背景：改革開放後「經濟開放、政治保守」，學生訴求政治民主改革；城鄉差距、貧富不均擴大，加上官員貪汙，民怨高漲","1989年北京學生在天安門廣場集會，要求政治民主改革、民主自由；6月4日中共為穩定政權派軍鎮壓、打壓政治訴求，造成眾多傷亡","六四事後西方國家經濟制裁使中國發展陷入停滯、經濟一度停滯，但憑充沛勞動力與廣大市場持續改革","六四後中共政治更趨保守、持續嚴控，維持「經濟開放、政治專制（政左經右）」，為少數維持共黨專政的國家","香港、澳門分別於1997、1999年回歸中國，設特別行政區","中國近年發展：加入世界貿易組織、主辦北京奧運、推動國際開發合作，以經濟與軍事力量擴大國際影響力，國際地位提升","中國當前挑戰：壓制民主、人權不彰；貧富不均、領土爭議；出生率下降與人口老化使勞動力與市場優勢消失","中國1979～2015年推行一胎化政策，導致幼年人口比例減少，未來有勞動力不足的隱憂"],"example":"引進外國資金技術、設經濟特區、皮爾・卡登到北京辦時裝秀→都是改革開放的關鍵字。"},{"heading":"冷戰與韓戰、越戰","points":["二戰結束後至1991年蘇聯解體，形成以蘇聯（共產）與美國（民主、反共）為首的兩大陣營對峙，非戰非和，稱為冷戰","二戰後東亞、東南亞多地脫離殖民獨立建國，美蘇為己身利益分別支持不同國家，形成東亞二元對立","東亞二元對立的影響：區域安全面臨挑戰，相關國家長期分裂，妨礙各國人民相互交流","冷戰陣營亞洲戰略：蘇聯與東亞共產政權建立緊密關係；美國以經濟、軍事協防西太平洋，建立亞太圍堵體系","美國在西太平洋與日本、南韓、中華民國、菲律賓等國簽約，建立島鏈防線，圍堵共產勢力","亞太圍堵體系：1951年美日簽《美日安保條約》、1954年與中華民國簽《中美共同防禦條約》，並創建東南亞公約組織","1951～1954年美國陸續簽美日安保、美菲、美紐澳、美韓（1953）、中美（1954）等協防條約","《美日安保條約》1951年簽訂、1960年強化：美軍駐日、日本提供基地，美國負防衛日本義務，日本成為美國國防最西邊前哨站","臺灣連結東北亞與東南亞，中國若控制臺灣將直接衝擊美日安保體系，故臺灣海峽安全與美國利益息息相關","1948年南、北韓分別建國，北韓為朝鮮民主主義人民共和國、南韓為大韓民國，以北緯38度線分界","韓戰（1950~1953年）：北韓在蘇聯支持下進攻南韓，以美國為首的聯合國部隊援南韓，中共「抗美援朝」援北韓","韓戰1953年簽停戰協定，劃停戰線，朝鮮半島以北緯38度附近分南北韓對峙至今","韓戰影響：刺激美國強化亞太地區反共圍堵體系，派第七艦隊協防臺灣海峽，並簽《中美共同防禦條約》","美國國會曾通過決議授權總統動用武力保護臺澎，擴大《中美共同防禦條約》範圍，但未解決臺海危機","韓戰後萬餘名中國戰俘不願遣返，依反共意願送往臺灣（反共義士），1954年1月23日定為自由日","韓戰傷亡慘重：美軍死亡約5.4萬人；1995年美國建韓戰紀念碑，碑文「自由是要付出代價的」","中國稱韓戰為「抗美援朝戰爭」，稱志願軍為「最可愛的人」，至今仍以韓戰作為愛國教育題材","朝鮮半島是東北亞勢力緩衝區，南北韓分裂對峙是美日同盟的重要依據，也是美國介入東北亞事務、防範北韓核武的理由","2024年10月北韓修憲放棄統一目標，稱南韓為「敵對國家」，兩韓關係持續惡化","越南自1884年清法戰爭後為法國占有；1954年脫離法國殖民統治，以北緯17度分為北越（共產）與南越（美國扶植）","北越國名越南民主共和國，南越為越南共和國；越戰導火線為北越共產黨向南擴張勢力","越戰（1955～1975年；翰林作1961～1975年）：1960年代美國正式出兵援南越；越戰期間蘇聯與中國分別援助北越","越戰中美軍使用落葉劑「橙劑」清除共軍藏身的叢林，因含致癌物質，嚴重損害越南民眾健康與生態，遺害至今","美國因國內反戰聲浪（反戰壓力）於1973年撤軍退出；1975年北越消滅南越、南越敗亡，越南統一成為共產國家，並向中南半島擴張","翰林年表將越戰爆發標為1961年（民國50年），越南統一為1976年（民國65年），與其他版本記法不同","越南人將越戰稱為「美國戰爭」，認為是美國擴張勢力；美國的記憶則著重共產敵人與國內反戰聲浪"],"example":"韓戰看「38度、聯合國首次反侵略、嚴寒多山」；越戰看「17度、熱帶叢林、法國殖民地、橙劑」。","fig":{"src":"../assets/fig/history/u10-s4.svg","cap":"冷戰時期的韓戰與越戰：南北分裂"}},{"heading":"中美蘇關係的轉變","points":["中蘇關係四階段：中蘇友好（一面倒）→中蘇交惡（大躍進、爭辯路線）→中美抗蘇（1979年建交）→中蘇緩解（正常往來）","中蘇友好（1950年代前期）：中共建國初期外交採「一邊倒」親蘇路線，接受蘇聯資金、技術援助協助建設，全面模仿蘇聯治國經驗","「一面倒」外交：主張不倒向帝國主義就倒向社會主義，沒有第三條道路，因而倒向蘇聯","中蘇交惡（1950年代晚期起）：理念分歧，蘇聯抨擊大躍進，中國認為蘇聯干預內政、試圖擺脫蘇聯控制，蘇聯停止援助","中蘇交惡時毛澤東稱赫魯雪夫為「現代修正主義」；赫魯雪夫曾嘲諷中國共產主義是「喝大鍋清水湯」","中蘇另有邊界領土糾紛，1969年因邊界領土爆發珍寶島事件","中美合作制蘇（1970年代起）：美國欲拉攏中共制衡蘇聯，中共也不願同時與美蘇交惡，毛澤東提出聯合美日對付蘇聯的「一條線」戰略","1972年美國總統尼克森訪中；1979年美國與中華人民共和國建交，與中華民國斷交並廢止《中美共同防禦條約》","美中建交公報：美國承認中華人民共和國為中國唯一合法政府，僅與臺灣人民維持文化、商務等非官方關係","1980年代鄧小平推行改革開放後改善與蘇聯關係、恢復正常往來，中蘇關係逐漸正常化；1989年戈巴契夫訪中","蘇聯解體後中俄合作密切，中美則轉為主要競爭對手；中美蘇三國關係仍左右東亞局勢","冷戰結束後，中華人民共和國取代蘇聯成為美國的潛在敵人，美國聯合日本、南韓及臺灣圍堵中國，並強化美日安保體制"],"example":"「打倒美帝！打倒蘇修！」的海報同時反美反蘇，代表1960年代中蘇已交惡、中美尚未和解。"},{"heading":"東南亞地區的國際組織","points":["東南亞公約組織（1955~1977年；翰林作1954年創建）：韓戰後美國為圍堵共產勢力成立的國際軍事聯盟","東約成員：美國聯合英、法、澳、紐、巴基斯坦、泰國、菲律賓；為亞太圍堵體系的一部分，由歐美主導","東約困境：東南亞區域內僅泰國、菲律賓參加，多數東南亞國家不願依附美蘇陣營、介入美蘇對抗","東約成員意見分歧、無統一指揮，於1977年解散","東南亞公約組織失敗原因之一：東南亞國家對歐洲殖民強國的敵意，與對共產主義的厭惡一樣強烈","東南亞國家協會（1967年迄今）：由印尼、馬來西亞、新加坡、菲律賓、泰國等非共產國家於曼谷發表宣言成立","東協目標轉變：冷戰時期著重政治協商、維護區域政治與社會穩定（維持東南亞秩序）；冷戰結束後注重經貿合作互惠","冷戰結束後東協強化區域整合：接納越南等共產背景國家、降低關稅、減少貿易限制，促進經貿","東協新增成員：汶萊、越南、寮國、緬甸、柬埔寨（共產背景者冷戰後陸續加入）、東帝汶（2025年）","東帝汶原為葡萄牙殖民地，1975年遭印尼占領，2002年脫離印尼獨立，2025年10月加入東協成為第11個成員國","東協對外擴大結盟：東協+3（中、日、韓）、RCEP（區域全面經濟夥伴協定）","2002年中國與東協簽《南海各方行為宣言》，不以武力處理爭議；中華民國未受邀參與、不承認該宣言","2016年海牙常設仲裁法院判決中國南海歷史權利主張違反《聯合國海洋法公約》，中國拒絕承認；2020年東協齊聲反對","2023年東協成員國首次在印尼舉行聯合軍事演習，因應氣候變遷與南海局勢，訓練人道救援、災難援助與海上巡邏","東南亞是臺灣重要出口市場，臺灣如何積極參與東南亞經濟整合架構、開拓國際經貿空間是重要課題"],"example":"東約＝美國主導的「反共軍事同盟」已解散；東協＝東南亞國家自己的「區域整合」存續至今。","fig":{"src":"../assets/fig/history/u10-s6.svg","cap":"東南亞國家協會（東協）的成員國"}}],"confusions":[{"a":"大躍進","b":"文化大革命","diff":"大躍進（1958年起）是追求農工產量的經濟運動；文化大革命（1966~1976年）是毛澤東奪權的政治鬥爭與批判傳統運動","tip":"超英趕美、人民公社、土法煉鋼、饑荒→大躍進；紅衛兵、破四舊、造反有理、毛語錄→文革"},{"a":"新文化運動","b":"文化大革命","diff":"兩者都批判儒家傳統，新文化運動（1915年起）由知識分子推動、引進西方思潮；文革由毛澤東發動、以紅衛兵鬥爭破壞文物","tip":"德先生、賽先生、白話文→新文化運動；紅衛兵、破四舊→文革"},{"a":"五四運動","b":"六四天安門事件","diff":"兩者都是北京學生在天安門集會，五四（1919年）針對巴黎和會山東問題、爭主權；六四（1989年）是改革開放後要求政治改革與民主","tip":"外爭主權、還我青島→五四；民主自由、軍隊鎮壓、經濟制裁→六四"},{"a":"六四天安門事件","b":"三月學運（野百合學運）","diff":"六四（1989年，北京）是改革開放後學生要求政治民主改革，遭中共軍事鎮壓；野百合（1990年，臺北）是學生在中正紀念堂靜坐，要求廢除《臨時條款》、解散國民大會，促成終止動員戡亂與國會全面改選","tip":"天安門、鄧小平、軍事鎮壓、經濟制裁→六四；中正紀念堂、李登輝、廢除臨時條款→野百合"},{"a":"韓戰","b":"越戰","diff":"韓戰（1950~1953年）停戰後南北韓對峙至今；越戰（1955~1975年；翰林作1961～1975年）北越統一全國成為共產國家","tip":"38度線、聯合國部隊、抗美援朝→韓戰；17度線、法國殖民、熱帶叢林、反戰撤軍→越戰"},{"a":"中蘇交惡","b":"中美合作制蘇","diff":"中蘇交惡始於1950年代晚期（1969年珍寶島衝突），中美合作則到1970年代才開始（1972年尼克森訪中、1979年建交）","tip":"同時反美反蘇→1960年代；聯美制蘇、一條線→1970年代"},{"a":"東南亞公約組織","b":"東南亞國家協會","diff":"東約是美國主導的反共軍事聯盟（1955年成立，翰林作1954年創建），1977年解散；東協是東南亞國家自組的區域整合組織，1967年成立至今","tip":"美國主導、軍事、圍堵共產→東約；印尼等創始、經貿合作、接納越南→東協"}],"terms":[{"term":"馬歇爾調停","def":"民國34年底美國派馬歇爾來華調停國共衝突，最終失敗，國共內戰全面爆發，美國隨後停止援助國民政府。"},{"term":"動員戡亂時期臨時條款","def":"民國37年因國共內戰轉趨激烈而頒布，凍結憲法對總統職權的限制、擴大總統權力，使憲政難以落實。"},{"term":"土地改革（中共）","def":"中共建政初期強制沒收地主土地分配給貧農以穩定經濟、爭取農民，其後又將全國土地收歸國有、實施集體耕作。"},{"term":"大躍進","def":"1958年起毛澤東發起的運動，以超英趕美為目標，推行人民公社與土法煉鋼，因浮誇虛報與技術不足導致大饑荒。"},{"term":"人民公社","def":"大躍進時期的農業組織，將約70萬個農業合作社整編為約2.4萬個公社；農民集體生活、集體生產，收穫公有共享、開辦公共食堂吃大鍋飯，導致生產意願低落。"},{"term":"土法煉鋼","def":"大躍進的工業措施，集結全國人力在空地興建土高爐煉鋼，因技術不成熟只煉出廢鐵，農田也因缺乏勞力而歉收。"},{"term":"文化大革命","def":"1966~1976年毛澤東為鞏固權力發動的運動，鼓動紅衛兵批鬥官員師長、破壞文物，造成社會動盪，被稱十年浩劫。"},{"term":"紅衛兵","def":"文化大革命期間由青年學生組成的團體，手持《毛語錄》、高喊「革命無罪，造反有理」，四處批鬥與破壞傳統文化。"},{"term":"破四舊，立四新","def":"文革口號，「破四舊」指破除中國傳統的思想、文化、風俗、習慣，「立四新」指樹立符合共產主義的新思想文化。"},{"term":"改革開放","def":"1978年起鄧小平推動的政策，對內改革、對外開放，逐步放寬經濟限制並在沿海設經濟特區，使中國經濟快速成長。"},{"term":"經濟特區","def":"改革開放時在沿海設立的特區，如深圳、珠海、汕頭、廈門、海南，給予優惠條件吸引外國資金與技術。"},{"term":"六四天安門事件","def":"1989年北京學生在天安門廣場集會要求政治改革與民主自由，6月4日遭中共派軍隊鎮壓，造成眾多傷亡。"},{"term":"吉尼係數","def":"評估所得分配均勻程度的指標，介於0～1，越大越不平均；聯合國以0.4為警戒值，可用來觀察改革開放後的貧富差距。"},{"term":"一胎化政策","def":"中國於1979～2015年推行的人口政策，限制每戶只生一胎，使幼年人口比例減少，造成人口老化與未來勞動力不足。"},{"term":"冷戰","def":"二戰後至1991年蘇聯解體，美國與蘇聯兩大陣營在軍備、科技等方面競爭對峙，但避免全面戰爭的非戰非和局面。"},{"term":"圍堵政策","def":"冷戰期間美國為限制共產勢力擴張，與盟邦簽約、提供軍經援助、設軍事基地並成立東南亞公約組織等軍事組織。"},{"term":"抗美援朝","def":"1950年韓戰爆發後，中共以此為名派遣志願軍援助北韓，對抗以美國為首的聯合國部隊，使中共與美國交惡。"},{"term":"珍寶島事件","def":"1969年中國與蘇聯因東北邊界珍寶島歸屬問題爆發軍事衝突，中蘇關係降至冰點，促成日後中美合作制蘇。"},{"term":"東南亞公約組織","def":"1955年（翰林作1954年創建）美國為防堵共產勢力在東南亞擴張而主導成立的軍事聯盟，成員8國，東南亞僅泰、菲，1977年解散。"},{"term":"東南亞國家協會","def":"1967年由印尼等非共產國家成立的區域組織，冷戰時維護區域穩定，冷戰後強化經貿整合，現有11個成員國。"},{"term":"RCEP","def":"區域全面經濟夥伴協定，2022年生效，由東協與中國、日本、南韓、澳洲、紐西蘭組成，建立廣泛的區域自由貿易。"}],"timeline":[{"time":"1945","event":"日本投降，國共因接收問題爆發衝突；年底美國派馬歇爾來華調停"},{"time":"1947（民國36年）","event":"頒布並實施《中華民國憲法》"},{"time":"1948（民國37年）","event":"頒布《動員戡亂時期臨時條款》；蔣中正當選行憲後第一任總統，國民政府改組為中華民國政府"},{"time":"1948","event":"南、北韓分別建國，以北緯38度線分界"},{"time":"1949","event":"10月1日中華人民共和國成立；年底中華民國政府遷臺"},{"time":"1950~1953","event":"韓戰：中共抗美援朝，1953年簽停戰協定，南北韓對峙至今"},{"time":"1951","event":"美國與日本簽訂《美日安保條約》，建構亞太圍堵體系"},{"time":"1954","event":"1月23日韓戰反共戰俘來臺，定為自由日"},{"time":"1954","event":"越南脫離法國殖民，以北緯17度分為南北越；簽《中美共同防禦條約》"},{"time":"1955","event":"東南亞公約組織成立（翰林作1954年創建）"},{"time":"1955~1975","event":"越戰（翰林作1961～1975年）"},{"time":"1958","event":"毛澤東發起大躍進，推行人民公社與土法煉鋼"},{"time":"1966~1976","event":"文化大革命，紅衛兵破四舊"},{"time":"1967","event":"東南亞國家協會成立"},{"time":"1969","event":"中蘇因邊界問題爆發珍寶島事件"},{"time":"1972","event":"美國總統尼克森訪問中國"},{"time":"1973","event":"美軍撤離越南"},{"time":"1975","event":"北越消滅南越，越南統一成為共產國家"},{"time":"1976","event":"北越統一全國，成立共產政權的越南（翰林記法）"},{"time":"1977","event":"東南亞公約組織解散"},{"time":"1978","event":"鄧小平推動改革開放，設經濟特區"},{"time":"1979","event":"美國與中華人民共和國建交"},{"time":"1981","event":"中國共產黨決議徹底否定文化大革命"},{"time":"1989","event":"六四天安門事件；戈巴契夫訪問中國"},{"time":"1991","event":"蘇聯解體，冷戰結束"},{"time":"1997、1999","event":"香港、澳門分別回歸中國"},{"time":"2002","event":"中國與東協會員國簽署《南海各方行為宣言》"},{"time":"2008","event":"中國主辦北京奧運"},{"time":"2016","event":"海牙常設仲裁法院判決中國南海歷史權利主張違反國際法"}],"sources":[{"name":"邱吉爾鐵幕演說","gist":"1946年邱吉爾指出鐵幕已降落歐洲，東歐都處在蘇聯勢力範圍內。","clue":"鐵幕、蘇聯勢力範圍、1946年→冷戰形成"},{"name":"梅瑞迪斯．勝利號興南撤退（1950）","gist":"美籍貨輪於1950年12月自北韓興南港撤出約14,000名難民，創單艘船救援最多生命的紀錄。","clue":"1950年、北韓難民撤往南方、中國出兵→韓戰"},{"name":"《中國人民志願軍戰歌》","gist":"1950年冬創作，歌詞「雄赳赳，氣昂昂，跨過鴨綠江，保和平衛祖國」，為志願軍出兵朝鮮的誓言。","clue":"跨過鴨綠江、志願軍、1950年、最可愛的人→韓戰抗美援朝"},{"name":"韓戰紀念碑文與宣傳海報","gist":"碑文稱此戰為聯合國首次反抗侵略的行動，敵人是共軍，地勢多山、氣候嚴寒。","clue":"聯合國部隊、抗美援朝、大韓民國、停戰線、38度線、1950年代"},{"name":"《美日安保條約》","gist":"1951年簽訂、1960年強化，美軍駐日，日本提供基地、美國負防衛日本義務，日本受攻擊視為對美國的危害。","clue":"美軍駐日、提供基地與防衛義務、韓戰後、圍堵共產→冷戰時期美國亞太圍堵體系"},{"name":"自由日紀念徽章（1954.1.23）","gist":"印有南韓與中華民國國旗及「自由」，紀念韓戰萬餘名中國戰俘依反共意願送往臺灣。","clue":"JAN.23.1954、反共戰俘、韓戰後→冷戰圍堵體系"},{"name":"越南反共海報「哪裡有共產主義，哪裡就有恐怖主義」","gist":"海報以鐮刀錘子、毒蛇與骷髏表現共產主義帶來恐怖，為南北越分裂後的反共宣傳。","clue":"反共、越南、鐮刀錘子→1954年南北越分裂後、越戰時期"},{"name":"大躍進宣傳海報與老農回憶（含「人有多大膽，地有多大產」）","gist":"海報誇耀鋼產量、比人還大的南瓜，工農手持紅書高舉歡呼，宣揚敢想敢做土地產量就能無限提高；老農回憶人人把鍋鏟丟進煉鐵爐以求超英趕美。","clue":"人有多大膽地有多大產、超英趕美、煉鋼、人民公社、吃大鍋飯、浮誇產量、1958年、饑荒死亡率上升"},{"name":"菲律賓SEATO五週年紀念郵票首日封（1959）","gist":"首日封印有東南亞公約組織會旗與成員國旗，紀念1955～1959年SEATO成立五週年。","clue":"SEATO、會員國旗（美英法澳紐巴泰菲）、1955年→美國主導圍堵共產勢力"},{"name":"北越海報「把美國侵略者從越南南方趕出去！」","gist":"越南士兵持槍埋伏叢林，號召驅逐援助南越的美軍。","clue":"美國侵略者、越南南方、叢林游擊→北越立場、越戰"},{"name":"文化大革命相關回憶與報導","gist":"孔子墓碑被砸碎、紅衛兵貼大字報、學生領袖批鬥師長後道歉、芒果崇拜。","clue":"革命無罪造反有理、破四舊、紅衛兵、毛語錄、批鬥、上山下鄉、1966~1976年"},{"name":"《台灣民聲日報》文革報導（1967年）","gist":"報導上海反毛工人罷工、廣州工人與紅衛兵戰鬥，反映文革時期社會動盪。","clue":"民國56年、紅衛兵、反毛林→文化大革命"},{"name":"《解放軍報》反蘇修報導","gist":"報紙標題高喊打倒蘇修社會帝國主義，聲討蘇聯侵犯中國領土。","clue":"蘇修、新沙皇、侵犯領土→1960年代中蘇交惡、珍寶島事件"},{"name":"改革開放相關談話","gist":"中共領導人主張引進發達國家的資金和技術，在深圳、廣東等地殺出一條血路。","clue":"引進外資技術、經濟特區、深圳、鄧小平、四個現代化、放寬經濟控制"}]},{"unit":11,"part":"世界史","title":"古代文化的遺產","summary":"認識兩河、埃及、希臘、羅馬等古文明的政治與文化成就，以及佛教、基督教、伊斯蘭教的起源與傳播；會考常以史料關鍵字（文字、宗教、地名、世紀）判斷文明、時代與地圖位置。","sections":[{"heading":"西亞古文明","points":["西亞範圍含兩河流域（美索不達米亞）、小亞細亞、地中海東岸、伊朗高原，位於歐亞非交界","兩河流域指幼發拉底河與底格里斯河間的沖積平原，稱美索不達米亞，形似新月又稱「肥沃月彎」","兩河流域地形平坦、缺乏屏障，易受外族入侵；往來民族多、商業繁盛，重視契約與法律","西亞與埃及比較：兩河流域地形平坦缺乏屏障、河流不定期氾濫；埃及地形封閉具天然屏障、尼羅河定期氾濫","蘇美人最早在兩河流域建立城邦（約前3500年），發明楔形文字、制定陰曆、發明六十進位法","《吉爾伽美什史詩》以楔形文字寫於泥板，講述烏魯克城邦國王的故事，是已知最早的英雄史詩，含大洪水故事","《聖經》與希臘神話多取材兩河流域神話（蘇美天堂神話、大洪水神話、巴比倫創世神話），可見其對西方影響深遠","巴比倫的漢摩拉比國王制定《漢摩拉比法典》，強調「以牙還牙，以眼還眼」的報復原則，刑罰依身分而有差別","腓尼基人居地中海東岸，擅長航海、經商，將古埃及文字改良為表音符號並傳入歐洲，成為西方拼音文字的基礎","歐洲字母演變：埃及文→腓尼基文→希臘文→拉丁文","希伯來人（猶太人）居巴勒斯坦，前10世紀建立統一王國，後分裂為南北兩國，先後被亞述帝國、新巴比倫帝國所滅","希伯來人創立猶太教，以耶和華為唯一真神、《舊約聖經》為經典，一神信仰影響基督教與伊斯蘭教","希伯來人相信自己是「上帝的選民」，巴勒斯坦是上帝賜給他們的「應許之地」","猶太人以巴勒斯坦地區的耶路撒冷為聖城，聖殿所在的聖山為敬拜耶和華之地","波斯人興起於伊朗高原，前6世紀建立歷史上第一個橫跨歐、亞、非三洲的波斯帝國，信奉祆教（崇拜光明與火、善惡二元論）","波斯帝國首都波斯波利斯位於伊朗高原；祆教於唐代隨胡人傳入長安，以聖火祭祀為特色","波斯帝國在波希戰爭中未能成功征服希臘，前4世紀亡於亞歷山大東征"],"example":"看到「泥板、幼發拉底河、巴比倫」→楔形文字；看到「崇拜火、善神終將戰勝惡神」→伊朗高原的祆教。","fig":{"src":"../assets/fig/history/u11-s1.svg","cap":"西亞古文明：肥沃月彎"}},{"heading":"埃及古文明","points":["位於北非，尼羅河每年定期氾濫帶來水源與肥沃淤泥，被埃及人視為生命的源頭，史家稱「埃及是尼羅河的贈禮」","四周沙漠與高山屏障使外敵難入侵、政治穩定","約前3100年出現統一王國，國王稱「法老」，以太陽神之子身分統治，王權強大得以興建金字塔","古埃及歷史分為古王國→中王國→新王國三階段，新王國時期版圖最遼闊","金字塔是法老的陵墓，以吉薩金字塔最著名","古埃及人依尼羅河漲水、退水、收穫安排年度行事；漲水季農民無法耕作，投入修建金字塔以獲得食物","多神信仰，主要信仰太陽神（宇宙主宰，法老即太陽神之子）與尼羅河神（代表循環不息的再生力量）","相信死後審判、通過者可復活，因此將遺體製成木乃伊，也帶動醫學（解剖）知識","前14世紀埃及法老阿肯那頓曾放棄傳統多神信仰，改崇拜唯一主神，但死後新宗教體制即被推翻","發明象形文字，由圖像與表音符號構成，寫在紙草製成的紙面","為預測尼羅河氾濫制定太陽曆（365天），並因丈量土地發展數學、幾何","前6世紀亡於波斯，之後先後受亞歷山大帝國（希臘文）、羅馬與拜占庭（拉丁文、基督教）、阿拉伯帝國（阿拉伯文、伊斯蘭教）統治"],"example":"埃及官方文字順序口訣：希臘文→拉丁文→阿拉伯文（亞歷山大→羅馬→阿拉伯）。"},{"heading":"希臘古典文明","points":["世界古代史可分為上古（前3500～前500年）與古典（前500年～西元500年）兩個時期","西元前2000年愛琴海地區文明（愛琴文明）是希臘古典文化的源頭","1900年英國考古學家亞瑟埃文斯在克里特島發現克諾斯遺址（米諾斯王宮），證實愛琴文明（克里特文明）存在","希臘半島地形崎嶇，前8世紀形成許多獨立城邦，代表為雅典與斯巴達","雅典：男性公民可參政，以抽籤選官、陶片流放制放逐危害城邦者，被視為民主政治起源；女性與奴隸無公民資格","斯巴達：男性公民自幼接受嚴格軍事訓練，軍事統治、武力強大","前5世紀波希戰爭，雅典領導各邦擊退波斯；雅典擊敗波斯後開啟黃金時代","波希戰爭後，雅典聯合小亞細亞等城邦組成對抗波斯的防禦同盟（提洛同盟），實際由雅典操控","雅典組提洛同盟、斯巴達領伯羅奔尼薩同盟相互爭霸（內戰），雅典與斯巴達爭霸兩敗俱傷；之後底比斯短暫稱霸","雅典與斯巴達爭霸內戰、兩敗俱傷，北方馬其頓王國趁勢崛起，最終全希臘遭馬其頓征服","文化：多神信仰、每4年奧林匹亞祭典為奧運起源；希臘三哲為蘇格拉底、柏拉圖、亞里斯多德","古希臘文化重視人的尊嚴與價值；哲學著重探討倫理道德與人生意義","柏拉圖主張品德教育重心為智慧、勇敢、節制、正義，國家目的在培養賢治者","《荷馬史詩》含〈伊里亞德〉與〈奧德賽〉，融合英雄事蹟與希臘早期歷史（特洛伊戰爭），為西方文藝創作靈感來源","希羅多德著《歷史》，以波希戰爭為題材、重視求真，有「史學之父」稱號","藝術重視均衡、對稱、和諧；古希臘雕刻崇尚人體的力與美","帕德嫩神廟建於前5世紀，5世紀改為基督教聚會所、15世紀改為清真寺","19世紀初額爾金伯爵運走帕德嫩神廟雕像，現藏大英博物館，希臘要求歸還"],"example":"「公民、抽籤、放逐對城邦有危害的人」三個關鍵字一出現，答案就是雅典民主。"},{"heading":"亞歷山大帝國與希臘化文化","points":["前4世紀馬其頓王國統一希臘各城邦；亞歷山大繼承父親腓力二世為馬其頓國王後東征","亞歷山大擊敗波斯大流士三世，征服埃及、西亞、波斯，最遠抵達印度河流域，兼有埃及法老、亞洲之王等頭銜","建立橫跨歐亞非三洲的帝國；亞歷山大在各地建立希臘式城市（多名為亞歷山卓）、推行希臘語言文字，並鼓勵民族通婚","東征後希臘文化與西亞、埃及文化融合，形成「希臘化文化」，希臘語成為通用語（柯因奈語）","希臘化文化始於前4世紀亞歷山大東征，約延續300年（翰林作至前2世紀希臘遭羅馬（共和時期）攻陷而結束）","希臘化文化保存了傳遞希臘人的成就；科學成就最突出，如歐幾里德《幾何原本》、阿基米德的浮體力學與槓桿原理","亞歷山大死後，希臘人在埃及建立托勒密王朝，融合希臘與埃及文化（君主被視為神），後被羅馬納入版圖","東征帶來西方寫實雕塑方法，影響犍陀羅佛教藝術","橫跨三洲大帝國年代與信仰：波斯（前6～前4世紀，祆教）、亞歷山大（前4世紀，希臘多神）、羅馬（前1～4世紀，羅馬多神）","融合比較：亞歷山大（前4世紀）建希臘式城市、推行希臘語文、鼓勵通婚→希臘化；北魏孝文帝（5世紀）說漢語、改漢姓、穿漢服、鼓勵通婚→漢化"],"example":"前4世紀、希臘語傳到埃及與西亞（如《七十士譯本》、塞拉比斯信仰）→都是亞歷山大東征的影響；佛像出現深目高鼻、衣褶深的希臘風格（犍陀羅）也是。","fig":{"src":"../assets/fig/history/u11-s4.svg","cap":"亞歷山大東征與帝國範圍"}},{"heading":"羅馬的政治與文化","points":["前8世紀拉丁人在義大利半島臺伯河畔建羅馬城（傳說前753年），進入王政時期","前6世紀（前509年）推翻王權進入共和：元老院決議、執政官執行","羅馬共和被視為混合政體：元老院代表貴族、執政官代表王政、公民大會代表民主，三者彼此制衡","SPQR意為「元老院與羅馬公民」，為古羅馬政權官方名稱，常見於公共建築；20世紀墨索里尼借用以連結羅馬","羅馬共和與腓尼基人建立的迦太基爆發三次戰爭爭奪地中海霸權，迦太基將領漢尼拔曾越阿爾卑斯山進攻羅馬","共和時期版圖擴張橫跨三洲，地中海成為內海；晚期內戰，軍事將領如凱撒、屋大維掌握政權","前27年屋大維集權稱帝，獲「奧古斯都」尊號，集行政、立法、司法、宗教大權於一身","屋大維開啟「羅馬和平」（前27年～180年），與中國漢朝遙相輝映","帝國時期疆域西北達不列顛群島、高盧，最北達不列顛群島","羅馬帝國與漢朝東西輝映：羅馬主要外患為日耳曼人、漢朝為匈奴；漢朝絲綢經絲路最遠輸往羅馬帝國（中國稱大秦）","3世紀羅馬危機：皇帝失去軍隊控制、停止擴張致財政困難、帝位動盪，邊疆遭日耳曼人與波斯薩珊王朝掠奪","帝國後期政經惡化（政治腐敗、經濟惡化）、日耳曼人（日耳曼民族）入侵，國勢漸衰","3世紀皇帝戴克里先因疆域遼闊，將國家分為兩部分交由兩位皇帝治理，但未能解決紛爭","君士坦丁在東方建新都君士坦丁堡（拜占庭）；395年羅馬帝國分裂為東西兩部","君士坦丁堡在鄂圖曼帝國時改稱伊斯坦堡，同一城市不同時期名稱不同","狄奧多西是最後一位統治環地中海全境的羅馬君王，395年死後由兩子分任東、西部皇帝，帝國正式分裂為東西兩部","西羅馬476年亡於日耳曼人；東羅馬（拜占庭帝國）1453年亡於鄂圖曼土耳其人","拜占庭皇帝查士丁尼致力收復古羅馬疆域、建聖索菲亞大教堂，是拜占庭帝國的黃金時代；帝國以基督教為國教、政教合一","查士丁尼向西擊敗汪達爾人取得北非沿岸、征服東哥德人奪回義大利半島；軍隊移動使鼠疫擴散，稱「查士丁尼瘟疫」","共和時期制定最早成文法《十二表法》；羅馬法律含「無罪推定」概念，成為歐洲各國制訂法律的參考來源","拉丁文成為中世紀西歐通用文字；羅馬人重視實用與公共生活，城市街道整齊，興建競技場、引水道、公共澡堂","塔西佗以拉丁文著《歷史》《編年史》記述帝國初期歷史，嚮往共和、反對皇帝專斷，被稱為「暴君的鞭子」"],"example":"題目出現「元老院、拉丁文、疆域含今英國與埃及」→羅馬；「君士坦丁堡/伊斯坦堡、1453」→拜占庭滅亡。","fig":{"src":"../assets/fig/history/u11-s5.svg","cap":"羅馬帝國的版圖與東西分裂"}},{"heading":"佛教的起源與發展","points":["前1500年信奉婆羅門教的阿利安人入侵印度，婆羅門教主張因果報應、靈魂輪迴","阿利安人為保持血統建立種姓制度：婆羅門、剎帝利、吠舍、首陀羅，身分職業世襲、互不通婚","前6世紀釋迦牟尼創立佛教，主張眾生平等，人可藉修行超脫輪迴，打破婆羅門教階級觀","前3世紀阿育王宣揚佛教而全盛；阿育王整理佛教基本教義與戒律，並派遣高僧向外弘法，使佛教向外傳播","佛教向外傳播：北傳中國、朝鮮、日本，南傳中南半島、南洋群島","阿育王死後佛教在印度式微；新興的印度教融合佛教、婆羅門教等信仰，至今是印度信仰人口最多的宗教","印度宗教比較：婆羅門教（阿利安人，階級觀念）、佛教（釋迦牟尼，眾生平等）、印度教（階級觀念，融合婆羅門教與佛教），三者都有因果輪迴觀念","佛教早期認為「法本無相」，不造佛像，以法輪、足印、菩提樹、佛塔象徵佛陀，至貴霜王朝才出現最初的佛像","犍陀羅佛像融合希臘寫實雕塑，具印度希臘化風格（身材高大、衣褶深、深目高鼻），隨絲路東傳中亞、中國","犍陀羅地區佛教於5世紀遭嚈噠入侵摧毀而衰"],"example":"柬埔寨、泰國、緬甸、斯里蘭卡多信佛教，但發源地是印度，別被信徒分布騙了。"},{"heading":"基督教的起源與發展","points":["1世紀羅馬帝國境內的巴勒斯坦，耶穌批判猶太社會腐敗，宣傳平等、博愛","耶穌主張不合猶太教教義，遭部分猶太教徒向羅馬官員控告，被釘死在十字架上；十字架成為基督教象徵，「基督」意為救世主","一神信仰（耶和華），經典《聖經》（舊約＋新約）：《舊約》原為猶太教經典，《新約》記載耶穌言行，兩者合為基督教的《聖經》","初期教徒拒拜皇帝像而遭羅馬迫害（被視為反抗帝國），但積極傳教反而吸引更多信徒、廣泛流傳","4世紀初君士坦丁承認基督教合法，是第一個信仰基督教的羅馬君王","4世紀末狄奧多西定基督教為羅馬國教，傳統多神信仰被視為異端","中世紀始於476年西羅馬帝國滅亡，至15世紀；西歐政治混亂、經濟回歸自給自足，商業幾乎停頓","中世紀西歐教會為生活與學術中心，教士抄寫拉丁文古籍保存古典文化；教會附設學校，成為重要教育機構，內容以服務宗教為主","教會負起維護社會秩序的任務；人們出生受洗、婚喪儀式都由教會主持","西歐君主管政治、羅馬教會管宗教屬「政教分離」，但教會影響力大、權力有時凌駕君主，以致發生政教衝突；東歐拜占庭則政教合一","1054年（11世紀）基督教第一次分裂，起因：以君士坦丁堡為中心的教會和羅馬教會爭奪基督教世界領導權","分裂為羅馬公教（天主教，教宗、西歐）與希臘正教（東正教，拜占庭皇帝、東歐與俄羅斯）","1054年分裂時，羅馬教皇與君士坦丁堡牧首相互開除對方教籍，爭議之一為聖餐使用發酵餅或無酵餅","十字軍背景：千禧年末日傳說、聖地遭破壞與朝聖者遇害；教宗宣稱參戰可贖罪、陣亡可升天堂","十字軍受義大利商人左右，曾攻打基督教城市並洗劫拜占庭帝國，使東西教派關係破裂","十字軍中義大利商人獲最大利益，日後成為文藝復興的贊助者"],"example":"判斷時間：1世紀受迫害→4世紀初合法→4世紀末國教→11世紀分裂。"},{"heading":"伊斯蘭教的起源與發展","points":["阿拉伯半島多沙漠，居民以游牧或經營駱駝商隊為主","7世紀麥加商人穆罕默德受猶太教與基督教一神信仰啟發，在阿拉伯半島創立伊斯蘭教","伊斯蘭教信奉唯一真神阿拉，以《古蘭經》為經典，阿拉伯語成為通用語","伊斯蘭教主張平等，廣受底層民眾歡迎；各地穆斯林背誦經典、分享共同生活準則與語言，使伊斯蘭教成為普世宗教","朝覲是穆斯林在經濟與身體條件允許下一生至少一次的義務，於伊斯蘭曆12月8～12日在麥加舉行","伊斯蘭曆為觀測月相的陰曆，一年12個月、無閏月，30年間設11個閏年，因此節日可能落在四季任何時段","麥加、耶路撒冷為伊斯蘭教聖地，麥加為穆斯林朝覲所在","耶路撒冷舊城區：基督教（耶穌祈禱、死亡與復活之地）、伊斯蘭教（先知升天與真主對話之地）、猶太教（第一座聖殿所在），三教共同聖地","8世紀阿拉伯帝國擴張為橫跨三洲的帝國，東至中亞（怛羅斯之役），西抵伊比利半島，形成伊斯蘭世界","阿拉伯帝國首都巴格達為商貿與文化中心（商業、政治及學術中心）；學者翻譯古希臘羅馬典籍，傳回歐洲有助文藝復興","阿拉伯商人以巴格達為中心溝通東西貿易，傳播造紙術、印度數字，並將支票等商業制度及中國的指南針傳到各地","11世紀塞爾柱土耳其人（塞爾柱帝國）攻陷耶路撒冷、阻撓基督徒朝聖，教宗多次號召十字軍，引發與基督教世界長期衝突","十字軍未成功，加深雙方衝突，卻促進貿易與文化交流","12世紀末（1187年）阿尤布王朝的薩拉丁擊敗十字軍、奪回耶路撒冷，加深雙方對立，並促成之後規模更大的十字軍遠征","13世紀初十字軍攻入拜占庭領土建立拉丁帝國；13世紀巴格達遭蒙古攻陷","鄂圖曼帝國13世紀末崛起；14世紀起占領巴爾幹，沿襲拜占庭的政治文化與貨幣體系","1453年鄂圖曼帝國攻滅拜占庭帝國，建立橫跨三洲、以巴爾幹半島為歐洲領土的帝國，至20世紀才衰亡","聖索菲亞大教堂為6世紀中期查士丁尼所建；15世紀中期鄂圖曼蘇丹穆罕默德二世攻占後增設尖塔，改為清真寺","16世紀中期鄂圖曼帝國控制葉門，將咖啡引入土耳其，首都伊斯坦堡出現公共咖啡館","三洲大帝國：拜占庭（4～15世紀，基督教→東正教）、阿拉伯（7～13世紀，伊斯蘭教，未拿下拜占庭）、鄂圖曼（13～20世紀，伊斯蘭教）"],"example":"耶路撒冷是猶太教、基督教、伊斯蘭教三教共同聖地，至今仍是衝突焦點。","fig":{"src":"../assets/fig/history/u11-s8.svg","cap":"伊斯蘭教的擴張：8 世紀阿拉伯帝國的範圍"}}],"confusions":[{"a":"楔形文字","b":"象形文字","diff":"楔形文字是蘇美人發明、刻在泥板、通行兩河流域；象形文字是古埃及的圖像＋表音符號文字，寫在紙草上","tip":"泥板、巴比倫→楔形；尼羅河、法老、紙草→象形"},{"a":"陰曆（兩河流域蘇美）、太陽曆／陽曆（埃及）","b":"陰陽合曆（商代）","diff":"蘇美依月亮週期制定陰曆（配楔形文字）；埃及觀察天狼星、依太陽週期制定365天的太陽曆以預測尼羅河氾濫（配象形文字）；商代為甲骨文＋陰陽合曆","tip":"月亮→蘇美；天狼星、365天、尼羅河氾濫→埃及太陽曆；甲骨→陰陽合曆"},{"a":"希臘古典時期","b":"希臘化時代","diff":"古典時期是城邦林立（雅典民主、斯巴達軍事）；希臘化時代是亞歷山大東征後希臘與西亞、埃及文化融合","tip":"城邦、抽籤→古典；前4世紀以後、埃及西亞講希臘語→希臘化"},{"a":"亞歷山大的希臘化政策","b":"北魏孝文帝的漢化政策","diff":"亞歷山大於前4世紀建希臘式城市、推行希臘語文、鼓勵通婚，使希臘文化傳入西亞、埃及；孝文帝於5世紀令鮮卑人說漢語、改漢姓、穿漢服、與漢人通婚","tip":"都鼓勵通婚；希臘語文→亞歷山大，改漢姓→孝文帝"},{"a":"西羅馬帝國","b":"東羅馬帝國","diff":"西羅馬：首都羅馬、拉丁文、疆域歐非、基督教，476年亡於日耳曼民族；東羅馬：首都君士坦丁堡、希臘文、疆域歐亞非、基督教→希臘正教，1453年亡於鄂圖曼帝國","tip":"拉丁文、476→西；希臘文、1453→東"},{"a":"婆羅門教","b":"印度教","diff":"婆羅門教為阿利安人所創，以階級觀念維護其統治地位；印度教在佛教衰落後興起，融合婆羅門教、佛教等信仰，仍保有階級觀念，至今為印度最多人信仰的宗教","tip":"阿利安人、前1500年→婆羅門教；融合佛教、今日印度最大宗教→印度教；兩者與佛教都相信因果輪迴"},{"a":"君士坦丁","b":"狄奧多西","diff":"君士坦丁於4世紀初承認基督教合法並建新都；狄奧多西於4世紀末定基督教為國教","tip":"合法＝君士坦丁；國教＝狄奧多西"},{"a":"羅馬公教（天主教）","b":"希臘正教（東正教）","diff":"1054年分裂：公教以羅馬為中心、教宗領導、政教分離、傳播西歐；正教以君士坦丁堡為中心、皇帝兼宗教領袖、傳播東歐與俄羅斯","tip":"教宗→公教；拜占庭皇帝、斯拉夫→正教"},{"a":"阿拉伯帝國","b":"鄂圖曼帝國","diff":"阿拉伯帝國7～8世紀擴張、占伊比利半島、首都巴格達；鄂圖曼帝國13世紀末興起、1453年滅拜占庭、歐洲領土在巴爾幹半島","tip":"8世紀、伊比利半島→阿拉伯；15世紀、君士坦丁堡→鄂圖曼"}],"terms":[{"term":"楔形文字","def":"蘇美人所發明，以蘆葦筆刻寫在泥板上的文字，通行於兩河流域，是西亞文明的共同遺產。"},{"term":"漢摩拉比法典","def":"巴比倫國王漢摩拉比制定的法典，以楔形文字寫成，強調「以牙還牙」報復原則，刑罰因身分而異。"},{"term":"猶太教","def":"希伯來人創立的一神信仰，以耶和華為唯一真神、《舊約聖經》為經典，自認為上帝選民，影響基督教與伊斯蘭教。"},{"term":"祆教","def":"波斯人信奉、發源於伊朗高原的宗教，崇拜光明與火，主張善惡二元論，相信善神終將戰勝惡神。"},{"term":"腓尼基人","def":"居地中海東岸的民族，擅長航海經商，改良古埃及文字傳入歐洲，為希臘、拉丁字母等西方拼音文字的基礎。"},{"term":"肥沃月彎","def":"兩河流域到地中海東岸一帶土壤肥沃、形狀像一彎新月的地區，為西亞古文明的發源地。"},{"term":"吉爾伽美什史詩","def":"以楔形文字刻寫於泥板的兩河流域英雄史詩，講述烏魯克國王事蹟，含大洪水故事，為已知最早英雄史詩。"},{"term":"法老","def":"古埃及國王的稱號，以太陽神之子身分統治人間，同時掌握政權與神權，能動員人力興建金字塔。"},{"term":"木乃伊","def":"古埃及人相信人死後通過審判即可復活，因此將遺體製成木乃伊以備復活使用，也促進醫學知識發展。"},{"term":"紙草","def":"古埃及以尼羅河畔植物製成的書寫材料，象形文字即書寫於紙草製成的紙面上。"},{"term":"城邦","def":"古希臘因地形崎嶇而形成的獨立小國，自前8世紀出現，以雅典（民主）與斯巴達（軍事）為代表。"},{"term":"陶片流放制","def":"雅典公民以投票方式決定是否放逐可能危害城邦的人，為雅典民主政治的特色之一。"},{"term":"荷馬史詩","def":"古希臘史詩，含〈伊里亞德〉與〈奧德賽〉，融合神話、英雄事蹟與特洛伊戰爭等早期歷史，為西方文藝的靈感來源。"},{"term":"希羅多德","def":"古希臘史家，著《歷史》一書，以波希戰爭為題材並重視求真，被稱為「史學之父」。"},{"term":"愛琴文明","def":"約西元前2000年出現在愛琴海地區（如克里特島）的文明，為希臘古典文化的源頭與先驅。"},{"term":"修昔底德陷阱","def":"源自雅典史家修昔底德，指新興強國威脅現有強國地位時易引發戰爭，如雅典崛起引發斯巴達恐懼。"},{"term":"希臘化文化","def":"亞歷山大東征後約300年間，希臘文化與西亞、埃及文化融合形成的文化，科學成就最突出。"},{"term":"托勒密王朝","def":"亞歷山大死後由希臘人在埃及建立的王朝，融合希臘與埃及文化，後被羅馬納入版圖。"},{"term":"幾何原本","def":"希臘化時期歐幾里德整合古希臘數學成就的著作，是希臘化文化的重要科學成就與後世幾何學教材。"},{"term":"元老院","def":"羅馬共和時期掌權的貴族機構，決議國家重要政務後交付執政官執行，帝國時期仍存在。"},{"term":"十二表法","def":"羅馬共和時期制定的最早成文法，後由城邦習慣法發展為萬民法，被視為成文法的始祖。"},{"term":"羅馬和平","def":"屋大維結束內戰、集權稱帝後，羅馬帝國約兩百年（前27年～180年）的安定繁榮時期。"},{"term":"拜占庭帝國","def":"即東羅馬帝國，以君士坦丁堡為首都，以基督教為國教、政教合一，1453年亡於鄂圖曼土耳其人。"},{"term":"執政官","def":"羅馬共和時期的最高行政首長，每年選出兩名，執行元老院決議的重要事務。"},{"term":"大秦","def":"中國史書對羅馬帝國的稱呼；漢朝的絲綢經由絲路輸出，最遠到達大秦。"},{"term":"奧古斯都","def":"前27年元老院獻給屋大維的尊號，集行政、立法、司法、宗教大權，此後成為羅馬皇帝的頭銜。"},{"term":"塔西佗","def":"古羅馬史家，以拉丁文著《歷史》《編年史》，嚮往共和、批判皇帝專斷，有「暴君的鞭子」之稱。"},{"term":"SPQR","def":"拉丁文「元老院與羅馬公民」的縮寫，為古羅馬政權的官方名稱，常刻於羅馬公共建築上。"},{"term":"迦太基","def":"西元前7世紀腓尼基人在北非沿岸建立的國家，繼承地中海貿易，後與羅馬共和爆發三次戰爭。"},{"term":"種姓制度","def":"阿利安人為保持血統而建立的階級制度，分婆羅門、剎帝利、吠舍、首陀羅，身分職業世襲、互不通婚。"},{"term":"阿育王","def":"前3世紀印度孔雀王朝的統治者，大力宣揚佛教，使佛教在印度廣泛傳布、進入全盛時期。"},{"term":"犍陀羅藝術","def":"今巴基斯坦西北、阿富汗東部一帶融合希臘寫實雕塑與佛教的造像風格，佛像深目高鼻、衣褶深，隨絲路東傳。"},{"term":"貴霜王朝","def":"月氏人在中亞、南亞建立的政權，2、3世紀鼎盛，以犍陀羅為都，推崇佛教並出現最初的佛像。"},{"term":"印度教","def":"佛教在印度式微後興起的宗教，融合婆羅門教、佛教等信仰，保有階級觀念，至今為印度信仰人口最多的宗教。"},{"term":"中世紀","def":"476年西羅馬帝國滅亡至15世紀的歐洲時期，西歐政治混亂、經濟自給自足，教會為生活中心。"},{"term":"十字軍","def":"11世紀末起教宗號召基督徒組成的軍隊，意圖奪回聖地耶路撒冷；多次東征未成功，卻促進東西貿易與文化交流。"},{"term":"破門律","def":"中世紀羅馬教會最嚴厲的宗教懲罰，即開除教籍；教宗曾以此懲罰攻打基督教城市的十字軍。"},{"term":"禧年","def":"又稱聖年，天主教重要傳統，源自希伯來人習俗；1300年教宗設立，信徒可赴羅馬朝聖與告解獲得罪罰寬免。"},{"term":"古蘭經","def":"伊斯蘭教經典，信徒相信為阿拉的話語，須以阿拉伯文背誦，使阿拉伯語成為伊斯蘭世界的通用語。"},{"term":"耶路撒冷","def":"位於地中海東岸，為猶太教、基督教、伊斯蘭教共同聖地，11世紀末被塞爾柱土耳其人攻陷而引發長期衝突。"},{"term":"巴格達","def":"阿拉伯帝國首都，中世紀伊斯蘭世界的商業與文化中心，設「智慧之家」翻譯古典著作，13世紀遭蒙古攻陷。"},{"term":"穆斯林","def":"伊斯蘭教徒的稱呼，原意為「歸順阿拉的人」，信奉唯一真神阿拉、以《古蘭經》為經典。"},{"term":"塞爾柱帝國","def":"11世紀崛起的伊斯蘭國家（土耳其人），攻占耶路撒冷、阻撓基督徒朝聖，引發十字軍東征。"},{"term":"朝覲","def":"穆斯林在條件允許下一生至少一次前往聖城麥加朝聖的宗教義務，固定於伊斯蘭曆12月舉行。"}],"timeline":[{"time":"前3500年","event":"蘇美人在兩河流域建立城邦，發明楔形文字"},{"time":"前3100年","event":"埃及出現統一王國，國王稱法老"},{"time":"前2000年","event":"愛琴文明出現，為希臘文明的先驅"},{"time":"前18世紀","event":"巴比倫國王漢摩拉比制定《漢摩拉比法典》"},{"time":"前1500年","event":"阿利安人入侵印度，信奉婆羅門教並建立種姓制度"},{"time":"前8世紀","event":"希臘出現許多城邦"},{"time":"前753年","event":"傳說拉丁人建立羅馬城，進入王政時期（國王領導）"},{"time":"前6世紀","event":"波斯帝國建立；釋迦牟尼創立佛教"},{"time":"前525年","event":"波斯帝國征服埃及（滅埃及），古埃及文明逐漸沒落"},{"time":"前509年","event":"羅馬推翻王政，進入共和時期（元老院決議、執政官執行）"},{"time":"前5世紀","event":"波希戰爭，雅典領導希臘城邦擊退波斯；雅典民主政治發展"},{"time":"前4世紀","event":"馬其頓統一希臘，亞歷山大東征滅波斯，開啟希臘化時代"},{"time":"前3世紀","event":"阿育王宣揚佛教，佛教在印度全盛"},{"time":"前27年","event":"屋大維稱帝（奧古斯都），羅馬進入帝國時期，開啟羅馬和平"},{"time":"1世紀","event":"耶穌在巴勒斯坦創立基督教，初期遭羅馬政府迫害"},{"time":"4世紀初","event":"君士坦丁承認基督教合法，並建新都君士坦丁堡"},{"time":"4世紀末","event":"狄奧多西定基督教為羅馬國教；395年羅馬帝國分裂為東西兩部"},{"time":"476","event":"西羅馬帝國亡於日耳曼人，歐洲進入中世紀"},{"time":"527","event":"查士丁尼登基為拜占庭皇帝"},{"time":"7世紀","event":"穆罕默德在阿拉伯半島創立伊斯蘭教"},{"time":"8世紀","event":"阿拉伯帝國擴張為橫跨歐亞非三洲的帝國，占領伊比利半島"},{"time":"1054","event":"基督教第一次分裂為羅馬公教與希臘正教"},{"time":"11世紀末","event":"塞爾柱土耳其人攻陷耶路撒冷，引發基督教世界與伊斯蘭世界衝突"},{"time":"1187","event":"薩拉丁擊潰十字軍聯軍，奪回耶路撒冷"},{"time":"13世紀末","event":"鄂圖曼帝國崛起"},{"time":"1453","event":"鄂圖曼帝國攻陷君士坦丁堡，拜占庭帝國滅亡"}],"sources":[{"name":"埃及死後審判傳說（心臟與羽毛秤重）","gist":"死者心臟與真理羽毛比重，通過審判者可復活。","clue":"阿努比斯、天秤、復活、木乃伊→古埃及"},{"name":"《漢摩拉比法典》法條","gist":"自由民毀自由民之眼則毀其眼；毀奴隸之眼只需賠償其價之半。","clue":"以牙還牙、自由民與奴隸處罰不同→巴比倫、法律有身分之別"},{"name":"阿瑪爾納頌歌（阿肯那頓頌歌）","gist":"前14世紀埃及頌歌，讚美創造萬物的唯一主神。","clue":"獨一無二的神、唯一主神→一神信仰，類似希伯來人"},{"name":"〈原人歌〉","gist":"原人身體分解：口為婆羅門、兩臂為王族、腿為吠舍、腳生首陀羅。","clue":"婆羅門、吠舍、首陀羅→印度種姓制度"},{"name":"巴比倫世界地圖（泥板）","gist":"前6世紀繪製，中央為幼發拉底河穿過巴比倫城。","clue":"幼發拉底河、巴比倫→兩河流域→楔形文字"},{"name":"雅典民主相關記載","gist":"公民在廣場議論城邦事務、投票放逐危害城邦者、抽籤選官。","clue":"公民、抽籤、放逐、女性與奴隸無公民權→雅典"},{"name":"額爾金石雕（帕德嫩神廟雕塑）","gist":"19世紀初英國大使額爾金運回帕德嫩神廟近半數雕像，現藏大英博物館，希臘持續要求歸還。","clue":"帕德嫩神廟、雅典、人體健美→古希臘藝術"},{"name":"《摩奴法論》","gist":"印度經典，以森嚴的社會階級為核心，規範各階級權利義務與違反懲罰，並以靈魂轉世強化。","clue":"階級、靈魂轉世、維護階級→婆羅門教與種姓制度"},{"name":"塔西佗《歷史》《編年史》","gist":"以拉丁文記述羅馬帝國初期歷史，懲惡揚善，對反面人物仍誠實記述。","clue":"拉丁文、帝國初期、嚮往共和→羅馬帝國（屋大維之後）"},{"name":"犍陀羅佛像","gist":"貴霜王朝時期的佛教雕像，融合希臘寫實手法，深目高鼻、衣褶深刻。","clue":"希臘化風格佛像→亞歷山大東征的影響、佛教經絲路東傳"},{"name":"狄奧多西的敕令","gist":"宣布所有羅馬人都應信奉基督教，其他異教與異端應受打擊，皇帝並在生前受洗。","clue":"所有羅馬人都應信、異端受打擊→4世紀末定為國教、狄奧多西"},{"name":"東羅馬帝國最後的彌撒（1453年）","gist":"鄂圖曼統治者攻陷君士坦丁堡後，在基督教大教堂面向麥加向阿拉禱告。","clue":"鄂圖曼、拜占庭、東羅馬滅亡→15世紀、君士坦丁堡（今伊斯坦堡）"}]},{"unit":12,"part":"世界史","title":"近代世界的變革","summary":"學習近代歐洲的興起（文藝復興、宗教改革、大航海時代）、歐洲殖民帶來的多元世界互動、科學革命與啟蒙運動的理性思維，以及美國獨立與法國大革命；會考常以史料關鍵字、地圖與殖民母國配對判斷時代與事件。","sections":[{"heading":"文藝復興","points":["14世紀起源於義大利半島北部（如佛羅倫斯），盛行於14~16世紀","文藝復興兼具「復古」與「創新」：以古希臘、羅馬文化為基礎，人們關注重心由神轉向人","核心精神為人文主義：以人為本，肯定人的尊嚴與價值、關注現世幸福（中世紀以神為本、關注來世）","背景①：中世紀後期基督教世界與伊斯蘭世界的衝突（十字軍）促進東西貿易，帶動歐洲城市興起","背景②：義大利半島是羅馬帝國發源地、古典文化深植；佛羅倫斯、威尼斯等城市掌握東西方貿易，富商贊助藝文","背景③：拜占庭、阿拉伯學者保存的古典典籍傳回歐洲；造紙術、印刷術使知識流通","威尼斯：由西羅馬帝國難民建於潟湖小島，效忠東羅馬並享高度自治，11世紀獨立","威尼斯藉十字軍運回地中海東岸奢侈品致富，14世紀成東西貿易重鎮","方言文學興起：初期學者崇拜古典、偏好古拉丁文，視方言文學為粗鄙；因民眾看不懂拉丁文、出版商迎合大眾，方言文學逐漸成為主流","方言文學代表：但丁、佩脫拉克、薄伽丘（義大利），莎士比亞（英格蘭），強化各國民族認同","藝術不再限於宗教題材，主題多元、寫實，重視人物性格與情感；除宗教題材外，也接受委託繪製肖像畫","新技法：運用透視、明暗對比；藝術家學習解剖學、肌肉排列與骨骼知識，刻畫生動逼真的人體姿態（如達文西的解剖素描）","代表人物與作品：達文西《蒙娜麗莎》（表情真實細膩）、拉斐爾《草地上的聖母》（明暗對比、姿態柔和）、米開朗基羅《大衛像》（肌肉線條寫實）","1550年瓦薩里在佛羅倫斯出版義大利藝術家傳記，記載13～16世紀建築師、畫家、雕刻家生平"],"example":"比較兩幅聖母圖：中世紀莊嚴神聖、文藝復興寫實溫柔，看到「人性」就想到人文主義。"},{"heading":"宗教改革","points":["背景：羅馬教會腐敗，販售贖罪券斂財；君主希望取得教會財產、擺脫束縛","1517年馬丁路德發表《九十五條論綱》，批判教會，開啟宗教改革","新教共同特點：否定羅馬教會權威、以《聖經》為唯一依歸；一般人可直接討論神學，無須神職人員指導","路德教派：因信得救，信徒可閱讀《聖經》（譯為德文）與上帝溝通，分布北歐、日耳曼","喀爾文教派：預選說，勤奮工作以榮耀上帝，受工商業者支持，分布瑞士、荷蘭、蘇格蘭","長老教會為喀爾文教派分支，清帝國晚期來臺傳教的馬偕、馬雅各皆屬長老教會","英國國教派：亨利八世因婚姻問題與教會決裂，英王兼任教會領袖、脫離羅馬控制，但教義改革不多","舊教改革：羅耀拉（西班牙人，逝世於羅馬）創立耶穌會，重視教士紀律與知識，赴海外傳教（如利瑪竇）","明末耶穌會士利瑪竇允許中國信徒祭祖以減少傳教阻力，並介紹天文、曆法、地理等西學","基督教兩次分裂：11世紀分為羅馬公教與希臘正教；16世紀宗教改革為第二次分裂，再分舊教與新教（路德、喀爾文、英國國教派），各派理念差異大","影響：新舊教衝突（各派理念差異）造成宗教戰爭（如三十年戰爭），戰後逐步確立、逐漸發展出宗教寬容原則","政治影響：羅馬教會影響力減少，新教君主透過控制教會提升權力，有助近代國家興起","經濟與教育影響：新教肯定工作的價值，促進歐洲經濟成長；倡導個人直接讀《聖經》，促進教育、提升識字率"],"example":"新教三派口訣：路德「因信」、喀爾文「預選」、亨利八世「離婚」；羅耀拉則是舊教的耶穌會。","fig":{"src":"../assets/fig/history/u12-s2.svg","cap":"16 世紀宗教改革後歐洲的宗教分布（示意）"}},{"heading":"大航海時代與歐洲海外擴張","points":["大航海時代約15～17世紀；背景：歐洲對香料、絲綢等東方（亞洲）商品需求增加，但東西貿易被義大利與鄂圖曼商人掌控","傳統陸上商路：亞洲商品由阿拉伯商人運到地中海東岸，再由義大利商人賣往歐洲；義大利與鄂圖曼商人控制商路，商品價格高昂","條件：航海技術進步、羅盤使用、王室支持；目標：商業利益、政治擴張、傳播基督福音","葡萄牙「向東」、西班牙「向西」；王室支持航海探險，使兩國逐漸成為海洋強權","葡萄牙：1488年狄亞士發現好望角；1498年達伽馬繞過好望角抵達印度，開闢亞洲新航路，以澳門為東亞據點","西班牙：1492年哥倫布橫渡大西洋抵達美洲（得王室資助），以為抵達印度，因而稱美洲原住民為「印第安人」","西班牙：麥哲倫船隊經南美洲南端（麥哲倫海峽）橫渡太平洋，完成首次環球航行、證實地圓說（1519~1522）","麥哲倫16世紀初率船隊繞過南美洲，在菲律賓遇害，船隊繼續西行完成繞行地球一周","15~16世紀葡、西因經商與殖民成為歐洲強權，歐洲發展重心由地中海轉向大西洋","15世紀後歐洲目光轉向大西洋，加上鄂圖曼帝國威脅，威尼斯的貿易重要性大不如前","影響：促進多元世界交流、開啟全球化，但殖民者武力征服造成不平等的社會與經濟結構","以海洋畫分世界史：古代之海（地中海、羅馬）→伊斯蘭之海（印度洋商路）→歐洲之海（大西洋、近代資本主義）"],"example":"方向記憶：葡萄牙「往南繞非洲到印度」，西班牙「往西橫渡大西洋到美洲」。","fig":{"src":"../assets/fig/history/u12-s3.svg","cap":"大航海時代的重要航線"}},{"heading":"歐洲殖民與多元世界的互動","points":["美洲古文明：阿茲提克（今墨西哥，觀察太陽擬定曆法）、馬雅（今墨西哥境內，城邦文明，天文、數學、文字成就高）","印加文明位於秘魯安地斯山脈，遺址馬丘比丘；西班牙征服者科爾迪斯征服阿茲提克、皮薩羅征服印加","美洲：西班牙消滅阿茲提克、印加文明，占多數中南美洲，葡萄牙占巴西；開採白銀、種植經濟作物","原住民因屠殺、傳染病（天花）、勞役而銳減，殖民者自非洲輸入黑奴補充勞力，形成三角貿易並改變人口結構","殖民經濟影響：開啟白銀貿易時代（大量白銀流入歐亞）；美洲作物養活大量人口；販運非洲黑人改變美洲族群結構","英國人稱砂糖、棉花為「白色貨品」、黑奴為「黑色貨品」；17~18世紀英國繁榮奠基於壓榨黑奴的勞動","美洲農產品跌價、取得黑奴成本增加，加上人道批判與輿論壓力，1807年英國制定《廢除奴隸貿易法》","哥倫布大交換：玉米、番薯、馬鈴薯、可可傳入歐亞非；小麥、甘蔗、咖啡、牛、馬傳入美洲","美洲作物玉米由葡萄牙人傳入非洲剛果（稱「葡萄牙黍」），初為飼料，因高產逐漸成為當地首要糧食作物","西班牙以馬尼拉為亞洲據點，大帆船貿易將美洲白銀運往亞洲","葡萄牙在印度西岸建立殖民城市（以達伽馬命名），打壓穆斯林與印度教徒，使多數人改信天主教，20世紀中期主權才移轉","16世紀末葡、西逐漸衰落，英、荷取而代之，陸續設東印度公司從事海外擴張、爭奪殖民地","英、荷東印度公司都是官方特許狀的集資民營公司，可籌組武裝勢力；英：1600年、總部倫敦；荷：1602年、阿姆斯特丹等6個分部","17世紀荷蘭（聯合東印度公司，VOC）以巴達維亞為總部，控制東印度群島香料，並在長崎出島與日本貿易","荷蘭聯合東印度公司占領澎湖失敗，1624年轉而占領臺灣，建熱蘭遮城為統治中心；英國東印度公司則與鄭氏有商業往來","VOC在平戶、長崎、廣州、阿育陀耶等地設貿易據點，曾向日本訂製印有VOC紋章的瓷器","荷蘭長期殖民印尼；1945年蘇卡諾等人在雅加達宣讀《獨立宣言》，宣布印度尼西亞獨立","16世紀起蒙兀兒帝國統治印度，採中央集權，17世紀國勢極盛、領土涵蓋中亞與印度","蒙兀兒帝國融合波斯、伊斯蘭、印度文化，代表建築為泰姬瑪哈陵","17世紀蒙兀兒帝國同意英國東印度公司在印度沿海設商館；公司並購買中國絲綢與茶葉銷往歐洲","18世紀英國擴張在印度勢力、取代衰弱的蒙兀兒帝國；19世紀中期直接派總督治理印度","英國東印度公司以印度為基地（種棉花、鴉片），19世紀中期英國正式殖民印度","1862年英國在印度發行貨幣，取代東印度公司貨幣；公司自1659年統治聖赫勒那島，後移交英國政府，運作持續至1874年解散","澳洲原住民長期與世隔絕、語言多樣，以狩獵、採集為生","18世紀後期英國殖民（占領）澳洲並流放囚犯開墾，1788年建殖民地","英國殖民者掠奪澳洲原住民土地，雙方衝突加上傳染病，造成許多原住民死亡","1992年澳洲「馬博裁決」承認原住民（托雷斯海峽島民）原有土地權，否定英國殖民時「無主地」的主張；次年通過《土著產權法》","轉型正義：美國以6月19日「六月節」紀念1865年最後一批被奴役的非洲裔美國人獲得自由，反省黑奴制度","美洲國家原以10月12日紀念哥倫布，近年受轉型正義影響改名為原住民日、原住民抵抗日、尊重文化多樣性之日等"],"example":"殖民配對：葡—巴西、西—拉丁美洲與菲律賓、荷—印尼與臺灣、英—印度與澳洲。"},{"heading":"科學革命","points":["16~17世紀，延續人文主義精神，以理性、觀察與實驗重新思索宇宙萬物運作原理","科學革命的新知識方法：歸納法與演繹法；培根提倡歸納法（觀察、蒐集事實歸納出定律）","笛卡兒提倡演繹法（知識藉推理而得），名言「我思故我在」","培根主張發現真理須先排除四種假象（部落、洞穴、市場、劇場），再以實驗蒐集事實、找出規律","新工具（望遠鏡、顯微鏡、溫度計）使觀測更準確","17世紀英、法等國設立科學研究機構（如皇家學會、法蘭西科學院）","英國皇家學會1660年成立、1662年獲英王特許（翰林兩處分作1660／1662年）","1699年法王路易十四贊助成立法蘭西科學院","哥白尼《天體運行論》提出太陽中心說，挑戰教會的地球中心說；挑戰傳統學術與宗教界，稱為「哥白尼革命」","伽利略以望遠鏡觀測天體（含太陽黑子）證實哥白尼理論（學說），並研究斜面與自由落體","1633年伽利略因支持太陽中心說遭教會審判：被宗教法庭以理論違背《聖經》為由審判","牛頓提出萬有引力定律與三大運動定律；17世紀科學人才輩出，被稱為「天才的世紀」","影響：建立科學的宇宙觀，啟發人們以理性探討人類社會，引發啟蒙運動與工業革命","連鎖影響：科學革命→啟蒙運動→美國獨立與法國大革命"],"example":"地心說→日心說的轉變，關鍵人物就是哥白尼《天體運行論》。"},{"heading":"啟蒙運動","points":["17世紀末~18世紀（盛行於18世紀）受科學革命啟發，運用理性解釋人類社會，批判專制王權與教會，以法國為重鎮","時間比較：文藝復興14~16世紀、科學革命16~17世紀、啟蒙運動17世紀末~18世紀","三大著作：洛克著《政府論》；盧梭著《民約論》（又稱《社會契約論》）；孟德斯鳩著《法意》（即《論法的精神》）","洛克（英）：天賦人權，生命、自由、財產不可侵犯，政府侵害時人民有權反抗","盧梭（法）：主權在民，政府權力來自人民委託","孟德斯鳩（法）：《論法的精神》，行政、立法、司法三權分立、互相制衡","三權分立為美國採行，後來不少民主共和國仿效","伏爾泰（法）：批判教會與迷信，主張宗教寬容與言論自由","狄德羅編纂《百科全書》；亞當斯密提倡自由放任","17世紀中期英國出現咖啡館（「一便士大學」），1660年代後倫敦咖啡館林立，成為分享知識、政治觀點與傳播啟蒙思潮的場所","影響：成為近代民主政治的思想淵源，啟發美國獨立與法國大革命"],"example":"口訣：洛克天賦、盧梭主權、孟德斯鳩三權、伏爾泰言論。"},{"heading":"美國獨立","points":["英國在北美洲東岸建立十三州殖民地，後因英國加稅、施加不合理管轄引發不滿","英國為解決對外戰爭的財政負擔向北美殖民地徵新稅，殖民地以英國國會中沒有代表為由拒絕納稅","1773年殖民地人民把英商（英國東印度公司）茶葉倒入海中，史稱波士頓茶葉事件","1776年7月4日十三州代表於費城發表《獨立宣言》，宣布脫離英國，吸收洛克天賦人權與盧梭主權在民學說","華盛頓率軍作戰，並獲法國、西班牙、荷蘭等國協助；1783年英國承認美國獨立","1787年制定世界第一部成文憲法，採聯邦制與孟德斯鳩三權分立，總統為國家元首","1789年華盛頓就任首任總統，組織聯邦政府","美國三權分立：總統（行政）可否決法案、提名法官；國會（立法）可彈劾總統、同意法官任命；聯邦法院（司法）審查法案是否違憲","美國成為第一個實踐啟蒙思想的民主共和國","美國為首個聯邦共和國，透過憲法界定中央與各州權限；獨立後陸續向西擴張領土"],"example":"看到「宣布與英國弟兄脫離」「總統＋參眾兩院＋聯邦最高法院」，就是18世紀後期的美國。"},{"heading":"法國大革命與拿破崙","points":["背景：法國多次參加對外戰爭（含援助美國獨立）造成政府財政困難；並受啟蒙思想與美國《獨立宣言》影響","社會分為教士、貴族、平民三級，教士與貴族人少卻擁有特權、免稅，賦稅由平民負擔","1789年路易十六為徵新稅召開三級會議，每階級1票共3票，平民代表不滿投票方式，另組國民會議","1789年7月14日巴黎民眾攻陷巴士底監獄（關政治犯、專制王權象徵），揭開法國大革命序幕","國民會議發表《人權宣言》，強調自由、平等；《1791年憲法》體現主權在民與分權思想","弗里吉帽（自由之帽）在法國大革命中象徵追求自由，成為法蘭西共和國的重要標誌","歐洲各國君主怕革命蔓延而組成聯軍攻法；法國後廢除君主、處死路易十六，建立共和","改建共和後，激進派領袖羅伯斯比掌權，大量處決反對者，法國籠罩在恐怖統治下；斷頭臺為恐怖統治的象徵","現代化學之父拉瓦錫因擔任稅務官，在大革命中被送上斷頭臺","拿破崙擊敗反法聯軍成為民族英雄，掌權後1804年稱帝建立法蘭西帝國，以武力征服歐洲大部分地區","《拿破崙法典》（民法典）取消貴族與教士特權，規定財產權、所有權等型態，成為許多歐洲國家修改法律的藍本","拿破崙影響：征服大半歐洲並傳播「自由、平等、博愛」革命理念；其占領行動激起歐洲各國的民族意識","1812年拿破崙遠征俄國，俄軍採焦土政策撤退，法軍占領莫斯科卻缺糧、嚴冬中潰敗，帝國由盛轉衰，反法聯軍反攻","1815年滑鐵盧之役戰敗失勢，結束拿破崙時代；被流放至南大西洋的聖赫勒那島，6年後（1821）病逝","維也納會議：由奧國主導，為重整被拿破崙破壞的歐洲秩序，以「正統」恢復原有王室並維持勢力平衡，此後確保歐洲數十年沒有大型戰爭","美法革命比較：美國反抗殖民母國英國、獲法西荷支持、制定三權分立憲法；法國反抗君主專制、遭反法聯軍進攻、理念隨拿破崙傳播"],"example":"三級會議口訣：教士、貴族2%人口不繳稅，98%平民扛全部稅，革命一觸即發。"}],"confusions":[{"a":"中世紀的藝術","b":"文藝復興的藝術","diff":"中世紀藝術以宗教為主題，人物造型刻板，表現神聖莊嚴；文藝復興藝術主題多元、寫實可親，運用透視、明暗對比，重視人物表情姿態","tip":"刻板、莊嚴、只畫神→中世紀；寫實、肖像、肌肉線條、透視→文藝復興"},{"a":"文藝復興","b":"啟蒙運動","diff":"文藝復興（14~16世紀，義大利）以人文主義批判神學、成就在文學藝術；啟蒙運動（18世紀，英法）以理性批判專制王權與教會，成就在政治思想","tip":"看到「古典、人性、方言、藝術」→文藝復興；看到「理性、天賦人權、三權分立、主權在民」→啟蒙"},{"a":"宗教改革（新教）","b":"舊教改革（耶穌會）","diff":"新教否定羅馬教會與教宗權威、以《聖經》為唯一依歸；耶穌會效忠教宗，是天主教內部為重振權威而改革","tip":"反教宗＝新教；效忠教宗、海外傳教（利瑪竇、南美聚落）＝耶穌會"},{"a":"路德教派","b":"喀爾文教派","diff":"路德主張因信得救，分布日耳曼、北歐；喀爾文主張預選說、勤奮工作榮耀上帝，分布瑞士、荷蘭、蘇格蘭","tip":"「因信」→路德；「預選、簡約勤奮、工商業者」→喀爾文"},{"a":"葡萄牙的航路","b":"西班牙的航路","diff":"葡萄牙沿非洲西岸南下繞好望角抵達印度（狄亞士、達伽馬）；西班牙向西橫渡大西洋抵達美洲（哥倫布）、環球航行（麥哲倫）","tip":"好望角、印度、澳門→葡；美洲、白銀、馬尼拉→西"},{"a":"荷蘭東印度公司","b":"英國東印度公司","diff":"荷蘭（1602年設立）以巴達維亞為總部經營東印度群島香料、占臺灣（熱蘭遮城）、長崎貿易；英國（1600年設立、總部倫敦）以印度為基地種棉花、鴉片，並走私鴉片至中國","tip":"巴達維亞、臺灣、長崎→荷；孟買、加爾各答、鴉片→英"},{"a":"科學革命","b":"啟蒙運動","diff":"科學革命（16~17世紀）以科學方法、理性態度尋找自然法則，成就在天文學、物理學；啟蒙運動（17世紀末~18世紀）把科學方法用於尋找社會法則，成就在政治學說","tip":"哥白尼、伽利略、牛頓、望遠鏡→科學革命；洛克、孟德斯鳩、盧梭、伏爾泰→啟蒙運動"},{"a":"洛克","b":"盧梭","diff":"洛克強調生命、自由、財產為天賦人權，政府侵犯時人民可反抗；盧梭強調主權屬於人民、政府權力來自人民委託","tip":"生命自由財產→洛克；主權在民、國民→盧梭"}],"terms":[{"term":"人文主義","def":"文藝復興的核心精神，以人為本，肯定人的尊嚴與價值，關注現世幸福，不同於中世紀以神為中心的價值觀。"},{"term":"方言文學","def":"文藝復興時期學者改以當地方言而非拉丁文創作，如但丁、薄伽丘、莎士比亞，強化各國民族認同。"},{"term":"透視法","def":"文藝復興畫家運用的技法，依遠近比例呈現立體空間，配合明暗對比使畫面寫實。"},{"term":"贖罪券","def":"羅馬教會販售、宣稱可赦免罪罰的憑證；教會藉此斂財，引發馬丁路德批判，成為宗教改革的導火線。"},{"term":"九十五條論綱","def":"1517年馬丁路德公開發表，批判羅馬教會販售贖罪券等腐敗行為，開啟宗教改革序幕。"},{"term":"因信得救","def":"路德教派主張，信徒憑藉自身對上帝的虔誠信仰即能得到救贖，不需仰賴教會與外在儀式。"},{"term":"預選說","def":"喀爾文教派主張，信徒能否得救早由上帝預先決定，信徒應勤奮工作、節儉簡約以榮耀上帝。"},{"term":"耶穌會","def":"16世紀羅耀拉創立的天主教團體，效忠教宗、重視教士紀律與知識訓練，積極赴海外傳教，如利瑪竇來華。"},{"term":"宗教寬容","def":"宗教改革後新舊教戰爭（如三十年戰爭）結束，各國逐步保障不同教派信仰自由的原則。"},{"term":"印第安人","def":"哥倫布抵達美洲後誤以為到達印度，因而對美洲原住民的稱呼。"},{"term":"阿茲提克文明","def":"位於今墨西哥的古文明，觀察太陽變化擬定曆法，16世紀被西班牙征服者科爾迪斯消滅。"},{"term":"馬雅文明","def":"中美洲古文明，位於今墨西哥境內，天文、數學與文字成就極高，發展城邦，遺址如馬雅金字塔。"},{"term":"印加文明","def":"南美洲秘魯安地斯山脈的古文明，遺址為馬丘比丘，16世紀被西班牙征服者皮薩羅消滅。"},{"term":"哥倫布大交換","def":"哥倫布抵達美洲後，新舊大陸間作物、牲畜、人口與疾病的大規模交流，如玉米、番薯傳入歐亞非。"},{"term":"三角貿易","def":"16~17世紀歐洲將日用品運往非洲、非洲黑奴運往美洲、美洲殖民地產品運回歐洲的貿易體系。"},{"term":"大帆船貿易","def":"16世紀中葉起西班牙將墨西哥白銀以大帆船運往馬尼拉，換取中國絲綢、瓷器等再轉銷歐洲的貿易。"},{"term":"東印度公司","def":"17世紀英（1600）、荷（1602）等國設立的特許貿易公司，可籌組武裝，在亞洲建立殖民據點，如荷蘭以巴達維亞、英國以印度為基地。"},{"term":"蒙兀兒帝國","def":"16世紀信奉伊斯蘭教的蒙古後裔在印度建立的帝國，融合波斯、伊斯蘭與印度文化，19世紀中期為英國所滅。"},{"term":"太陽中心說","def":"16世紀哥白尼在《天體運行論》中提出地球繞太陽運行的學說，挑戰教會的地球中心說，稱「哥白尼革命」，被視為科學革命開端。"},{"term":"歸納法","def":"培根提倡的知識方法，透過觀察、大量蒐集事實再分析歸納，建立普遍的原則或科學定律。"},{"term":"演繹法","def":"笛卡兒提倡的知識方法，主張知識可藉由推理而得，不必仰賴經驗歸納，名言「我思故我在」。"},{"term":"天才的世紀","def":"指17世紀，歐洲科學人才輩出、科學革命成果豐碩，如伽利略、牛頓等。"},{"term":"天賦人權","def":"洛克在《政府論》中主張生命、自由、財產是人與生俱來的權利，政府若侵犯，人民有權反抗並另立政府。"},{"term":"主權在民","def":"盧梭在《民約論》（社會契約論）中主張國家主權屬於人民，政府的權力來自人民的委託，是近代民主政治的重要基礎。"},{"term":"三權分立","def":"孟德斯鳩在《論法的精神》中主張政府的行政、立法、司法三權分立、互相制衡，以避免專制；美國憲法首先採行。"},{"term":"百科全書","def":"18世紀法國狄德羅邀集盧梭、伏爾泰等學者編纂，系統整理當代知識，促進啟蒙思想的傳播。"},{"term":"獨立宣言","def":"1776年北美十三州發表的文件，指責英國不合理的統治，宣布脫離英國獨立，體現天賦人權思想。"},{"term":"國民會議","def":"1789年法國平民代表不滿三級會議投票方式另組的會議，主張保障人權，後發表《人權宣言》。"},{"term":"巴士底監獄","def":"關押政治犯的監獄，為法國專制王權的象徵；1789年7月14日被巴黎民眾攻陷，揭開法國大革命序幕。"},{"term":"無套褲漢","def":"法國大革命時期對中下階級平民的稱呼，他們不穿貴族式的及膝套褲，是革命的重要力量。"},{"term":"拿破崙法典","def":"拿破崙頒布的民法典，取消貴族與教士特權、保障法律平等，並隨其征服將法國大革命理念傳播歐洲。"},{"term":"焦土政策","def":"戰爭時一方撤退時自行燬壞駐地建築、物資，使敵方無法利用；1812年俄國以此擊退拿破崙大軍。"}],"timeline":[{"time":"14世紀","event":"文藝復興起源於義大利半島北部"},{"time":"1453","event":"鄂圖曼帝國攻陷君士坦丁堡，滅拜占庭帝國，掌控東西貿易通道"},{"time":"1488","event":"葡萄牙狄亞士抵達非洲南端好望角"},{"time":"1492","event":"哥倫布橫渡大西洋抵達美洲"},{"time":"1498","event":"葡萄牙達伽馬繞過好望角抵達印度"},{"time":"16世紀","event":"西班牙消滅阿茲提克、印加文明，占有中南美洲大部分區域"},{"time":"1517","event":"馬丁路德發表《九十五條論綱》，宗教改革開始"},{"time":"1519~1522","event":"麥哲倫船隊完成首次環球航行，證實地圓說"},{"time":"16世紀中期","event":"哥白尼提出太陽中心說；羅耀拉創立耶穌會；西班牙展開大帆船貿易"},{"time":"17世紀初","event":"英國（1600）、荷蘭（1602）相繼設立東印度公司"},{"time":"1618~1648","event":"三十年戰爭，戰後各國簽訂《西發里亞和約》，逐步確立宗教寬容"},{"time":"1624","event":"荷蘭聯合東印度公司占領澎湖失敗後，轉而占領臺灣"},{"time":"1632","event":"伽利略出版著作支持哥白尼太陽中心說"},{"time":"1633","event":"伽利略遭宗教法庭審判"},{"time":"1660","event":"英國皇家學會成立，推動科學研究（1662年獲英王特許；翰林內文作「1662年英王成立」）"},{"time":"1687","event":"牛頓提出萬有引力定律"},{"time":"1690","event":"洛克提出天賦人權（《政府論》）"},{"time":"1699","event":"法王路易十四贊助成立法蘭西科學院"},{"time":"18世紀","event":"啟蒙運動盛行（洛克、盧梭、孟德斯鳩、伏爾泰）"},{"time":"1773","event":"北美殖民地波士頓茶葉事件"},{"time":"1776","event":"北美十三州發表《獨立宣言》"},{"time":"1783","event":"英國承認美國獨立"},{"time":"1787","event":"美國制定世界第一部成文憲法，採三權分立"},{"time":"1788","event":"英國在澳洲建立新南威爾斯殖民地，作為囚犯流放地"},{"time":"1789","event":"法國大革命爆發，發表《人權宣言》；同年華盛頓就任美國首任總統"},{"time":"1792~1795","event":"法國大革命恐怖統治時期"},{"time":"1804","event":"拿破崙稱帝，建立法蘭西帝國"},{"time":"1807","event":"英國制定《廢除奴隸貿易法》，禁止奴隸交易"},{"time":"1812","event":"拿破崙遠征俄國失敗，反法聯軍反攻"},{"time":"1815","event":"拿破崙於滑鐵盧戰敗失勢"},{"time":"19世紀中期","event":"英國終結蒙兀兒帝國，正式殖民印度"}],"sources":[{"name":"九十五條論綱／馬丁路德的答辯","gist":"批判教宗律法與羅馬教會的勒索，主張只受《聖經》約束，不願撤回批評教會的言論。","clue":"贖罪券、教宗、只受《聖經》約束、德意志→16世紀宗教改革、馬丁路德"},{"name":"宗教改革時期的木刻版畫與傳單","gist":"新教版畫將教宗畫成怪獸、諷刺「用錢來贖罪」；舊教傳單則畫馬丁路德與魔鬼共煮教義。","clue":"醜化教宗→支持路德（新教）；醜化路德→羅馬教會立場"},{"name":"洛克《政府論》","gist":"執政者若侵犯人民的生命、自由和財產，人民有權收回託付的權力，重立新執政者。","clue":"生命、自由、財產、有權反抗→洛克天賦人權"},{"name":"孟德斯鳩《論法的精神》","gist":"立法、行政、司法若集中於同一人或機關，自由便不復存在。","clue":"三種權力分立、制衡、避免專制→孟德斯鳩"},{"name":"《獨立宣言》","gist":"指責英國立法機構把不合理管轄權橫加於殖民地，因此宣布與英國脫離。","clue":"18世紀後期、英國弟兄、宣布脫離→北美十三州獨立"},{"name":"《1791年憲法》","gist":"主權屬於國民，國王只能依法律治理，司法權由人民選出的審判官行使。","clue":"主權屬於國民、法國大革命→盧梭主權在民"},{"name":"英國《廢除奴隸貿易法》（1807）","gist":"因奴隸貿易利潤下滑及人道批判、輿論壓力，英國立法禁止奴隸的交易。","clue":"白色貨品、黑色貨品、西印度群島砂糖、1807→英國三角貿易與廢奴"},{"name":"英屬印度時期發行的貨幣（1862年）","gist":"正面為英國維多利亞女王肖像，背面為幣值（ONE QUARTER ANNA INDIA）與鑄造年1862。","clue":"維多利亞女王、INDIA、19世紀中期→英國直接統治印度"},{"name":"印度尼西亞《獨立宣言》（1945年）","gist":"印度尼西亞民族宣布獨立，政權移交事宜將從速辦妥，由蘇卡諾、哈達具名。","clue":"雅加達（巴達維亞）、香料→荷蘭殖民地印尼獨立"}]},{"unit":13,"part":"世界史","title":"現代國家與帝國主義的發展","summary":"從18世紀英國工業革命、美法政治革命、拉丁美洲獨立與德義統一，到19世紀後期帝國主義瓜分亞非、第一次世界大戰與巴黎和會；會考常以史料、統計圖表與地圖判斷時代與因果。","sections":[{"heading":"工業革命","points":["18世紀中期起源於英國紡織業：中世紀英國即為羊毛紡織中心，新航路發現後加工印度棉花、輸出棉紡織品","英國先工業化的背景：政治安定、煤鐵豐富、擁有廣大殖民地提供原料與市場；充裕資金與人才投入技術改良","龐大市場需求促使英國陸續改良織布機；18世紀後期（1769）瓦特改良蒸汽機，先用於紡織業","19世紀初蒸汽機應用於汽船、火車，促成交通運輸革新","工業革命傳播順序：英國→歐陸各國→美國→亞洲；傳到亞洲的代表為中國自強運動、日本明治維新","1851年英國倫敦舉辦首屆世界博覽會，展示英國最早工業化的強盛生產力","工廠制度形成並帶來就業機會，人口湧向城市、集中都市（都市化），歐洲相繼出現大城市","都市化帶來空氣汙染、擁擠、治安敗壞等問題；工人權益缺乏保障，勞資對立、貧富差距擴大","社會主義因而興起，分兩派：溫和派主張以改革、立法等和平手段解決","激進派如馬克思提出共產主義：主張階級鬥爭、以革命推翻現有秩序、財產公有","工業國家為爭奪原料與市場，爭奪海外殖民地，促使帝國主義再度擴張"],"example":"關鍵字「蒸汽機、煤煙、童工、城市人口激增」→工業革命；「貧富差距、勞工階級」→社會主義。"},{"heading":"歐美的政治革命","points":["英國為解決財政困難向北美殖民地徵稅，殖民地主張「無代表不納稅」，1773年波士頓茶葉事件","1776年北美十三州發表《獨立宣言》，華盛頓領軍戰勝英軍，1783年英國承認美國獨立","美國制定成文憲法，建立三權分立的聯邦共和政府，落實啟蒙思想","1789年路易十六為徵稅召開三級會議，巴黎市民攻陷巴士底監獄，國民會議發表《人權宣言》","反法聯軍進攻，革命轉向激進：改行共和、處死路易十六、羅伯斯比恐怖統治","1804年拿破崙稱帝，頒布《拿破崙法典》並征服歐陸，傳播革命精神、喚起民族意識；1815年敗於滑鐵盧","1814～1815年維也納會議由奧地利主導，以正統、均勢為原則，恢復舊王室統治","維也納會議以正統原則恢復舊秩序，使歐洲近半世紀無大規模戰爭，並成立日耳曼邦聯"],"example":"「自由、平等、博愛」的精神隨拿破崙大軍傳遍歐洲，反而激起各地反法的民族意識。"},{"heading":"中南美洲獨立運動","points":["背景：土生白人不滿西、葡高壓統治與經濟剝削；西、葡殖民政府長期壟斷資源，引起當地人民不滿","受啟蒙思想、美國獨立與法國大革命鼓舞；英、美也支持拉丁美洲獨立","19世紀初拿破崙入侵伊比利半島，西、葡自顧無暇，玻利瓦等人領導獨立運動","墨西哥獨立：當地菁英趁拿破崙占領西班牙起事，印第安人與混血族群則訴求經濟社會改革，最終建國","1820年代陸續形成新興國家：1821年中美洲五國（瓜地馬拉、宏都拉斯、薩爾瓦多、尼加拉瓜、哥斯大黎加）獨立","1822年巴西脫離葡萄牙獨立；殖民影響至今：拉丁美洲大部分國家使用西班牙語，巴西則使用葡萄牙語","1823年美國總統門羅發表《門羅宣言》：美洲事務由美洲人自行解決，反對歐洲干涉","門羅宣言的影響：鞏固拉丁美洲的獨立，也增強美國對拉丁美洲的控制","此後拉丁美洲政治、經濟漸受美國宰制（如介入古巴、巴拿馬）"],"example":"玻利瓦被稱為「解放者」「南美的華盛頓」，玻利維亞國名即為紀念他。"},{"heading":"德意志與義大利的統一","points":["兩地中世紀起長期邦國林立；拿破崙的征服激發民族意識，成為追求統一的動力","拿破崙稱霸期間將日耳曼地區小國合併為三十多邦；維也納會議後組成日耳曼邦聯，以奧國實力最強","德、義統一的共同阻礙是奧國與法國","德意志：1834年普魯士主導成立關稅同盟，奠定統一的經濟基礎","首相俾斯麥推行「鐵血政策」，以戰爭打敗奧國、法國：1866年普奧戰爭先戰勝奧國，奧國被迫解散日耳曼邦聯","1870年展開德法戰爭；1871年威廉一世在凡爾賽宮登基，建立德意志帝國","德國統一後積極發展工商業、向海外擴張，成為歐洲強國；俾斯麥推行以社會保險為核心的醫療制度（俾斯麥模式）","義大利：維也納會議在北義設倫巴底－威尼托王國交奧地利統治；以薩丁尼亞王國（國王伊曼紐二世）為核心","建國三傑：馬志尼（宣揚民族意識）、加富爾（排除奧國勢力）、加里波底（征服南部）","馬志尼成立青年義大利黨，以「恢復古羅馬光榮」為號召宣揚民族意識，原主張建立統一的共和國","奧國1860年薩奧戰爭失去倫巴底，義大利取得倫巴底；同年加里波底親率「紅衫軍」征服兩西西里王國，獻給薩丁尼亞國王","1861年成立義大利王國，最終以王國（君主制）完成統一；1866年普奧戰爭奧國失去威尼斯，義大利再取得威尼托","羅馬原由法國以保護教皇為由駐軍；1870年趁德法戰爭法軍撤離，收復羅馬並定為首都，完成統一"],"example":"德法戰爭一石二鳥：德意志帝國成立（1871），義大利收復羅馬（1870）。","fig":{"src":"../assets/fig/history/u13-s4.svg","cap":"德意志與義大利的統一"}},{"heading":"帝國主義的再擴張","points":["帝國主義定義：一個國家利用強勢軍事或政治力量壓迫其他國家，進而占領土地、建立殖民地","三大背景：工業革命（需要原料、市場）、民族主義（民族自尊）、文化優越感（合理化侵略行為）","社會達爾文主義盛行，歐美自認有教化落後地區的使命（白種人的負擔）","亞洲：英國以印度為中心擴張至緬甸、馬來亞；法國在清法戰爭後占越南，組成法屬印度支那","荷蘭加強對印尼的控制；美國19世紀中期強迫日本開港，後自西班牙手中奪得菲律賓","日本明治維新後亦成為帝國主義國家：侵略琉球、中國、朝鮮，以臺灣、朝鮮為跳板進行侵略","19世紀亞洲殖民地：英（印度、香港、緬甸）、法（以越南為中心）、日（琉球、臺灣、朝鮮）、美（菲律賓）、荷（印尼）","非洲：19世紀後期列強（柏林會議）瓜分非洲，以經緯線劃界不顧族群分布，導致日後領土與民族糾紛","非洲僅衣索比亞、賴比瑞亞保持獨立；賴比瑞亞1847年宣布獨立，源於美國殖民協會安置自由黑人","賴比瑞亞首都門羅維亞以門羅總統命名","拉丁美洲：美國介入中南美洲內政與經濟，並在美西戰爭後取得菲律賓；拉丁美洲民眾抗爭曾遭美軍鎮壓","1898年美西戰爭後美國簽《巴黎條約》取得古巴、菲律賓、波多黎各；馬克吐溫曾反對併吞","美國1946年才承認菲律賓獨立；美國支持巴拿馬獨立並取得巴拿馬運河治理權，直到1999年底才將運河歸還巴拿馬","殖民地式經濟：殖民地生產經濟作物或工業原料，導致當地糧食不足，雖進入世界貿易體系但普遍貧窮落後","文化衝擊：強勢文化以無形、強迫方式不斷擴張；弱勢文化不自覺接受，產生文化衝突與自我認同危機","一戰前夕歐洲國家掌控全球過半陸地；列強爭奪殖民地的衝突間接導致第一次世界大戰"],"example":"英國羅德斯的「2C計畫」要把開普敦（Cape Town）到開羅（Cairo）的殖民地連成一片。","fig":{"src":"../assets/fig/history/u13-s5.svg","cap":"帝國主義：約 1914 年列強在亞洲、非洲的殖民地"}},{"heading":"第一次世界大戰","points":["德法戰爭後德國拉攏俄、奧結盟；後因德國大日耳曼主義威脅俄國，俄國轉與法國結盟，德國只能全力支持奧匈","德國積極發展海軍與殖民地，刺激原本保持中立的英國與法、俄結盟","戰前形成兩大集團：三國同盟（德、奧、義，1882）與三國協約（英、法、俄，1907）","巴爾幹半島因鄂圖曼衰弱、奧俄角力，成為「歐洲火藥庫」；塞爾維亞向同為斯拉夫民族的俄國靠攏","巴爾幹紛爭的宗教背景：鄂圖曼帝國信奉伊斯蘭教，斯拉夫人信奉希臘正教；奧匈帝國以日耳曼人為主","奧匈帝國（1867～1918）為雙元帝國：奧地利皇帝約瑟夫一世同時兼任匈牙利國王，民族問題始終是隱憂","奧匈帝國自鄂圖曼手中取得波士尼亞、赫塞哥維納管理權","導火線：1914年奧國皇儲在塞拉耶佛遇刺，奧國向塞爾維亞宣戰；德國基於大日耳曼主義及德奧同盟條約支持奧國參戰","各國參戰理由：俄國以「支持斯拉夫小兄弟」動員；英國以德國破壞比利時中立參戰；日本藉口英日同盟參戰","形成同盟國對協約國：同盟國為德、奧、土（鄂圖曼）、保（保加利亞）；協約國為英、法、俄、義、日，義大利倒戈加入協約國","大戰初期同盟國占優勢；西線陷入壕溝戰，東線為德俄交戰，俄國屢屢失敗","坦克、毒氣、潛艇、飛機等新式武器登場","坦克最早出現於一戰，用以支援步兵突破西線壕溝戰的膠著戰線，改變以壕溝與防禦工事為主的作戰型態","1917年德國無限制潛艇政策與煽動墨西哥反美，促使美國參戰；同年中國也加入協約國","一戰期間中華民國對德、奧宣戰，廢除兩國間條約、收回租界，戰後得以戰勝國身分出席巴黎和會","1917年俄國兩次革命，1918年退出戰爭","1918年美國與協約國在西線展開反擊，同盟國漸趨劣勢；11月雙方達成停戰協定","影響：殖民地資源與人力也被動員參戰；動員規模空前，英、美等國女性投入後勤生產工作，權益提升","戰後婦女地位提升，獲得投票權"],"example":"判斷陣營：看到「支援斯拉夫兄弟」想俄國，「無限制潛艇政策」想美國參戰。","fig":{"src":"../assets/fig/history/u13-s6.svg","cap":"第一次世界大戰歐洲形勢"}},{"heading":"戰後秩序重建","points":["依據美國總統威爾遜提出的「十四點原則」，如民族自決、成立國際聯盟；可視為19世紀民主與民族運動的成果","1919年巴黎和會由戰勝國主導，戰敗國不得參加；翰林作在巴黎凡爾賽宮舉行","巴黎和會由三巨頭主導：法國克里蒙梭、英國勞合喬治、美國威爾遜","對德國的《凡爾賽條約》：割地、賠款（負擔所有戰爭賠償）、限制軍備並負戰爭罪責","《凡爾賽條約》規定德國軍隊總人數不得超過10萬；德國在山東的特權由日本繼承","《凡爾賽條約》令德國人民不滿，埋下第二次世界大戰的火種","德意志、奧匈、鄂圖曼、俄羅斯四大帝國瓦解，波蘭、捷克等新興國家依民族自決建國","一戰後新興國家：芬蘭、愛沙尼亞、拉脫維亞、立陶宛、波蘭、捷克、奧地利、匈牙利、南斯拉夫等；鄂圖曼縮為土耳其","但新興國家並未完全依民族自決原則處理，造成日後國際秩序的隱憂","1919年朝鮮三一運動受威爾遜民族自決理念影響，向世界宣布獨立","國際聯盟由威爾遜倡議，1920年成立，總部設在瑞士日內瓦","威爾遜在巴黎和會未得到所有想要的成果，《凡爾賽條約》也未獲美國參議院批准","孤立主義：1920年代起美國不參與他國事務、拒絕加入國聯、採取關稅保護，助長第二次世界大戰爆發","國際聯盟因美國孤立主義未加入，且缺乏武力（軍事力量），威信日漸低落、成效不彰"],"example":"越南胡志明向巴黎和會請願爭取自治未獲回應，可見民族自決實際上只適用於歐洲。","fig":{"src":"../assets/fig/history/u13-s7.svg","cap":"第一次世界大戰後的歐洲：民族自決與新興國家"}}],"confusions":[{"a":"社會主義（溫和派）","b":"共產主義（激進派）","diff":"兩者都想解決工業革命造成的勞資對立與貧富懸殊；溫和派主張以改革、立法等和平手段，激進派（馬克思）主張以革命推翻現有秩序、廢除私有財產","tip":"立法、改革、和平→溫和社會主義；革命、廢私產、消除階級→馬克思共產主義"},{"a":"《獨立宣言》","b":"《人權宣言》","diff":"《獨立宣言》是1776年北美十三州宣布脫離英國；《人權宣言》是1789年法國國民會議宣示自由平等、主權在民","tip":"脫離英國、殖民地→獨立宣言；廢特權、法國→人權宣言"},{"a":"維也納會議（1814～1815）","b":"巴黎和會（1919）","diff":"維也納會議在拿破崙戰敗後由奧國主導、恢復舊王室；巴黎和會在一戰後由戰勝國主導，依十四點原則簽訂《凡爾賽條約》","tip":"拿破崙後＝維也納／正統均勢；一戰後＝巴黎／民族自決"},{"a":"門羅宣言（1823）","b":"十四點原則（1918）","diff":"門羅宣言反對歐洲干涉美洲事務；十四點原則是威爾遜提出的戰後和平方案，含民族自決、國際聯盟","tip":"「美洲是美洲人的」→門羅；「民族自決、國聯」→威爾遜"},{"a":"德意志統一","b":"義大利統一","diff":"德意志以普魯士為核心，靠關稅同盟與俾斯麥鐵血政策；義大利以薩丁尼亞為核心，靠建國三傑","tip":"俾斯麥、關稅同盟、威廉一世→德；馬志尼、加富爾、加里波底、收復羅馬→義"},{"a":"16～18世紀的殖民擴張","b":"19世紀帝國主義","diff":"前者由葡西荷英等海權國家以貿易掠奪為主、侵略沿海；後者由工業強國全面掌控殖民地內政、外交與經濟，深入亞非內陸","tip":"大航海時代＝香料、白銀；工業革命後＝原料、市場、瓜分非洲"},{"a":"三國同盟","b":"三國協約","diff":"三國同盟為德、奧、義（1882）；三國協約為英、法、俄（1907）；開戰後義大利倒戈到協約國","tip":"德奧義同盟、英法俄協約"},{"a":"三國同盟","b":"同盟國","diff":"三國同盟是戰前（1882）德、奧、義的結盟；同盟國是一戰交戰陣營，為德、奧、土耳其（鄂圖曼）、保加利亞，義大利已倒向協約國","tip":"戰前看「三國」有義；開打後同盟國＝德奧土保，沒有義"},{"a":"門羅宣言（1823）","b":"孤立主義（1920年代起）","diff":"門羅宣言是反對歐洲干涉美洲，使美國勢力深入拉丁美洲；孤立主義是一戰後美國不參與他國事務、拒入國聯、採關稅保護","tip":"門羅＝美洲是美洲人的（對外擋歐洲）；孤立＝美國不管別人（拒入國聯）"}],"terms":[{"term":"工業革命","def":"18世紀中期起源於英國的生產技術變革，以蒸汽動力機器取代人力，使工廠得以大規模生產。"},{"term":"蒸汽機","def":"18世紀後期由瓦特改良，先用於紡織業，19世紀初用於火車、汽船，是工業革命的關鍵動力。"},{"term":"社會主義","def":"主張由國家社會統籌生產工具並分配財富，以解決勞資對立與貧富差距；溫和派主張以改革、立法等和平手段。"},{"term":"共產主義","def":"馬克思提出的激進社會主義，主張以階級鬥爭、革命推翻資本主義，建立財產公有的無階級社會。"},{"term":"波士頓茶葉事件","def":"1773年北美殖民地居民反對英國徵稅，將英商茶葉倒入波士頓港，成為美國獨立的導火線。"},{"term":"三級會議","def":"法國由教士、貴族、平民三階級代表組成的會議；1789年路易十六為徵稅召開，引發大革命。"},{"term":"恐怖統治","def":"法國大革命走向激進時，羅伯斯比以斷頭臺大量處死被懷疑支持王室的異議分子。"},{"term":"拿破崙法典","def":"拿破崙頒布的法典，確認人民自由平等原則與信仰自由，體現法國大革命精神。"},{"term":"維也納會議","def":"1814～1815年拿破崙戰敗後由奧國主導的會議，以正統、均勢為原則，恢復各國舊王室。"},{"term":"門羅宣言","def":"1823年美國總統門羅提出，主張美洲事務由美洲人自行解決，反對歐洲國家干涉美洲。"},{"term":"民族主義","def":"民族是由擁有相同語言、文化或生活習慣的人因認同感而形成；19世紀主張一個民族建立一個國家，以增進民族利益"},{"term":"日耳曼邦聯","def":"維也納會議後，奧國與普魯士等使用德語的邦國組成的鬆散聯盟，以奧國實力最強"},{"term":"關稅同盟","def":"1834年普魯士號召德意志各邦成立，廢除內部關稅、統一稅制，奠定德意志統一的經濟基礎。"},{"term":"鐵血政策","def":"普魯士首相俾斯麥主張以武器（鐵）與戰爭（血）完成德意志統一，而非靠民主手段。"},{"term":"青年義大利黨","def":"馬志尼成立的團體，以「恢復古羅馬光榮」為號召，宣揚義大利民族意識、鼓吹統一"},{"term":"帝國主義","def":"一國利用強勢軍事或政治力量掠奪其他地區土地，或控制當地政治與經濟，以建立自身霸權的擴張行為。"},{"term":"社會達爾文主義","def":"引用達爾文生物演化觀點解釋人類社會，主張強者主宰世界，被用來合理化帝國主義侵略。"},{"term":"白種人的負擔","def":"英國詩人吉卜林1899年提出，認為白人負有教化落後民族的使命，被用來合理化帝國主義侵略"},{"term":"殖民地式經濟","def":"殖民者在殖民地發展熱帶栽培業與採礦業，生產經濟作物或工業原料，造成當地糧食不足、貧窮落後"},{"term":"歐洲火藥庫","def":"指20世紀初的巴爾幹半島，鄂圖曼衰弱後奧、俄在此競逐，民族宗教紛爭不斷。"},{"term":"雙元帝國","def":"兩個彼此獨立的君主國由同一人同時擔任君主的政體，最著名的是奧匈帝國（1867～1918）"},{"term":"無限制潛艇政策","def":"一戰期間德國以潛艇攻擊進入封鎖區的船隻，連中立國船隻也不例外，促使美國參戰。"},{"term":"十四點原則","def":"1918年美國總統威爾遜提出的戰後和平方案，包含民族自決、成立國際聯盟等主張。"},{"term":"凡爾賽條約","def":"巴黎和會中協約國與德國簽訂的條約，要求割地、賠款、限制軍備，令德國人民不滿。"},{"term":"國際聯盟","def":"1920年成立的維護世界和平組織，但美國因孤立主義未加入且缺乏武力，成效不彰。"},{"term":"孤立主義","def":"一戰後（1920年代起）美國因戰債難收、損失嚴重，不再積極參與國際事務：國會拒批《凡爾賽條約》、拒入國聯、採關稅保護。"}],"timeline":[{"time":"1769","event":"英國瓦特改良蒸汽機（18世紀後期），工業革命展開"},{"time":"1773","event":"波士頓茶葉事件"},{"time":"1776","event":"北美十三州發表《獨立宣言》"},{"time":"1789","event":"法國大革命爆發，攻陷巴士底監獄，發表《人權宣言》"},{"time":"1804","event":"拿破崙稱帝，建立法蘭西帝國"},{"time":"1814～1815","event":"維也納會議；1815年拿破崙兵敗滑鐵盧，日耳曼地區組成日耳曼邦聯，以奧國實力最強"},{"time":"1820年代","event":"拉丁美洲陸續獨立建國"},{"time":"1823","event":"美國發表《門羅宣言》"},{"time":"1834","event":"普魯士主導成立關稅同盟"},{"time":"1847","event":"賴比瑞亞宣布獨立，為非洲第一個獨立的共和國"},{"time":"1848","event":"馬克思發表《共產黨宣言》"},{"time":"1851","event":"英國倫敦舉辦首屆世界博覽會"},{"time":"19世紀後期","event":"歐洲列強瓜分非洲（柏林會議）"},{"time":"1858","event":"英國正式殖民印度"},{"time":"1861","event":"義大利王國成立"},{"time":"1866","event":"普奧戰爭，義大利趁機取得奧地利控制的威尼斯（威尼托）"},{"time":"1867","event":"奧地利給予匈牙利高度自治，奧匈帝國（雙元帝國）建立"},{"time":"1870～1871","event":"德法戰爭；義大利收復羅馬，德意志帝國成立"},{"time":"1882","event":"德、奧、義組成三國同盟"},{"time":"1885","event":"法國於清法戰爭後吞併越南"},{"time":"1898","event":"美西戰爭後簽訂《巴黎條約》，美國取得古巴、菲律賓、波多黎各"},{"time":"1907","event":"英、法、俄組成三國協約"},{"time":"1914","event":"塞拉耶佛事件，第一次世界大戰爆發"},{"time":"1917","event":"美國參戰；俄國爆發二月革命、十月革命"},{"time":"1918","event":"俄國退出戰爭；同盟國停戰，一戰結束"},{"time":"1919","event":"巴黎和會，簽訂《凡爾賽條約》；朝鮮受民族自決影響發動三一運動，宣布獨立"},{"time":"1920","event":"國際聯盟成立"}],"sources":[{"name":"《獨立宣言》","gist":"聯合的殖民地應為自由獨立的國家，解除對英國王室的效忠與政治聯繫。","clue":"「殖民地」「大不列顛」「生命、自由、追求幸福」→1776年美國"},{"name":"《人權宣言》","gist":"主權在民，保障公民自由、財產、安全和反抗壓迫的權利，廢除貴族教士特權。","clue":"「國民會議」「主權屬於國民」「廢除特權」→1789年法國大革命"},{"name":"《門羅宣言》","gist":"歐洲國家不應干涉美洲事務，否則美國將視為具敵意的行為。","clue":"「美洲只屬於美洲人」「南方的兄弟對抗西班牙」→1823年美國"},{"name":"《共產黨宣言》","gist":"資產階級握有生產工具，產生了無產的勞工階級，主張階級鬥爭。","clue":"「資本家、勞工階級、無產階級、財產公有」→工業革命後的社會主義"},{"name":"俾斯麥「鐵血」演說／漫畫","gist":"追求統一不能靠民主與言論，必須靠軍備與戰爭。","clue":"「鐵與血」「威廉一世」「關稅同盟」→19世紀中後期德意志統一"},{"name":"巴拿馬運河擋路獅漫畫（1888）","gist":"頭部為山姆大叔的獅子擋住歐洲國家人群，反對歐洲介入美洲運河事務。","clue":"「山姆大叔」「擋住歐洲人」「運河」→美國門羅主義與帝國主義擴張"},{"name":"吉卜林《白種人的負擔》（1899）","gist":"呼籲白種人挑起教化「野蠻」民族的責任；同名口號也被用於英國肥皂廣告。","clue":"「白種人的負擔」「野蠻的人們」→帝國主義以優越感合理化侵略"},{"name":"美國總統與德國政府的外交照會","gist":"美國要求德國停止襲擊客船，否則斷交；德國承諾客船不會成為目標，後於1917年違背承諾。","clue":"「停止襲擊客船」「斷交」「擊沉商船」→一戰德國潛艇政策，導致美國參戰"},{"name":"齊默爾曼電報（1917）","gist":"德國外交部長齊默爾曼邀墨西哥對美作戰，承諾歸還其舊有領土，遭英方攔截解密。","clue":"「德國外交部長」「墨西哥城」「1917年」→德國煽動墨西哥反美，促使美國參戰"},{"name":"威爾遜十四點原則","gist":"各民族有權自己決定歸屬與政府體制，並成立國際組織維護和平。","clue":"「民族自決」「國際聯盟」「巴黎和會」→一戰後1918～1919年"},{"name":"《和平餐桌》諷刺畫","gist":"侍者請德國客人入座，餐桌上卻只有柄鍬、炮彈與釘刺座椅，諷刺和會對德國形同懲罰。","clue":"「德國客人」「和平」「釘刺、炮彈」→巴黎和會與《凡爾賽條約》的嚴苛"},{"name":"梵蒂岡與義大利的條約摘要","gist":"梵蒂岡成為獨立國家，補償教廷失去教皇國的損失，教廷承認義大利以羅馬為首都。","clue":"「教皇國」「教廷承認羅馬為首都」→解決1870年義大利收復羅馬留下的問題"},{"name":"國際聯盟兔子與蛇漫畫","gist":"以軟弱的兔子代表國際聯盟，面對大蛇般的侵略者無能為力。","clue":"「兔子」「國際聯盟」「無法遏止侵略」→國聯缺乏武力、美國未加入"}]},{"unit":14,"part":"世界史","title":"第二次世界大戰與戰後秩序","summary":"學習戰間期蘇聯共產政權、經濟大恐慌與德義極權興起，第二次世界大戰的爆發經過，以及冷戰對峙、第三世界與冷戰結束；會考常以史料、漫畫、統計圖與形勢圖判斷事件、陣營與時序。","sections":[{"heading":"蘇聯共產政權的建立與發展","points":["一次大戰期間俄國戰場失利、經濟惡化，1917年二月革命推翻沙皇尼古拉二世，成立臨時政府，結束帝制","臨時政府致力政治改革，卻無力解決經濟困境，又持續參戰","列寧領導布爾什維克黨，以「和平、土地、麵包」為號召發動十月革命，推翻臨時政府，建立世界第一個共產政權","布爾什維克黨後改稱俄國共產黨；列寧實施獨裁專制、沒收私有財產，並於1918年與同盟國議和，退出一次大戰","1919年成立共產國際，策畫世界各地共產活動","1922年改國號為「蘇維埃社會主義共和國聯邦」，簡稱蘇聯","史達林推行計畫經濟，由國家統籌發展國防與重工業，蘇聯成為工業強國，但人民生活困苦；較未受經濟大恐慌波及"],"example":"記口訣：二月推沙皇、十月推臨時政府；列寧喊「和平、土地、麵包」，史達林搞計畫經濟。"},{"heading":"經濟大恐慌與羅斯福新政","points":["一戰期間美國供應協約國軍火物資，戰後又供應歐洲重建，掌握世界經濟主導權；歐洲勢力衰退，美國成為世界經濟強權","歐洲經濟復甦後美國商品供過於求；美國因孤立主義提高關稅保護國內產業，各國仿效形成關稅壁壘，國際貿易停頓","1929年10月24日紐約華爾街股市暴跌，稱「黑色星期四」；股市崩盤後公司、銀行、工廠倒閉，失業人口劇增","1930年美國通過《斯姆特霍利關稅法》大幅提高關稅，引發全球貿易戰，加深經濟大蕭條","美國從德國撤出資金，依賴美資付賠款的德國金融崩潰，1932年失業率約30%；經濟風暴席捲全球","1933年美國總統羅斯福推行新政：興建大型公共建設、增加就業，建立社會福利制度，並以「爐邊談話」向民眾喊話，經濟逐漸改善","大恐慌影響：各國採緊急措施擴大中央政府權力；共產黨擴大影響力","大恐慌促成德、義極權政治興起與日本軍國主義昂揚：日本加速侵略中國（發動九一八事變）"],"example":"統計圖上1929~1933年失業率暴增、就業人口與股市崩跌，就是經濟大恐慌（起點：1929年10月24日「黑色星期四」）。"},{"heading":"義、德極權政體的興起","points":["一次大戰後歐洲極權政治興起，強調國家榮譽與秩序，壓制人民自由，以蘇聯、義大利、德國為代表","法西斯主義主張崇拜領袖、極權政治並反共；德國納粹也屬法西斯主義","義大利雖為一次大戰戰勝國，但未獲太多利益、戰後經濟蕭條；墨索里尼成立法西斯黨，主張反共、恢復古羅馬光榮","法西斯黨「恢復古羅馬光榮」口號，義大利統一時的馬志尼也曾使用","1922年墨索里尼發動政變取得政權，迫使義大利國王任命他為首相；掌權後鎮壓反對分子，並加速侵略衣索比亞","1935年義大利受經濟大恐慌衝擊而入侵衣索比亞，使用生化武器；英法姑息、國聯制裁無效；1941年衣索比亞在英國協助下復國","德國為一次大戰戰敗國，戰時耗損加上苛刻的《凡爾賽條約》賠款，財政困難、濫發紙幣造成嚴重通貨膨脹，經濟與財政更加惡化","德國又受經濟大恐慌衝擊，加上共產黨活動，社會不安","希特勒領導納粹黨，以反共、恢復社會秩序、撕毀《凡爾賽條約》為號召，1933年透過選舉取得政權","希特勒掌權後積極發展經濟、重整軍備，廢除《凡爾賽條約》；納粹實施一黨專政，積極對外擴張","納粹抱持種族優越理論，迫害猶太人等少數族群並關押於集中營；戰爭中期在奧斯維辛等集中營進行大規模屠殺","三國極權掌權方式不同：列寧發動十月革命推翻臨時政府、墨索里尼發動政變、希特勒藉選舉合法掌權"],"example":"《安妮日記》記錄猶太少女一家躲避納粹迫害，最後被送往集中營。"},{"heading":"二戰前局勢與綏靖政策","points":["1930年代日、德、義對外擴張，以「反共」為名組成軸心國；「軸心國」名稱意指世界以柏林、羅馬、東京為軸心轉動","美國1920年代孤立主義盛行：拒加入國際聯盟、築關稅壁壘保護國內產業，旁觀國際事務","孤立主義造成國聯缺乏威信、助長經濟大恐慌、促成二戰爆發","英、法為避免重啟戰端採取姑息政策，助長侵略野心","亞洲：日本軍國主義興起，以中國為擴張目標，1937年發動盧溝橋事變（七七事變）","1938年德國併吞奧地利，英、法與德國簽訂《慕尼黑協定》，逼迫捷克割讓蘇臺德區","1939年德國毀約併吞捷克，並與蘇聯簽訂《德蘇互不侵犯條約》，密約協議瓜分波蘭","德國侵略順序：1938併吞奧地利→占領捷克蘇臺德區→1939併吞捷克→入侵波蘭","德蘇互不侵犯條約密約中，波羅的海三國（立陶宛、拉脫維亞、愛沙尼亞）被畫入蘇聯範圍並遭占領","1939年波蘭遭瓜分：西部為德國併吞區、中部為德國管轄的波蘭總督轄區、東部為蘇聯併吞區"],"example":"漫畫中希特勒與史達林假意互相脫帽致敬，地上倒著的「密約」受害者就是波蘭。"},{"heading":"第二次世界大戰的爆發與經過","points":["1939年德國入侵波蘭，英、法對德宣戰，二次大戰全面爆發；軸心國（德義日）對抗同盟國","各國參戰時段：英國1939~1945；義大利1940參戰、1943投降；蘇聯1941年中參戰；美國1941年底參戰","二戰歐洲戰場順序：1939入侵波蘭→1940攻陷法國→1940轟炸英國→1941攻擊蘇聯","前期德國以「閃電戰」攻陷荷、比、法並轟炸英國","法國一戰後興建馬其諾防線防範德國，1940年德軍繞道而入使其失去作用，衍生「馬其諾心態」一詞","德國空襲英國（1940年9月~1941年5月）連續轟炸倫敦，之後德軍目標轉往蘇聯與地中海","1941年希特勒毀棄《德蘇互不侵犯條約》攻擊蘇聯，開啟東線戰場；蘇聯宣傳將其與1812年敗於俄國的拿破崙相比","1942~1943年史達林格勒戰役，蘇聯與德軍激戰、傷亡近百萬人，是東線戰場的關鍵戰役","1941年底日本偷襲珍珠港，美國對日宣戰，太平洋戰爭爆發，歐亞戰場合而為一","後期：1943年盟軍自北非反攻，義大利投降；1944年盟軍諾曼第登陸，與蘇聯夾擊德國","諾曼第登陸：盟軍放棄最近但防衛最嚴密的加萊，改在諾曼第出其不意搶灘，約15萬聯軍、數千艘船艦參與","1942年奧本海默主持美國曼哈頓計畫，1945年完成首次核試爆（三位一體試驗），隨後原子彈用於結束戰爭","1945年盟軍攻入柏林、德國投降；8月美國在廣島、長崎投下原子彈，日本無條件投降","密蘇里號戰艦1945年舉行日本簽字投降儀式，1950年參與韓戰支援聯合國軍","戰時會議：1943年開羅會議由中、美、英召開，討論東亞問題，聲明日本須無條件投降，並將中國東北、臺灣、澎湖歸還中華民國","1945年雅爾達會議由美、英、蘇召開：決定德國由美英法蘇四國分區占領；蘇聯接收東歐部分地區，造成戰後共產勢力擴張","雅爾達會議以東歐部分地區換取蘇聯對日宣戰（翰林作：簽訂《雅爾達密約》，犧牲中國權益以換取）","雅爾達會議對戰後問題處理含糊，為近半世紀的東西分裂奠基，有人視為冷戰開端","1945年聯合國成立，總部設於紐約；安全理事會常任理事國（中美英法蘇）擁有否決權","聯合國安理會有權要求會員國提供武力制裁侵略國、組織維和部隊；並促進人權、衛生、經濟、文化、教育合作","國際聯盟（1920~1946，總部日內瓦）缺乏武力制裁侵略，只能道德譴責、集體制裁，曾派員調查九一八事變","聯合國（1945至今，總部紐約）可由會員國提供武力介入，安理會曾派兵介入韓戰支援南韓","聯合國的困境：常任理事國具否決權；小會員國多，容易影響決議"],"example":"投降順序口訣「義→德→日」；判斷圖例：英美同圖例＝1941年底珍珠港事變後。","fig":{"src":"../assets/fig/history/u14-s5.svg","cap":"第二次世界大戰後期盟軍的反攻"}},{"heading":"冷戰的形成與危機","points":["冷戰（1947~1991年）：雙方政治與思想理念歧異大並進行軍備競賽，但憂慮核子武器毀滅性而避免直接武力衝突，非戰非和","二戰後蘇聯共產勢力在東歐、亞洲擴張；1947年杜魯門主張支持抵抗外來勢力的自由人民（杜魯門主義），首開美國援助反共政權先例","美國隨後以經濟援助（馬歇爾計畫）援歐、重建歐洲，並在東亞建立圍堵防線","兩大陣營：美國與歐美民主國家組成北大西洋公約組織；蘇聯與東歐共產國家組成華沙公約組織","冷戰區域性組織：北約（美國主導，持續運作至今）、東南亞公約組織（亞洲版北約，1977年解散）、華約（蘇聯主導，1991年解散）","冷戰國際衝突順序：1948柏林危機→1949東西德分立→1961興建柏林圍牆→1962古巴危機","柏林危機：1948年蘇聯封鎖美英法控制的西柏林，西方盟國（美英）經由空中走廊空運補給援助物資；1949年蘇聯解除封鎖","1949年德國分裂為東、西德；1961年東德興建柏林圍牆","1989年柏林圍牆被推倒後，東、西德加速合併，1990年完成統一，兩德邊界改為綠化地帶","1960年前後美蘇關係緊張（如蘇聯宣傳反美圖像），1962年爆發古巴危機","古巴危機：1962年蘇聯在古巴建飛彈基地威脅美國，美國以海軍封鎖古巴，核戰一觸即發，最後蘇聯撤除基地","古巴危機後美、蘇政府開始建立溝通管道，冷戰漸趨緩和","奧本海默戰後主張防止核擴散、管控核技術，希望藉國際組織阻止美蘇核軍備競賽","區域衝突：韓戰、越戰與以阿衝突","以阿衝突：二戰後猶太人得美英支持在巴勒斯坦建立以色列，巴勒斯坦人被迫遷離，引起同為穆斯林的阿拉伯國家不滿","阿拉伯國家與以色列爆發多次戰爭；巴勒斯坦居民以和平、軍事等手段向以色列爭取權益，區域局勢動盪","1970年代阿拉伯國家對支持以色列的西方國家實施石油禁運，引發能源危機","以巴對比：以色列以猶太裔為主、國民所得高；巴勒斯坦（西岸、加薩）以穆斯林為主、所得偏低"],"example":"時序口訣：柏林危機1948→韓戰1950→古巴危機1962→美國退出越戰1973。","fig":{"src":"../assets/fig/history/u14-s6.svg","cap":"冷戰時期的兩大陣營（約 1950～1960 年代）"}},{"heading":"第三世界與冷戰結束","points":["二戰後亞、非殖民地陸續獨立，出現許多新興國家，但多半政局動盪不安、經濟貧窮落後","部分國家不願加入美蘇陣營，1955年亞非會議後推動不結盟運動，形成可與美蘇抗衡的第三世界","第三世界以亞、非、拉丁美洲為主，國力不強但數目眾多，在國際組織中扮演重要角色","第三世界在國際事務上相互合作，提出反帝國主義與反殖民主義訴求；1961年起定期舉辦不結盟運動峰會","國際組織分類：全球性（聯合國、國際聯盟）與區域性（北約、華約、東南亞國家協會等）","冷戰時代蘇聯與東歐共產國家忽視民生經濟，人民生活困苦","1985年戈巴契夫上臺推動改革，改善與西方關係、放寬對東歐的管控，但經濟未見成效；1980年代末東歐共產政權陸續瓦解","1989年波羅的海三國約200萬人手牽手組成600多公里人鍊爭取獨立；1990年起三國陸續宣布恢復獨立，開啟蘇聯解體之路","1989年柏林圍牆拆除，1990年東西德統一","1991年蘇聯加盟國獨立組成獨立國家國協，蘇聯解體，冷戰結束，世界由兩極走向多元","冷戰後形成多元並立的國際秩序，但各地仍因政治、經濟、宗教差異爆發衝突與恐怖攻擊，如2001年美國九一一事件"],"example":"1989年奧匈邊界「泛歐野餐」：東德人趁圍籬開放衝向西方，是東歐民主化的縮影。"}],"confusions":[{"a":"二月革命","b":"十月革命","diff":"二月革命推翻沙皇、成立臨時政府；十月革命由列寧推翻臨時政府，建立共產政權","tip":"推沙皇＝二月；布爾什維克、列寧＝十月"},{"a":"羅斯福新政","b":"十大建設","diff":"新政是1930年代美國羅斯福為因應經濟大蕭條，興建公共工程並建立社會福利；十大建設是1970年代蔣經國因應國際能源危機推行的重大基礎建設、發展重工業","tip":"1930年代＋經濟大恐慌＝新政；1970年代＋能源危機＋蔣經國＝十大建設"},{"a":"墨索里尼掌權","b":"希特勒掌權","diff":"墨索里尼1922年發動政變，迫使國王任命為首相；希特勒1933年藉國會選舉合法取得政權","tip":"義大利＝政變；德國＝選舉"},{"a":"姑息政策","b":"孤立主義","diff":"姑息政策是英、法對軸心國侵略一再退讓；孤立主義是美國不積極參與國際事務","tip":"英法姑息（慕尼黑協定）、美國孤立（不參加國聯、二戰初期旁觀）"},{"a":"開羅會議","b":"雅爾達會議","diff":"開羅會議（1943）由中美英討論戰後亞洲秩序；雅爾達會議（1945）由美英蘇決定分區占領德國並換取蘇聯對日宣戰","tip":"有中國與會＝開羅；蘇聯要東北權益、出兵對日＝雅爾達"},{"a":"國際聯盟","b":"聯合國","diff":"國聯1920年依十四點原則成立（1920~1946，總部日內瓦），美國未加入且缺乏武力，只能道德譴責、集體制裁；聯合國1945年成立（總部紐約），安理會可要求會員國提供武力、組維和部隊","tip":"日內瓦、無武力＝國聯；紐約、否決權＝聯合國"},{"a":"北大西洋公約組織","b":"華沙公約組織","diff":"北約由美國與歐美民主國家組成，屬反共陣營；華沙公約由蘇聯與東歐共產國家組成","tip":"北約＝美國帶頭；華約＝蘇聯帶頭"},{"a":"柏林危機","b":"古巴危機","diff":"柏林危機是1948年蘇聯封鎖西柏林；古巴危機是1962年蘇聯在古巴建飛彈基地威脅美國","tip":"切斷水陸交通、空運物資＝柏林；飛彈基地、海軍封鎖＝古巴"}],"terms":[{"term":"布爾什維克黨","def":"列寧領導的俄國共產黨派（後改稱俄國共產黨），1917年發動十月革命推翻臨時政府，建立世界上第一個共產政權。"},{"term":"共產國際","def":"列寧於1919年成立的組織，策畫與支援世界各地的共產活動，擴大共產勢力。"},{"term":"計畫經濟","def":"由國家統籌規劃生產與分配的經濟制度；史達林以此發展國防與重工業，使蘇聯成為工業強國。"},{"term":"經濟大恐慌","def":"1929年美國紐約股市崩盤引發的全球性經濟危機，銀行工廠倒閉、失業人口劇增。"},{"term":"黑色星期四","def":"1929年10月24日美國紐約華爾街股市暴跌，揭開經濟大恐慌序幕，因當天為星期四而得名。"},{"term":"斯姆特霍利關稅法","def":"1930年美國通過的法案，大幅提高進口商品關稅以保護國內產業，引發各國報復與全球貿易戰。"},{"term":"新政","def":"1933年美國總統羅斯福推行的政策，以興建大型公共建設提升就業率，改善大恐慌的衝擊。"},{"term":"法西斯黨","def":"墨索里尼在義大利成立的政黨，主張反共、恢復古羅馬光榮，發動政變取得政權建立極權統治。"},{"term":"納粹黨","def":"希特勒領導的德國政黨，以反共、撕毀《凡爾賽條約》為號召，1933年執政後實施一黨專政並迫害猶太人。"},{"term":"集中營","def":"納粹德國在占領區設立的拘押場所，關押猶太人、異議分子等，進行迫害與屠殺。"},{"term":"軸心國","def":"1930年代德、義、日以「反共」為名結成的同盟，是二次大戰中對抗同盟國的陣營。"},{"term":"姑息政策","def":"英、法為避免重啟戰端，對軸心國侵略一再退讓的政策，如簽訂《慕尼黑協定》，反助長其野心。"},{"term":"慕尼黑協定","def":"1938年英、法與德國簽訂的協定，逼迫捷克將蘇臺德區割讓給德國，是姑息政策的代表。"},{"term":"德蘇互不侵犯條約","def":"1939年德國與蘇聯簽訂的條約，密約協議瓜分波蘭；1941年德國毀約進攻蘇聯。"},{"term":"波羅的海三國","def":"立陶宛、拉脫維亞、愛沙尼亞，1940年代遭蘇聯併吞，1990年起陸續宣布恢復獨立。"},{"term":"馬其諾防線","def":"法國在一次大戰後沿德法邊境興建的碉堡防線，1940年德軍繞道入侵法國而失去作用。"},{"term":"珍珠港事變","def":"1941年底日本偷襲美國在夏威夷的海軍基地，美國因此對日宣戰，太平洋戰爭爆發。"},{"term":"曼哈頓計畫","def":"二戰期間美國研發原子彈的祕密計畫，1942年由奧本海默主持，1945年成功試爆並投彈日本。"},{"term":"雅爾達會議","def":"1945年美英蘇在蘇聯雅爾達召開，決定戰後分區占領德國，並同意蘇聯接收東歐部分地區換取對日宣戰。"},{"term":"雅爾達密約","def":"1945年雅爾達會議中美、英與蘇聯簽訂的祕密協定，犧牲中國權益，以換取蘇聯出兵對日宣戰。"},{"term":"聯合國","def":"1945年成立、總部設於紐約的國際組織，安理會常任理事國擁有否決權，可組織維和部隊。"},{"term":"安全理事會","def":"聯合國維護和平的核心機構，可要求會員國提供武力制裁侵略國、組織維和部隊；中、美、英、法、蘇（今俄羅斯）為常任理事國，擁有否決權。"},{"term":"冷戰","def":"二戰後至1991年，美蘇兩大陣營進行軍備競賽但避免直接武力衝突的「非戰非和」對峙局面。"},{"term":"杜魯門主義","def":"1947年美國總統杜魯門提出支持抵抗共產勢力的自由國家，開啟美國援助反共政權、圍堵共產主義的政策。"},{"term":"馬歇爾計畫","def":"二戰後美國對歐洲國家提供經濟援助協助重建，以防範共產勢力擴張。"},{"term":"柏林圍牆","def":"1961年東德為阻止人民逃往西柏林興建的圍牆，1989年拆除，象徵冷戰結束。"},{"term":"以阿衝突","def":"二戰後以色列在巴勒斯坦建國，巴勒斯坦人被迫遷離，阿拉伯國家與以色列爆發多次戰爭的長期衝突。"},{"term":"第三世界","def":"二戰後亞、非、拉丁美洲新興國家不願加入美蘇陣營，推動不結盟運動所形成的第三勢力。"},{"term":"獨立國家國協","def":"1991年蘇聯加盟國陸續獨立後組成的組織，蘇聯隨之解體，冷戰正式結束。"}],"timeline":[{"time":"1917","event":"俄國二月革命推翻沙皇；列寧發動十月革命建立共產政權；美國加入一次大戰"},{"time":"1919","event":"列寧成立共產國際；巴黎和會簽訂《凡爾賽條約》"},{"time":"1922","event":"俄國改國號為蘇維埃社會主義共和國聯邦（蘇聯）；墨索里尼發動政變，迫使義大利國王任命他為首相"},{"time":"1929","event":"美國紐約股市崩盤（10月24日黑色星期四），經濟大恐慌席捲全球"},{"time":"1930","event":"美國通過《斯姆特霍利關稅法》提高關稅，引發全球貿易戰"},{"time":"1933","event":"羅斯福推行新政；希特勒領導納粹黨取得德國政權"},{"time":"1935","event":"義大利入侵衣索比亞，國際聯盟制裁無效"},{"time":"1936","event":"希特勒毀棄《凡爾賽條約》，重整軍備"},{"time":"1937","event":"日本發動盧溝橋事變（七七事變），中日戰爭爆發"},{"time":"1938","event":"德國併吞奧地利；英法德簽訂《慕尼黑協定》，捷克割讓蘇臺德區"},{"time":"1939","event":"德蘇簽訂互不侵犯條約；德國入侵波蘭，二次大戰全面爆發"},{"time":"1940","event":"德國以閃電戰攻陷法國，並空襲英國"},{"time":"1941","event":"德國毀約進攻蘇聯；年底日本偷襲珍珠港，美國參戰"},{"time":"1942~1943","event":"史達林格勒戰役，蘇聯擊敗德軍"},{"time":"1943","event":"義大利投降；中美英召開開羅會議"},{"time":"1944","event":"盟軍諾曼第登陸，與蘇聯夾擊德國"},{"time":"1945","event":"雅爾達會議；德國投降；美國投下原子彈，日本投降；聯合國成立"},{"time":"1947","event":"美國總統杜魯門提出援助反共國家的主張，冷戰展開"},{"time":"1948","event":"猶太人在巴勒斯坦建立以色列，以阿衝突展開"},{"time":"1948~1949","event":"柏林危機：蘇聯封鎖西柏林，1949年德國分裂為東、西德，北約成立"},{"time":"1950","event":"韓戰爆發"},{"time":"1955","event":"亞非會議召開，第三世界國家推動不結盟運動；華沙公約組織成立"},{"time":"1961","event":"東德興建柏林圍牆；第三世界國家開始定期舉辦不結盟運動峰會"},{"time":"1962","event":"古巴危機：蘇聯在古巴建飛彈基地，最後撤除"},{"time":"1967","event":"以阿戰爭，以色列占領西奈半島、戈蘭高地等地"},{"time":"1985","event":"戈巴契夫上臺推動改革，放寬對東歐的控制"},{"time":"1989~1990","event":"柏林圍牆拆除、東歐共產政權瓦解；1989年波羅的海三國人民組成人鍊爭取脫離蘇聯獨立；1990年東西德統一"},{"time":"1991","event":"蘇聯解體，組成獨立國家國協，冷戰結束；華沙公約組織解散"},{"time":"2001","event":"美國發生九一一恐怖攻擊事件"}],"sources":[{"name":"納粹「工作和麵包」選舉海報","gist":"宣稱元首的重建政策使人民收入較1932年增加，呼籲投票給希特勒。","clue":"元首、收入成長、1932年→希特勒納粹黨1930年代選舉宣傳"},{"name":"「美國高枕無憂、歐洲重病」漫畫","gist":"歐洲病床上患者罹患希特勒炎、法西斯熱、史達林癢等病，美國卻安睡一旁。","clue":"美國袖手旁觀歐洲極權興起→戰間期孤立主義"},{"name":"〈帝國主義侵略下的衣索比亞〉","gist":"衣索比亞19世紀末擊退義大利，1935年再遭義大利入侵，國聯制裁無效，1941年復國。","clue":"1935、義大利、國聯無效、英法姑息→墨索里尼對外擴張"},{"name":"1930年代德國向外侵略示意圖","gist":"標示德國1938年併吞奧地利、占領蘇臺德區，1939年併吞捷克的範圍。","clue":"奧地利、蘇臺德區、捷克依序被併→二戰爆發前德國擴張、英法姑息"},{"name":"希特勒與史達林「密約」漫畫","gist":"兩人假意友好互相致敬，地上倒著一名受害者。","clue":"希特勒＋史達林＋密約→1939年《德蘇互不侵犯條約》瓜分波蘭"},{"name":"1939年9月2日《臺灣新民報》號外","gist":"報導德、波兩軍開戰，英、波發動相互援助條約。","clue":"1939年9月、德國與波蘭開戰→二戰歐戰爆發"},{"name":"蘇聯「過去是……將來也是！」宣傳海報","gist":"以刺刀刺退拿破崙，比喻希特勒也將同樣被擊敗。","clue":"拿破崙＋希特勒＋俄文→1941年德國毀約攻蘇、蘇聯參戰"},{"name":"二戰形勢圖圖例","gist":"以某國角度把各國分為敵對國、友好國、中立國。","clue":"日本角度英美同圖例→1941年底後；德國角度英蘇不同圖例→1941年德國攻蘇前"},{"name":"《安妮日記》","gist":"荷蘭猶太少女安妮一家躲藏於閣樓，最後被捕送往納粹集中營。","clue":"猶太人、荷蘭被占領、集中營→納粹德國對外擴張與種族迫害（二戰）"},{"name":"第二次世界大戰全球形勢示意圖","gist":"標示珍珠港事件、諾曼第登陸、攻陷柏林、原子彈與日本最大勢力範圍。","clue":"日本勢力範圍涵蓋東南亞、太平洋島嶼；盟軍反攻箭頭→二戰後期"},{"name":"開羅會議決議","gist":"中、美、英聲明日本須無條件投降，並將中國東北、臺灣、澎湖歸還中華民國。","clue":"1943年、中美英、東北臺澎歸還→開羅會議"},{"name":"雅爾達會議討論","gist":"蘇聯要求中國東北權益才出兵對日，美英同意先達成書面協議再說服蔣中正。","clue":"蔣中正、對德對日作戰、東北權益、出兵→雅爾達會議（甲蘇聯、乙美英）"},{"name":"奧本海默「我成為死神，世界的毀滅者」","gist":"曼哈頓計畫主持人形容首次核試爆的毀滅性，戰後主張防止核擴散。","clue":"曼哈頓計畫、三位一體試驗→原子彈結束二戰；核擴散→冷戰軍備競賽"},{"name":"四國分區占領德國圖","gist":"德國與柏林市各分為美、英、法、蘇四個占領區，柏林位於蘇聯占領區內。","clue":"西柏林被蘇占區包圍→柏林危機時美英須空運物資"},{"name":"杜魯門1947年演說","gist":"美國須支持抵抗少數武裝團體或外來勢力征服的自由人民。","clue":"1947、杜魯門、支持自由人民→美國圍堵共產、冷戰開始"},{"name":"柏林封鎖演說","gist":"蘇聯指控英美法在西部占領區實施貨幣改革，宣布切斷對西柏林的交通。","clue":"貨幣改革、切斷西部水陸交通、西柏林→1948年柏林危機"},{"name":"中央通訊社柏林空中走廊地圖","gist":"標示東、西德分界與通往西柏林的空中走廊、公路。","clue":"東德、西德、空中走廊→柏林危機空運補給"},{"name":"美蘇冷戰示意圖（NATO老鷹與WARSAW熊）","gist":"以老鷹代表北大西洋公約組織、熊代表華沙公約組織，彼此對峙。","clue":"NATO對WARSAW、鷹對熊、戰車對峙→冷戰兩大陣營"},{"name":"冷戰時代兩大陣營分布示意圖","gist":"標示北約、華約、其他共產國家與其他美國盟邦的分布。","clue":"西歐、北美屬北約；蘇聯、東歐屬華約；中國、蒙古、北韓為其他共產國家"},{"name":"二戰後亞、非新興國家分布圖","gist":"標示1945年以後在亞洲、非洲獨立的國家。","clue":"二戰後殖民地獨立、新興國家→第三世界"},{"name":"古巴危機信函","gist":"一國不滿對方包圍部署飛彈；另一國要求停止在古巴建飛彈基地。","clue":"古巴、飛彈基地→1962年古巴危機（蘇聯 vs 美國）"},{"name":"古巴危機美蘇角力漫畫","gist":"美、蘇領導人坐在核彈上比腕力，互不相讓。","clue":"美蘇對峙、核武、1962年→古巴危機"},{"name":"1967年以阿戰爭後以色列占領形勢圖","gist":"標示以色列占領的加薩走廊、西奈半島、戈蘭高地等地，西奈半島1982年歸還埃及。","clue":"以色列、巴勒斯坦、耶路撒冷→以阿衝突"},{"name":"〈波羅的海之路〉","gist":"波羅的海三國1939年被畫入蘇聯範圍，1989年以人鍊爭取獨立，1990年起宣布恢復獨立。","clue":"立陶宛、拉脫維亞、愛沙尼亞、人鍊、1989→蘇聯瓦解、冷戰結束"},{"name":"梅克爾談柏林圍牆","gist":"柏林圍牆的歷史告訴我們，沒有一堵限制自由的牆無法打破。","clue":"柏林圍牆、分隔人們→冷戰美蘇陣營對峙的象徵"},{"name":"〈攻不破的城牆？從來沒有〉","gist":"以萬里長城、馬其諾防線、柏林圍牆、以色列邊境牆說明人造屏障終被突破。","clue":"馬其諾防線→二戰法國；柏林圍牆→冷戰；以色列邊境牆、哈瑪斯→以阿衝突"}]}];
